import struct
from collections.abc import Iterator

HEADER_STRUCT = struct.Struct("!I")


class FrameTooLargeError(ValueError):
    pass


class LengthPrefixedDecoder:
    def __init__(self, max_frame_bytes: int = 1024 * 1024) -> None:
        if max_frame_bytes <= 0:
            raise ValueError("max_frame_bytes must be positive")
        self._max_frame_bytes = max_frame_bytes
        self._buf = bytearray()

    @property
    def buffered_bytes(self) -> int:
        return len(self._buf)

    def feed(self, chunk: bytes | bytearray | memoryview) -> Iterator[memoryview]:
        if not chunk:
            return
        self._buf.extend(chunk)
        offset = 0
        total = len(self._buf)
        view = memoryview(self._buf)
        try:
            while offset + HEADER_STRUCT.size <= total:
                (frame_len,) = HEADER_STRUCT.unpack_from(view, offset)
                if frame_len > self._max_frame_bytes:
                    self._buf.clear()
                    raise FrameTooLargeError(
                        f"frame length {frame_len} exceeds limit {self._max_frame_bytes}"
                    )
                end = offset + HEADER_STRUCT.size + frame_len
                if end > total:
                    break
                payload = view[offset + HEADER_STRUCT.size : end]
                offset = end
                try:
                    yield payload
                finally:
                    payload.release()
        finally:
            view.release()
            if offset:
                del self._buf[:offset]
