use std::marker::PhantomData;

pub struct Unverified;
pub struct Verified;

#[derive(Debug)]
pub enum AuthError {
    Malformed,
    BadSignature,
}

pub struct SessionToken<State> {
    subject: String,
    scopes: Vec<String>,
    signature: Vec<u8>,
    _state: PhantomData<fn() -> State>,
}

impl SessionToken<Unverified> {
    pub fn parse_wire(frame: &str, signature: Vec<u8>) -> Result<Self, AuthError> {
        let (sub, raw_scopes) = frame.split_once('|').ok_or(AuthError::Malformed)?;
        if sub.is_empty() {
            return Err(AuthError::Malformed);
        }
        let scopes = raw_scopes
            .split(',')
            .filter(|s| !s.is_empty())
            .map(str::to_owned)
            .collect();
        Ok(Self {
            subject: sub.to_owned(),
            scopes,
            signature,
            _state: PhantomData,
        })
    }

    pub fn verify(self, expected_mac: &[u8]) -> Result<SessionToken<Verified>, AuthError> {
        if self.signature.len() != expected_mac.len()
            || self
                .signature
                .iter()
                .zip(expected_mac)
                .fold(0u8, |acc, (a, b)| acc | (a ^ b))
                != 0
        {
            return Err(AuthError::BadSignature);
        }
        Ok(SessionToken {
            subject: self.subject,
            scopes: self.scopes,
            signature: self.signature,
            _state: PhantomData,
        })
    }
}

impl SessionToken<Verified> {
    pub fn subject(&self) -> &str {
        &self.subject
    }

    pub fn scopes(&self) -> &[String] {
        &self.scopes
    }
}
