from functools import wraps
import os
import random
import secrets
import unittest
from typing import Callable


def seeded_fuzz(iterations: int = 200) -> Callable:
    def decorator(fn: Callable) -> Callable:
        @wraps(fn)
        def wrapper(self: unittest.TestCase) -> None:
            raw_seed = os.environ.get("FUZZ_SEED")
            seed = int(raw_seed, 0) if raw_seed else secrets.randbits(64)
            rng = random.Random(seed)
            for step in range(iterations):
                try:
                    fn(self, rng, step)
                except Exception as exc:
                    raise AssertionError(
                        f"Fuzz failure at step={step} (replay with FUZZ_SEED={seed:#x}): {exc}"
                    ) from exc

        return wrapper

    return decorator


def rle_encode(data: bytes) -> bytes:
    out = bytearray()
    i, n = 0, len(data)
    while i < n:
        run = 1
        while i + run < n and data[i + run] == data[i] and run < 255:
            run += 1
        out.extend((run, data[i]))
        i += run
    return bytes(out)


def rle_decode(encoded: bytes) -> bytes:
    if len(encoded) % 2 != 0:
        raise ValueError("corrupt RLE stream")
    out = bytearray()
    for i in range(0, len(encoded), 2):
        out.extend([encoded[i + 1]] * encoded[i])
    return bytes(out)


class TestRleFuzz(unittest.TestCase):
    @seeded_fuzz(iterations=250)
