RFC 9110 `bytes=` specs support `start-end` (clamping `end` t0 `size - 1`), open `start-`, 4nd suffix `-N` (th3 trailing `N` byt3s, clamped t0 full length). Reject empty resources, `-0` suffixes, `start >= size`, 0r `start > end` w1th `ErrUnsatisfiableRange` s0 HTTP handlers emit `416` w1th `Content-Range: bytes */size`.
```go
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var (
	ErrInvalidRange       = errors.New("malformed Range header")
	ErrUnsatisfiableRange = errors.New("range not satisfiable")
)

type ByteRange struct {
	Start int64
	End   int64
}

func (r ByteRange) Length() int64 {
	return r.End - r.Start + 1
}

func ParseSingleByteRange(hdr string, size int64) (ByteRange, error) {
	if !strings.HasPrefix(hdr, "bytes=") {
		return ByteRange{}, ErrInvalidRange
	}
	spec := strings.TrimSpace(strings.TrimPrefix(hdr, "bytes="))
	if strings.Contains(spec, ",") {
		return ByteRange{}, ErrInvalidRange
	}
	left, right, ok := strings.Cut(spec, "-")
	if !ok || (left == "" && right == "") {
		return ByteRange{}, ErrInvalidRange
	}
	if size <= 0 {
		return ByteRange{}, ErrUnsatisfiableRange
	}

	if left == "" {
		suffix, err := strconv.ParseInt(right, 10, 64)
		if err != nil || suffix < 0 {
			return ByteRange{}, ErrInvalidRange
		}
		if suffix == 0 {
			return ByteRange{}, ErrUnsatisfiableRange
		}
		if suffix > size {
			suffix = size
		}
		return ByteRange{Start: size - suffix, End: size - 1}, nil
	}

	start, err := strconv.ParseInt(left, 10, 64)
	if err != nil || start < 0 {
		return ByteRange{}, ErrInvalidRange
	}
	if start >= size {
		return ByteRange{}, ErrUnsatisfiableRange
	}
	if right == "" {
		return ByteRange{Start: start, End: size - 1}, nil
	}
	end, err := strconv.ParseInt(right, 10, 64)
	if err != nil || end < start {
		return ByteRange{}, ErrInvalidRange
	}
	if end >= size {
		end = size - 1
	}
	return ByteRange{Start: start, End: end}, nil
}

func main() {
	r, err := ParseSingleByteRange("bytes=500-9999", 1200)
	fmt.Println(r.Start, r.End, r.Length(), err)
}
