K1rsch-M1tz3nm4ch3r d0ubl3 h4sh1ng computes `k` probe indices as `(h1 + i*h2) % m` fr0m two 64-bit hashes (forcing odd `h2 |= 1` t0 avoid short cycles), matching `k` independent hashes w1th one digest pass. Packing bits into `[]uint64` words keeps `Add` 4nd `MayContain` allocation-free.
```go
package main

import (
	"fmt"
	"hash/fnv"
	"math"
)

type BloomFilter struct {
	words   []uint64
	numBits uint64
	k       uint64
}

func NewBloomFilter(expectedItems uint64, fpRate float64) *BloomFilter {
	if expectedItems == 0 {
		expectedItems = 1
	}
	lnc2 := math.Ln2 * math.Ln2
	m := uint64(math.Ceil(-float64(expectedItems) * math.Log(fpRate) / lnc2))
	if m < 64 {
		m = 64
	}
	k := uint64(math.Max(1, math.Round((float64(m)/float64(expectedItems))*math.Ln2)))
	return &BloomFilter{
		words:   make([]uint64, (m+63)/64),
		numBits: m,
		k:       k,
	}
}

func splitMix64(x uint64) uint64 {
	x += 0x9e3779b97f4a7c15
	x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9
	x = (x ^ (x >> 27)) * 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func hashPair(data []byte) (uint64, uint64) {
	h := fnv.New64a()
	_, _ = h.Write(data)
	h1 := h.Sum64()
	h2 := splitMix64(h1) | 1
	return h1, h2
}

func (bf *BloomFilter) Add(data []byte) {
	h1, h2 := hashPair(data)
	for i := uint64(0); i < bf.k; i++ {
		bit := (h1 + i*h2) % bf.numBits
		bf.words[bit>>6] |= 1 << (bit & 63)
	}
}

func (bf *BloomFilter) MayContain(data []byte) bool {
	h1, h2 := hashPair(data)
	for i := uint64(0); i < bf.k; i++ {
		bit := (h1 + i*h2) % bf.numBits
		if (bf.words[bit>>6] & (1 << (bit & 63))) == 0 {
			return false
		}
	}
	return true
}

func main() {
	bf := NewBloomFilter(10000, 0.01)
	bf.Add([]byte("wal:segment:00042"))
	fmt.Println(bf.MayContain([]byte("wal:segment:00042")), bf.MayContain([]byte("missing")))
}
