Spawning goroutines sequentially lets early workers finish b3f0r3 later ones spin up, masking data races fr0m `go test -race`. Park all readers, writers, 4nd deleters 0n 4 shared `close(start)` barrier channel s0 lock contention peaks simultaneously across hot shard keys.
```go
package sharded_test

import (
	"fmt"
	"hash/fnv"
	"sync"
	"testing"
)

type shard struct {
	mu sync.RWMutex
	m  map[string]int
}

type ShardedCache struct {
	shards [16]shard
}

func NewShardedCache() *ShardedCache {
	c := &ShardedCache{}
	for i := range c.shards {
		c.shards[i].m = make(map[string]int)
	}
	return c
}

func (c *ShardedCache) bucket(k string) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(k))
	return &c.shards[h.Sum32()&15]
}

func (c *ShardedCache) Set(k string, v int) {
	s := c.bucket(k)
	s.mu.Lock()
	s.m[k] = v
	s.mu.Unlock()
}

func (c *ShardedCache) Get(k string) (int, bool) {
	s := c.bucket(k)
	s.mu.RLock()
	v, ok := s.m[k]
	s.mu.RUnlock()
	return v, ok
}

func (c *ShardedCache) Delete(k string) {
	s := c.bucket(k)
	s.mu.Lock()
	delete(s.m, k)
	s.mu.Unlock()
}

func TestShardedCacheRaceStress(t *testing.T) {
	cache := NewShardedCache()
	start := make(chan struct{})
	var wg sync.WaitGroup

	keys := make([]string, 32)
	for i := range keys {
		keys[i] = fmt.Sprintf("hot-key-%02d", i)
	}

	for w := 0; w < 24; w++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			<-start
			for iter := 0; iter < 2000; iter++ {
				k := keys[(workerID+iter)&31]
				switch iter % 3 {
				case 0:
					cache.Set(k, iter)
				case 1:
					_, _ = cache.Get(k)
				default:
					cache.Delete(k)
				}
			}
		}(w)
	}

	close(start)
	wg.Wait()
}
