Linux clamps `SO_RCVBUF` against `net.core.rmem_max` silently without returning `-1` (doubling th3 granted value f0r skb overhead), s0 always inspect `getsockopt` after `setsockopt`. Retry `recvfrom` wh3n `errno == EINTR` s0 POSIX signals d0n't kill th3 datagram loop.
```c
#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

int open_udp_receiver(uint16_t port, int requested_rcvbuf, int *granted_rcvbuf) {
    int fd = socket(AF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    if (fd < 0) {
        return -1;
    }

    if (setsockopt(fd, SOL_SOCKET, SO_RCVBUF, &requested_rcvbuf, sizeof(requested_rcvbuf)) < 0) {
        close(fd);
        return -1;
    }

    socklen_t optlen = sizeof(*granted_rcvbuf);
    if (getsockopt(fd, SOL_SOCKET, SO_RCVBUF, granted_rcvbuf, &optlen) < 0) {
        close(fd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);

    if (bind(fd, (const struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

ssize_t recv_datagram_eintr(int fd, void *buf, size_t cap, struct sockaddr_in *peer) {
    for (;;) {
        socklen_t peer_len = sizeof(*peer);
        ssize_t n = recvfrom(fd, buf, cap, 0, (struct sockaddr *)peer, &peer_len);
        if (n < 0 && errno == EINTR) {
            continue;
        }
        return n;
    }
}

int main(void) {
    int granted = 0;
    int fd = open_udp_receiver(0, 4 * 1024 * 1024, &granted);
    if (fd < 0) {
        perror("open_udp_receiver");
        return 1;
    }
    printf("kernel granted SO_RCVBUF=%d bytes\n", granted);
    close(fd);
    return 0;
}
