#[derive(Debug, Clone, Copy)]
pub struct FrameView<'buf> {
    raw: &'buf [u8],
    header_len: usize,
}

impl<'buf> FrameView<'buf> {
    pub fn parse(raw: &'buf [u8]) -> Option<Self> {
        let &hdr_len = raw.first()?;
        let header_len = usize::from(hdr_len);
        if header_len == 0 || header_len > raw.len() {
            return None;
        }
        Some(Self { raw, header_len })
    }

    pub fn header(&self) -> &'buf [u8] {
        &self.raw[..self.header_len]
    }

    pub fn payload(&self) -> &'buf [u8] {
        &self.raw[self.header_len..]
    }
}

fn main() {
    let packet = [4_u8, b'P', b'I', b'N', b'G', b'd', b'a', b't', b'a'];
    let body: &[u8] = {
        let view = FrameView::parse(&packet).expect("valid frame");
        view.payload()
    };
    assert_eq!(body, b"data");
}
