package scheduler

import (
	"container/heap"
	"time"
)

type Job[T any] struct {
	Payload T
	RunAt   time.Time
	index   int
}

type jobHeap[T any] []*Job[T]

func (h jobHeap[T]) Len() int           { return len(h) }
func (h jobHeap[T]) Less(i, j int) bool { return h[i].RunAt.Before(h[j].RunAt) }
func (h jobHeap[T]) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
	h[i].index = i
	h[j].index = j
}
func (h *jobHeap[T]) Push(x any) {
	item := x.(*Job[T])
	item.index = len(*h)
	*h = append(*h, item)
}
func (h *jobHeap[T]) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	item.index = -1
	*h = old[:n-1]
	return item
}

type PriorityScheduler[T any] struct {
	pq jobHeap[T]
}

func New[T any]() *PriorityScheduler[T] {
	s := &PriorityScheduler[T]{}
	heap.Init(&s.pq)
	return s
}

func (s *PriorityScheduler[T]) PushJob(payload T, runAt time.Time) *Job[T] {
	job := &Job[T]{Payload: payload, RunAt: runAt}
	heap.Push(&s.pq, job)
	return job
}

func (s *PriorityScheduler[T]) PopJob() (*Job[T], bool) {
	if len(s.pq) == 0 {
		return nil, false
	}
	return heap.Pop(&s.pq).(*Job[T]), true
}

func (s *PriorityScheduler[T]) Reschedule(job *Job[T], nextRunAt time.Time) bool {
	if job.index < 0 || job.index >= len(s.pq) {
		return false
	}
	job.RunAt = nextRunAt
	heap.Fix(&s.pq, job.index)
	return true
}
