func getWithRetry(ctx context.Context, client *http.Client, url string, maxAttempts int, baseDelay time.Duration) ([]byte, error) {
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		if err != nil {
			return nil, err
		}
		resp, err := client.Do(req)
		if err == nil {
			body, readErr := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				return body, readErr
			}
			if resp.StatusCode < 500 || attempt == maxAttempts {
				return nil, errors.New(resp.Status)
			}
		} else if attempt == maxAttempts {
			return nil, err
		}
		timer := time.NewTimer(baseDelay * time.Duration(1<<(attempt-1)))
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, ctx.Err()
		case <-timer.C:
		}
	}
	return nil, errors.New("unreachable")
}

func TestGetWithRetry_RecoversAndHonorsCancel(t *testing.T) {
	var hits atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if hits.Add(1) <= 2 {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ready"))
	}))
	defer srv.Close()

	body, err := getWithRetry(context.Background(), srv.Client(), srv.URL, 4, 2*time.Millisecond)
	if err != nil || string(body) != "ready" {
		t.Fatalf("got (%q, %v), want (\"ready\", nil)", body, err)
	}
	if got := hits.Load(); got != 3 {
		t.Fatalf("got %d attempts, want 3", got)
	}

	hits.Store(0)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := getWithRetry(ctx, srv.Client(), srv.URL, 3, 5*time.Millisecond); !errors.Is(err, context.Canceled) {
		t.Fatalf("got err=%v, want context.Canceled", err)
	}
}
