```rust
use std::future::Future;
use std::time::Duration;
use tokio::sync::mpsc;
use tokio::time::{self, MissedTickBehavior};
use tokio_util::sync::CancellationToken;

pub async fn run_batch_worker<T, F, Fut>(
    mut rx: mpsc::Receiver<T>,
    cancel: CancellationToken,
    max_batch: usize,
    flush_every: Duration,
    mut flush_fn: F,
) where
    F: FnMut(Vec<T>) -> Fut,
    Fut: Future<Output = ()>,
{
    let cap = max_batch.max(1);
    let mut batch = Vec::with_capacity(cap);
    let mut ticker = time::interval(flush_every);
    ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);
    ticker.tick().await;

    loop {
        tokio::select! {
            biased;
            _ = cancel.cancelled() => {
                rx.close();
                while let Ok(item) = rx.try_recv() {
                    batch.push(item);
                    if batch.len() >= cap {
                        flush_fn(std::mem::replace(&mut batch, Vec::with_capacity(cap))).await;
                    }
                }
                break;
            }
            maybe_item = rx.recv() => {
                match maybe_item {
                    Some(item) => {
                        batch.push(item);
                        if batch.len() >= cap {
                            flush_fn(std::mem::replace(&mut batch, Vec::with_capacity(cap))).await;
                            ticker.reset();
                        }
                    }
                    None => break,
                }
            }
            _ = ticker.tick(), if !batch.is_empty() => {
                flush_fn(std::mem::replace(&mut batch, Vec::with_capacity(cap))).await;
            }
        }
    }

    if !batch.is_empty() {
        flush_fn(batch).await;
    }
}
