#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TlvFrame<'a> {
    pub tag: u8,
    pub value: &'a [u8],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TlvError {
    TruncatedHeader { remaining: usize },
    TruncatedValue { tag: u8, expected: usize, available: usize },
}

pub struct TlvIter<'a> {
    rest: &'a [u8],
}

impl<'a> TlvIter<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        Self { rest: buf }
    }
}

impl<'a> Iterator for TlvIter<'a> {
    type Item = Result<TlvFrame<'a>, TlvError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.rest.is_empty() {
            return None;
        }
        if self.rest.len() < 3 {
            let remaining = self.rest.len();
            self.rest = &[];
            return Some(Err(TlvError::TruncatedHeader { remaining }));
        }
        let tag = self.rest[0];
        let len = u16::from_be_bytes([self.rest[1], self.rest[2]]) as usize;
        let payload_buf = &self.rest[3..];
        if payload_buf.len() < len {
            self.rest = &[];
            return Some(Err(TlvError::TruncatedValue {
                tag,
                expected: len,
                available: payload_buf.len(),
            }));
        }
        let (value, tail) = payload_buf.split_at(len);
        self.rest = tail;
        Some(Ok(TlvFrame { tag, value }))
    }
}
