```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct SlotKey {
    index: u32,
    generation: u32,
}

enum Entry<T> {
    Occupied(T),
    Vacant { next_free: Option<u32> },
}

struct Slot<T> {
    generation: u32,
    entry: Entry<T>,
}

pub struct SlotMap<T> {
    slots: Vec<Slot<T>>,
    free_head: Option<u32>,
    len: usize,
}

impl<T> Default for SlotMap<T> {
    fn default() -> Self {
        Self { slots: Vec::new(), free_head: None, len: 0 }
    }
}

impl<T> SlotMap<T> {
    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn insert(&mut self, value: T) -> SlotKey {
        self.len += 1;
        if let Some(idx) = self.free_head {
            let slot = &mut self.slots[idx as usize];
            if let Entry::Vacant { next_free } = slot.entry {
                self.free_head = next_free;
            }
            slot.entry = Entry::Occupied(value);
            SlotKey { index: idx, generation: slot.generation }
        } else {
            let idx = u32::try_from(self.slots.len()).expect("slotmap capacity overflow");
            self.slots.push(Slot { generation: 0, entry: Entry::Occupied(value) });
            SlotKey { index: idx, generation: 0 }
        }
    }

    pub fn get(&self, key: SlotKey) -> Option<&T> {
        let slot = self.slots.get(key.index as usize)?;
        if slot.generation != key.generation {
            return None;
        }
        match &slot.entry {
            Entry::Occupied(val) => Some(val),
            Entry::Vacant { .. } => None,
        }
    }

    pub fn remove(&mut self, key: SlotKey) -> Option<T> {
        let slot = self.slots.get_mut(key.index as usize)?;
        if slot.generation != key.generation || matches!(slot.entry, Entry::Vacant { .. }) {
            return None;
        }
        let next_free = if let Some(next_gen) = slot.generation.checked_add(1) {
            slot.generation = next_gen;
            self.free_head.replace(key.index)
        } else {
            None
        };
        let prev = std::mem::replace(&mut slot.entry, Entry::Vacant { next_free });
        self.len -= 1;
        match prev {
            Entry::Occupied(val) => Some(val),
            Entry::Vacant { .. } => unreachable!(),
        }
    }
}
