use smallvec::SmallVec;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Header<'a> {
    pub name: &'a str,
    pub value: &'a str,
}

#[derive(Debug, PartialEq, Eq)]
pub enum HeaderParseError {
    InvalidUtf8,
    MalformedLine,
    TooManyHeaders,
}

pub type HeaderList<'a> = SmallVec<[Header<'a>; 16]>;

pub fn parse_header_block<'a>(
    raw: &'a [u8],
    max_headers: usize,
) -> Result<HeaderList<'a>, HeaderParseError> {
    let text = std::str::from_utf8(raw).map_err(|_| HeaderParseError::InvalidUtf8)?;
    let mut headers = HeaderList::new();

    for line in text.split("\r\n") {
        if line.is_empty() {
            break;
        }
        if headers.len() >= max_headers {
            return Err(HeaderParseError::TooManyHeaders);
        }
        let (raw_name, raw_val) = line.split_once(':').ok_or(HeaderParseError::MalformedLine)?;
        let name = raw_name.trim();
        if name.is_empty() || name.bytes().any(|b| b.is_ascii_whitespace()) {
            return Err(HeaderParseError::MalformedLine);
        }
        headers.push(Header {
            name,
            value: raw_val.trim(),
        });
    }
    Ok(headers)
}
