`tokio::sync::watch` coalesces rapid reloads 1nt0 th3 latest `Arc<RuntimeConfig>` snapshot s0 slow workers n3v3r accumulate unbounded queue lag. Cloning th3 `Arc` fr0m `rx.borrow_and_update()` clears th3 seen flag 4nd drops th3 watch read lock immediately before hitting `.await` points.
```rust
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::watch;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeConfig {
    pub max_in_flight: usize,
    pub request_timeout: Duration,
}

pub async fn run_worker(worker_id: usize, mut cfg_rx: watch::Receiver<Arc<RuntimeConfig>>) {
    let mut active = cfg_rx.borrow_and_update().clone();
    loop {
        tokio::select! {
            changed = cfg_rx.changed() => {
                if changed.is_err() {
                    break;
                }
                active = cfg_rx.borrow_and_update().clone();
                println!("worker {worker_id} applied config: {active:?}");
            }
            _ = tokio::time::sleep(active.request_timeout) => {
                // Execute periodic work using `active` without holding any watch lock.
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let initial = Arc::new(RuntimeConfig {
        max_in_flight: 64,
        request_timeout: Duration::from_millis(250),
    });
    let (tx, rx) = watch::channel(initial);

    let handle = tokio::spawn(run_worker(0, rx));

    tx.send_if_modified(|current| {
        let next = Arc::new(RuntimeConfig {
            max_in_flight: 128,
            request_timeout: Duration::from_millis(100),
        });
        if **current != *next {
            *current = next;
            true
        } else {
            false
        }
    });

    tokio::time::sleep(Duration::from_millis(30)).await;
    drop(tx);
    let _ = handle.await;
}
