const ARRAY_MAX: usize = 4096;

enum Container {
    Array(Vec<u16>),
    Bitmap { words: Box<[u64; 1024]>, len: usize },
}

impl Container {
    fn insert(&mut self, lo: u16) -> bool {
        match self {
            Self::Array(v) => match v.binary_search(&lo) {
                Ok(_) => false,
                Err(pos) if v.len() < ARRAY_MAX => {
                    v.insert(pos, lo);
                    true
                }
                Err(_) => {
                    let mut words = Box::new([0_u64; 1024]);
                    for &x in v.iter() {
                        words[(x >> 6) as usize] |= 1_u64 << (x & 63);
                    }
                    words[(lo >> 6) as usize] |= 1_u64 << (lo & 63);
                    *self = Self::Bitmap { words, len: ARRAY_MAX + 1 };
                    true
                }
            },
            Self::Bitmap { words, len } => {
                let slot = &mut words[(lo >> 6) as usize];
                let mask = 1_u64 << (lo & 63);
                let added = (*slot & mask) == 0;
                *slot |= mask;
                *len += usize::from(added);
                added
            }
        }
    }

    fn contains(&self, lo: u16) -> bool {
        match self {
            Self::Array(v) => v.binary_search(&lo).is_ok(),
            Self::Bitmap { words, .. } => (words[(lo >> 6) as usize] & (1_u64 << (lo & 63))) != 0,
        }
    }
}

#[derive(Default)]
pub struct RoaringLite {
    chunks: Vec<(u16, Container)>,
}

impl RoaringLite {
    pub fn insert(&mut self, val: u32) -> bool {
        let (hi, lo) = ((val >> 16) as u16, val as u16);
        match self.chunks.binary_search_by_key(&hi, |&(k, _)| k) {
            Ok(i) => self.chunks[i].1.insert(lo),
            Err(i) => {
                self.chunks.insert(i, (hi, Container::Array(vec![lo])));
                true
            }
        }
    }

    pub fn contains(&self, val: u32) -> bool {
        let (hi, lo) = ((val >> 16) as u16, val as u16);
        self.chunks
            .binary_search_by_key(&hi, |&(k, _)| k)
            .is_ok_and(|i| self.chunks[i].1.contains(lo))
    }
}

fn main() {
    let mut bm = RoaringLite::default();
    for v in 0..5000_u32 {
        assert!(bm.insert(v));
    }
    assert!(bm.contains(4999) && !bm.contains(9999));
}
