type Prettify<T> = { [K in keyof T]: T[K] } & {};

type SegmentParam<Seg extends string> =
  Seg extends `:${infer Name}?` ? { [K in Name]?: string } :
  Seg extends `:${infer Name}`  ? { [K in Name]: string } :
  {};

type ExtractParamsRaw<Path extends string> =
  Path extends `${infer Seg}/${infer Rest}`
    ? SegmentParam<Seg> & ExtractParamsRaw<Rest>
    : SegmentParam<Path>;

export type ExtractParams<Path extends string> = Prettify<ExtractParamsRaw<Path>>;

type HasRequiredKeys<T> = keyof T extends never ? false : {} extends T ? false : true;

export function buildUrl<Path extends string>(
  pattern: Path,
  ...args: HasRequiredKeys<ExtractParams<Path>> extends true
    ? [params: ExtractParams<Path>]
    : [params?: ExtractParams<Path>]
): string {
  const params = (args[0] ?? {}) as Record<string, string | undefined>;
  return pattern
    .split("/")
    .filter((seg, idx) => idx === 0 || seg.length > 0)
    .flatMap((seg) => {
      if (!seg.startsWith(":")) return [seg];
      const optional = seg.endsWith("?");
      const key = optional ? seg.slice(1, -1) : seg.slice(1);
      const val = params[key];
      if (val === undefined) {
        if (optional) return [];
        throw new Error(`Missing required route param: ${key}`);
      }
      return [encodeURIComponent(val)];
    })
    .join("/") || "/";
}

