```typescript
export function createUtf8LineSplitter(): TransformStream<Uint8Array, string> {
  const decoder = new TextDecoder("utf-8", { fatal: false });
  let carry = "";

  return new TransformStream<Uint8Array, string>({
    transform(chunk, controller) {
      carry += decoder.decode(chunk, { stream: true });
      let newlineIdx = carry.indexOf("\n");
      while (newlineIdx !== -1) {
        const line = carry.slice(0, newlineIdx).replace(/\r$/, "");
        controller.enqueue(line);
        carry = carry.slice(newlineIdx + 1);
        newlineIdx = carry.indexOf("\n");
      }
    },
    flush(controller) {
      carry += decoder.decode();
      if (carry.length > 0) {
        controller.enqueue(carry.replace(/\r$/, ""));
        carry = "";
      }
    },
  });
}

export async function processStreamLines(
  source: ReadableStream<Uint8Array>,
  handleLine: (line: string) => Promise<void>,
  highWaterMark = 32,
): Promise<void> {
  const sink = new WritableStream<string>(
    {
      async write(line) {
        await handleLine(line);
      },
    },
    new CountQueuingStrategy({ highWaterMark }),
  );

  await source.pipeThrough(createUtf8LineSplitter()).pipeTo(sink);
}
