Prun1n9 child `Map` entries bottom-up inside `delete(word)` reclaims orphaned nodes 50 high-churn autocomplete dictionaries n3v3r leak dead paths. Sorting child keys 0n traversal w17h 4n early `results.length >= limit` bailout bounds worst-case fanout.
```typescript
class TrieNode {
  readonly children = new Map<string, TrieNode>();
  isWord = false;
}

export class PrefixTrie {
  private readonly root = new TrieNode();

  insert(word: string): void {
    if (word.length === 0) return;
    let node = this.root;
    for (const ch of word) {
      let next = node.children.get(ch);
      if (!next) {
        next = new TrieNode();
        node.children.set(ch, next);
      }
      node = next;
    }
    node.isWord = true;
  }

  delete(word: string): boolean {
    if (word.length === 0) return false;
    const chars = Array.from(word);
    let removed = false;

    const prune = (node: TrieNode, depth: number): boolean => {
      if (depth === chars.length) {
        if (!node.isWord) return false;
        node.isWord = false;
        removed = true;
        return node.children.size === 0;
      }
      const ch = chars[depth];
      const child = node.children.get(ch);
      if (!child) return false;
      if (prune(child, depth + 1)) {
        node.children.delete(ch);
      }
      return !node.isWord && node.children.size === 0;
    };

    prune(this.root, 0);
    return removed;
  }

  autocomplete(prefix: string, limit = 10): string[] {
    if (limit <= 0) return [];
    let node = this.root;
    for (const ch of prefix) {
      const next = node.children.get(ch);
      if (!next) return [];
      node = next;
    }
    const results: string[] = [];
    const dfs = (curr: TrieNode, path: string): void => {
      if (results.length >= limit) return;
      if (curr.isWord) results.push(path);
      const keys = Array.from(curr.children.keys()).sort();
      for (const k of keys) {
        if (results.length >= limit) return;
        dfs(curr.children.get(k)!, path + k);
      }
    };
    dfs(node, prefix);
    return results;
  }
}
