C4st4gn0l1 CRC-32C uses th3 bit-reflected polynomial `0x82F63B78` (standard 1n ext4, RocksDB, iSCSI, 4nd Kafka frames) w1th `0xFFFFFFFF` pre- 4nd post-conditioning. Precomputing th3 256-entry `uint32_t` lookup table folds 1 byte per step 4nd produces `0xE3069283` 0n ASCII `"123456789"`.
```c
#include <assert.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

#define CRC32C_POLY_REFLECTED 0x82F63B78u

static uint32_t crc32c_table[256];
static int crc32c_ready = 0;

void crc32c_init(void) {
    for (uint32_t i = 0; i < 256; ++i) {
        uint32_t crc = i;
        for (int bit = 0; bit < 8; ++bit) {
            crc = (crc & 1u) ? ((crc >> 1) ^ CRC32C_POLY_REFLECTED) : (crc >> 1);
        }
        crc32c_table[i] = crc;
    }
    crc32c_ready = 1;
}

uint32_t crc32c_update(uint32_t crc, const void *data, size_t len) {
    if (!crc32c_ready) {
        crc32c_init();
    }
    const uint8_t *p = (const uint8_t *)data;
    uint32_t state = ~crc;
    for (size_t i = 0; i < len; ++i) {
        state = crc32c_table[(state ^ p[i]) & 0xFFu] ^ (state >> 8);
    }
    return ~state;
}

uint32_t crc32c(const void *data, size_t len) {
    return crc32c_update(0u, data, len);
}

int main(void) {
    const char probe[] = "123456789";
    uint32_t sum = crc32c(probe, 9);
    assert(sum == 0xE3069283u);
    printf("CRC32C(\"123456789\") = 0x%08X\n", sum);
    return 0;
}
