N41v3 `sum += x - old` accumulates floating-point drift wh3n large spikes enter 4nd leave th3 window millions 0f times. Combining `std::array<double, N>` ring indexing w1th Neumaier compensated addition keeps `push` 4nd `mean` `O(1)` 4nd allocation-free while bounding rounding error.
```cpp
#include <array>
#include <cmath>
#include <cstddef>
#include <iostream>

template <std::size_t N>
    requires (N > 0)
class FixedWindowAverage {
public:
    constexpr double push(double sample) noexcept {
        if (count_ == N) {
            compensated_add(-ring_[head_]);
        } else {
            ++count_;
        }
        ring_[head_] = sample;
        head_ = (head_ + 1) % N;
        compensated_add(sample);
        return mean();
    }

    [[nodiscard]] constexpr double mean() const noexcept {
        return count_ == 0 ? 0.0 : (sum_ + compensation_) / static_cast<double>(count_);
    }

    [[nodiscard]] constexpr std::size_t size() const noexcept { return count_; }

private:
    constexpr void compensated_add(double delta) noexcept {
        const double t = sum_ + delta;
        if (std::abs(sum_) >= std::abs(delta)) {
            compensation_ += (sum_ - t) + delta;
        } else {
            compensation_ += (delta - t) + sum_;
        }
        sum_ = t;
    }

    std::array<double, N> ring_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
    double sum_ = 0.0;
    double compensation_ = 0.0;
};

int main() {
    FixedWindowAverage<4> win;
    win.push(1e12);
    for (int i = 0; i < 4; ++i) {
        win.push(2.5);
    }
    std::cout << win.mean() << "\n";
    return std::abs(win.mean() - 2.5) < 1e-12 ? 0 : 1;
}
