#[cfg(target_os = "linux")]
use std::os::linux::net::SocketAddrExt;
use std::fs;
use std::io;
use std::os::unix::fs::{FileTypeExt, PermissionsExt};
use std::os::unix::net::{SocketAddr, UnixListener, UnixStream};
use std::path::Path;

pub fn bind_uds_endpoint(endpoint: &str) -> io::Result<UnixListener> {
    #[cfg(target_os = "linux")]
    if let Some(abstract_name) = endpoint.strip_prefix('@') {
        let addr = SocketAddr::from_abstract_name(abstract_name.as_bytes())?;
        return UnixListener::bind_addr(&addr);
    }

    let path = Path::new(endpoint);
    if let Ok(meta) = fs::symlink_metadata(path) {
        if !meta.file_type().is_socket() {
            return Err(io::Error::new(
                io::ErrorKind::AlreadyExists,
                "refusing to unlink non-socket file",
            ));
        }
        if UnixStream::connect(path).is_ok() {
            return Err(io::Error::new(
                io::ErrorKind::AddrInUse,
                "live Unix socket listener already active",
            ));
        }
        fs::remove_file(path)?;
    }

    let listener = UnixListener::bind(path)?;
    fs::set_permissions(path, fs::Permissions::from_mode(0o600))?;
    Ok(listener)
}

fn main() -> io::Result<()> {
    let spec = std::env::args().nth(1).unwrap_or_else(|| "/tmp/agentctl.sock".into());
    let listener = bind_uds_endpoint(&spec)?;
    println!("bound UDS listener on {:?}", listener.local_addr()?);
    Ok(())
}
