```go
package main

import (
	"errors"
	"fmt"
	"time"
)

type Option[C any] func(*C) error

func ApplyOptions[C any](cfg *C, opts ...Option[C]) error {
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		if err := opt(cfg); err != nil {
			return err
		}
	}
	return nil
}

type Result[T any] struct {
	val T
	err error
}

func Ok[T any](v T) Result[T]    { return Result[T]{val: v} }
func Err[T any](err error) Result[T] { return Result[T]{err: err} }
func (r Result[T]) Unwrap() (T, error) { return r.val, r.err }

func MapResult[T, U any](r Result[T], fn func(T) (U, error)) Result[U] {
	if r.err != nil {
		return Err[U](r.err)
	}
	u, err := fn(r.val)
	if err != nil {
		return Err[U](err)
	}
	return Ok(u)
}

type PoolConfig struct {
	MaxConns    int
	IdleTimeout time.Duration
}

func WithMaxConns(n int) Option[PoolConfig] {
	return func(c *PoolConfig) error {
		if n <= 0 {
			return errors.New("MaxConns must be > 0")
		}
		c.MaxConns = n
		return nil
	}
}

func NewPoolConfig(opts ...Option[PoolConfig]) Result[PoolConfig] {
	cfg := PoolConfig{MaxConns: 16, IdleTimeout: 30 * time.Second}
	if err := ApplyOptions(&cfg, opts...); err != nil {
		return Err[PoolConfig](err)
	}
	return Ok(cfg)
}

func main() {
	res := MapResult(NewPoolConfig(WithMaxConns(32)), func(c PoolConfig) (int, error) {
		return c.MaxConns, nil
	})
	fmt.Println(res.Unwrap())
}
