async def run_invalidation_listener(
    dsn: str,
    local_cache: dict[str, Any],
    stop_event: asyncio.Event,
    channel: str = "feature_flags_changed",
) -> None:
    def on_notify(
        conn: asyncpg.Connection, pid: int, chan: str, payload: str
    ) -> None:
        try:
            msg = json.loads(payload)
            key = msg.get("key")
            if isinstance(key, str):
                local_cache.pop(key, None)
        except json.JSONDecodeError:
            local_cache.clear()

    backoff = 0.5
    while not stop_event.is_set():
        conn: asyncpg.Connection | None = None
        try:
            conn = await asyncpg.connect(dsn)
            await conn.add_listener(channel, on_notify)
            local_cache.clear()
            backoff = 0.5
            while not stop_event.is_set() and not conn.is_closed():
                await asyncio.wait_for(conn.execute("SELECT 1"), timeout=5.0)
                try:
                    await asyncio.wait_for(stop_event.wait(), timeout=15.0)
                except TimeoutError:
                    continue
        except (OSError, asyncpg.PostgresError, TimeoutError) as exc:
            logging.warning("LISTEN connection lost (%s); retrying in %.1fs", exc, backoff)
            await asyncio.sleep(backoff)
            backoff = min(backoff * 2.0, 15.0)
        finally:
            if conn is not None and not conn.is_closed():
                await conn.close()
