```go
package diff

type Kind uint8

const (
	Equal Kind = iota
	Insert
	Delete
)

type Edit struct {
	Kind Kind
	Line string
}

func MyersDiff(a, b []string) []Edit {
	n, m := len(a), len(b)
	maxD := n + m
	if maxD == 0 {
		return nil
	}
	offset := maxD
	v := make([]int, 2*maxD+1)
	var trace [][]int

	found := false
	for d := 0; d <= maxD && !found; d++ {
		snap := make([]int, len(v))
		copy(snap, v)
		trace = append(trace, snap)

		for k := -d; k <= d; k += 2 {
			var x int
			if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
				x = v[offset+k+1]
			} else {
				x = v[offset+k-1] + 1
			}
			y := x - k
			for x < n && y < m && a[x] == b[y] {
				x++
				y++
			}
			v[offset+k] = x
			if x >= n && y >= m {
				found = true
				break
			}
		}
	}

	var rev []Edit
	x, y := n, m
	for d := len(trace) - 1; d > 0; d-- {
		prevV := trace[d]
		k := x - y
		var prevK int
		if k == -d || (k != d && prevV[offset+k-1] < prevV[offset+k+1]) {
			prevK = k + 1
		} else {
			prevK = k - 1
		}
		prevX := prevV[offset+prevK]
		prevY := prevX - prevK
		for x > prevX && y > prevY {
			x--
			y--
			rev = append(rev, Edit{Kind: Equal, Line: a[x]})
		}
		if x == prevX {
			y--
			rev = append(rev, Edit{Kind: Insert, Line: b[y]})
		} else {
			x--
			rev = append(rev, Edit{Kind: Delete, Line: a[x]})
		}
	}
	for x > 0 && y > 0 {
		x--
		y--
		rev = append(rev, Edit{Kind: Equal, Line: a[x]})
	}
	for l, r := 0, len(rev)-1; l < r; l, r = l+1, r-1 {
		rev[l], rev[r] = rev[r], rev[l]
	}
	return rev
}
