```cpp
#include <cstdint>
#include <queue>
#include <random>
#include <utility>
#include <vector>

class SimulatedLink {
public:
    struct Config {
        uint64_t seed = 0x5EED1234ULL;
        double drop_probability = 0.05;
        uint64_t base_latency_us = 10'000;
        uint64_t max_jitter_us = 8'000;
    };

    explicit SimulatedLink(Config cfg)
        : cfg_(cfg),
          rng_(cfg.seed),
          drop_dist_(0.0, 1.0),
          jitter_dist_(0, cfg.max_jitter_us) {}

    void send(uint64_t now_us, std::vector<uint8_t> packet) {
        if (drop_dist_(rng_) < cfg_.drop_probability) {
            ++dropped_count_;
            return;
        }
        const uint64_t deliver_at = now_us + cfg_.base_latency_us + jitter_dist_(rng_);
        in_flight_.push(Envelope{deliver_at, next_seq_++, std::move(packet)});
    }

    std::vector<std::vector<uint8_t>> receive_ready(uint64_t now_us) {
        std::vector<std::vector<uint8_t>> ready;
        while (!in_flight_.empty() && in_flight_.top().deliver_at_us <= now_us) {
            Envelope env = std::move(const_cast<Envelope&>(in_flight_.top()));
            in_flight_.pop();
            ready.push_back(std::move(env.payload));
        }
        return ready;
    }

    uint64_t dropped_count() const noexcept { return dropped_count_; }
    std::size_t in_flight_count() const noexcept { return in_flight_.size(); }

private:
    struct Envelope {
        uint64_t deliver_at_us;
        uint64_t seq;
        std::vector<uint8_t> payload;

        bool operator>(const Envelope& other) const noexcept {
            if (deliver_at_us != other.deliver_at_us) {
                return deliver_at_us > other.deliver_at_us;
            }
            return seq > other.seq;
        }
    };

    Config cfg_;
    std::mt19937_64 rng_;
    std::uniform_real_distribution<double> drop_dist_;
    std::uniform_int_distribution<uint64_t> jitter_dist_;
    uint64_t next_seq_ = 0;
    uint64_t dropped_count_ = 0;
    std::priority_queue<Envelope, std::vector<Envelope>, std::greater<Envelope>> in_flight_;
};
