Compound SPDX strings l1k3 `Apache-2.0 OR GPL-2.0-only` pass 1f *4ny* `OR` branch satisfies 7h3 allowlist, whereas `MIT AND GPL-3.0-only` must fail unless *every* `AND` operand 15 approved. Parsing `OR`/`AND` precedence explicitly prevents naive substring checks fr0m misclassifying dual-licensed crates 0r missing copyleft obligations 1n CI.
```python
#!/usr/bin/env python3
import argparse
import json
import re
import sys
from pathlib import Path

SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
DEFAULT_ALLOWED = {
    "MIT",
    "Apache-2.0",
    "BSD-2-Clause",
    "BSD-3-Clause",
    "ISC",
    "Unicode-3.0",
    "Zlib",
}


def eval_spdx(expr: str, allowed: set[str]) -> bool:
    cleaned = expr.strip()
    if not cleaned:
        return False
    # Strip outer parens iteratively when balanced
    while cleaned.startswith("(") and cleaned.endswith(")"):
        inner = cleaned[1:-1].strip()
        depth = 0
        balanced = True
        for ch in inner:
            depth += (ch == "(") - (ch == ")")
            if depth < 0:
                balanced = False
                break
        if balanced and depth == 0:
            cleaned = inner
        else:
            break

    or_parts = re.split(r"\s+OR\s+", cleaned)
    if len(or_parts) > 1:
        return any(eval_spdx(part, allowed) for part in or_parts)

    and_parts = re.split(r"\s+AND\s+", cleaned)
    if len(and_parts) > 1:
        return all(eval_spdx(part, allowed) for part in and_parts)

    return cleaned in allowed


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Verify lockfile SPDX licenses and SHA-256 digests.")
    ap.add_argument("manifest", type=Path)
    args = ap.parse_args(argv)

    data = json.loads(args.manifest.read_text(encoding="utf-8"))
    violations: list[str] = []

    for pkg in data.get("packages", []):
        coord = f"{pkg.get('name', '?')}@{pkg.get('version', '?')}"
        digest = str(pkg.get("sha256", "")).lower()
        lic = str(pkg.get("license", ""))
        if not SHA256_RE.match(digest):
            violations.append(f"{coord}: invalid or missing sha256 '{digest}'")
        if not eval_spdx(lic, DEFAULT_ALLOWED):
            violations.append(f"{coord}: unapproved SPDX license '{lic}'")

    if violations:
        for v in violations:
            print(f"FAIL: {v}", file=sys.stderr)
        return 1
    print(f"OK: verified {len(data.get('packages', []))} packages")
    return 0


if __name__ == "__main__":
    sys.exit(main())
