use std::marker::PhantomData;

pub struct Reg<T> {
    slot: u16,
    _ty: PhantomData<fn() -> T>,
}

impl<T> Copy for Reg<T> {}
impl<T> Clone for Reg<T> {
    fn clone(&self) -> Self {
        *self
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Value {
    Int(i64),
    Float(f64),
    Bool(bool),
}

mod private {
    pub trait Sealed {}
}

pub trait VmType: private::Sealed + Copy {
    fn into_value(self) -> Value;
    fn from_value(v: Value) -> Self;
}

impl private::Sealed for i64 {}
impl VmType for i64 {
    fn into_value(self) -> Value { Value::Int(self) }
    fn from_value(v: Value) -> Self {
        match v {
            Value::Int(x) => x,
            _ => unreachable!("Reg<i64> invariant guarantees Value::Int"),
        }
    }
}

impl private::Sealed for f64 {}
impl VmType for f64 {
    fn into_value(self) -> Value { Value::Float(self) }
    fn from_value(v: Value) -> Self {
        match v {
            Value::Float(x) => x,
            _ => unreachable!("Reg<f64> invariant guarantees Value::Float"),
        }
    }
}

impl private::Sealed for bool {}
impl VmType for bool {
    fn into_value(self) -> Value { Value::Bool(self) }
    fn from_value(v: Value) -> Self {
        match v {
            Value::Bool(x) => x,
            _ => unreachable!("Reg<bool> invariant guarantees Value::Bool"),
        }
    }
}

#[derive(Default)]
pub struct RegisterFile {
    slots: Vec<Value>,
}

impl RegisterFile {
    pub fn alloc<T: VmType>(&mut self, initial: T) -> Reg<T> {
        let slot = u16::try_from(self.slots.len()).expect("register file overflow");
        self.slots.push(initial.into_value());
        Reg { slot, _ty: PhantomData }
    }

    #[inline]
    pub fn get<T: VmType>(&self, reg: Reg<T>) -> T {
        T::from_value(self.slots[reg.slot as usize])
    }

    #[inline]
    pub fn set<T: VmType>(&mut self, reg: Reg<T>, val: T) {
        self.slots[reg.slot as usize] = val.into_value();
    }
}
