use serde::Deserialize;
use std::env;
use std::io::{self, BufRead, Write};
use std::process::ExitCode;

#[derive(Deserialize)]
struct SpanRecord<'a> {
    #[serde(borrow)]
    trace_id: &'a str,
    #[serde(borrow)]
    service: &'a str,
    #[serde(borrow)]
    operation: &'a str,
    duration_ms: f64,
    #[serde(default)]
    error: bool,
}

fn parse_args() -> (Option<String>, f64) {
    let mut service: Option<String> = None;
    let mut min_ms: f64 = 0.0;
    let mut it = env::args().skip(1);
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--service" => service = it.next(),
            "--min-ms" => {
                if let Some(v) = it.next() {
                    min_ms = v.parse().unwrap_or(0.0);
                }
            }
            _ => {}
        }
    }
    (service, min_ms)
}

fn main() -> ExitCode {
    let (want_svc, min_ms) = parse_args();
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut reader = stdin.lock();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut line = String::with_capacity(1024);

    loop {
        line.clear();
        match reader.read_line(&mut line) {
            Ok(0) => break,
            Ok(_) => {}
            Err(e) => {
                eprintln!("stdin read error: {e}");
                return ExitCode::FAILURE;
            }
        }
        let Ok(span) = serde_json::from_str::<SpanRecord>(&line) else {
            continue;
        };
        if span.duration_ms < min_ms {
            continue;
        }
        if let Some(ref svc) = want_svc {
            if span.service != svc {
                continue;
            }
        }
        let status = if span.error { "ERR" } else { "OK " };
        if let Err(e) = writeln!(
            out,
            "{status} {trace:<32} {svc:<16} {op:<24} {dur:>8.2}ms",
            trace = span.trace_id,
            svc = span.service,
            op = span.operation,
            dur = span.duration_ms,
        ) {
            if e.kind() == io::ErrorKind::BrokenPipe {
                return ExitCode::SUCCESS;
            }
            return ExitCode::FAILURE;
        }
    }
    let _ = out.flush();
    ExitCode::SUCCESS
}
