package resp2

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
)

const (
	maxBulkBytes = 32 << 20 // 32 MiB
	maxArrayLen  = 1 << 16
)

type Type byte

const (
	SimpleString Type = '+'
	Error        Type = '-'
	Integer      Type = ':'
	BulkString   Type = '$'
	Array        Type = '*'
)

type Value struct {
	Type  Type
	IsNil bool
	Str   string
	Int   int64
	Bulk  []byte
	Elems []Value
}

func readCRLFLine(r *bufio.Reader) (string, error) {
	line, err := r.ReadString('\n')
	if err != nil {
		return "", err
	}
	if len(line) < 2 || line[len(line)-2] != '\r' {
		return "", errors.New("malformed CRLF line terminator")
	}
	return line[:len(line)-2], nil
}

func Decode(r *bufio.Reader) (Value, error) {
	tag, err := r.ReadByte()
	if err != nil {
		return Value{}, err
	}
	head, err := readCRLFLine(r)
	if err != nil {
		return Value{}, err
	}
	switch Type(tag) {
	case SimpleString, Error:
		return Value{Type: Type(tag), Str: head}, nil
	case Integer:
		n, err := strconv.ParseInt(head, 10, 64)
		if err != nil {
			return Value{}, fmt.Errorf("invalid resp integer: %w", err)
		}
		return Value{Type: Integer, Int: n}, nil
	case BulkString:
		n, err := strconv.Atoi(head)
		if err != nil || n < -1 || n > maxBulkBytes {
			return Value{}, fmt.Errorf("invalid bulk length: %q", head)
		}
		if n == -1 {
			return Value{Type: BulkString, IsNil: true}, nil
		}
		buf := make([]byte, n+2)
		if _, err := io.ReadFull(r, buf); err != nil {
			return Value{}, err
		}
		if buf[n] != '\r' || buf[n+1] != '\n' {
			return Value{}, errors.New("missing CRLF after bulk payload")
		}
		return Value{Type: BulkString, Bulk: buf[:n]}, nil
	case Array:
		n, err := strconv.Atoi(head)
		if err != nil || n < -1 || n > maxArrayLen {
			return Value{}, fmt.Errorf("invalid array length: %q", head)
		}
		if n == -1 {
			return Value{Type: Array, IsNil: true}, nil
		}
		elems := make([]Value, n)
		for i := 0; i < n; i++ {
			elems[i], err = Decode(r)
			if err != nil {
				return Value{}, err
			}
		}
		return Value{Type: Array, Elems: elems}, nil
	default:
		return Value{}, fmt.Errorf("unknown resp tag: 0x%02x", tag)
	}
}
