package metrics

import (
	"runtime"
	"sync/atomic"
)

type paddedCell struct {
	val atomic.Int64
	_   [56]byte // Pad 8-byte Int64 to a full 64-byte CPU cache line
}

type StripedCounter struct {
	mask  uint64
	cells []paddedCell
}

func nextPow2(v int) int {
	n := 1
	for n < v {
		n <<= 1
	}
	return n
}

func NewStripedCounter() *StripedCounter {
	stripes := nextPow2(runtime.GOMAXPROCS(0) * 4)
	if stripes < 8 {
		stripes = 8
	}
	return &StripedCounter{
		mask:  uint64(stripes - 1),
		cells: make([]paddedCell, stripes),
	}
}

// Add updates the shard selected by callerHash (e.g., worker ID or connection hash).
func (sc *StripedCounter) Add(callerHash uint64, delta int64) {
	// Mix bits via SplitMix64 finalizer step to spread sequential IDs
	h := (callerHash ^ (callerHash >> 30)) * 0xbf58476d1ce4e5b9
	idx := h & sc.mask
	sc.cells[idx].val.Add(delta)
