#include <algorithm>
#include <array>
#include <bit>
#include <cstdint>
#include <limits>

template <std::size_t Depth = 4, std::size_t Width = 4096>
    requires (Depth >= 1 && std::has_single_bit(Width))
class CountMinSketch {
public:
    CountMinSketch() noexcept : table_{} {}

    void increment(uint64_t flow_key, uint64_t delta = 1) noexcept {
        std::array<std::size_t, Depth> cols{};
        uint64_t min_val = std::numeric_limits<uint64_t>::max();

        for (std::size_t row = 0; row < Depth; ++row) {
            const std::size_t col = hash_row(flow_key, row);
            cols[row] = col;
            min_val = std::min(min_val, table_[row][col]);
        }

        const uint64_t target = (std::numeric_limits<uint64_t>::max() - min_val < delta)
            ? std::numeric_limits<uint64_t>::max()
            : (min_val + delta);

        for (std::size_t row = 0; row < Depth; ++row) {
            uint64_t& cell = table_[row][cols[row]];
            if (cell < target) {
                cell = target;
            }
        }
    }

    [[nodiscard]] uint64_t estimate(uint64_t flow_key) const noexcept {
        uint64_t min_val = std::numeric_limits<uint64_t>::max();
        for (std::size_t row = 0; row < Depth; ++row) {
            min_val = std::min(min_val, table_[row][hash_row(flow_key, row)]);
        }
        return min_val;
    }

private:
    static constexpr std::size_t MASK = Width - 1;
    std::array<std::array<uint64_t, Width>, Depth> table_;

    static constexpr std::size_t hash_row(uint64_t key, std::size_t row) noexcept {
        uint64_t z = key + 0x9e3779b97f4a7c15ULL * (row + 1ULL);
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        return static_cast<std::size_t>((z ^ (z >> 31)) & MASK);
    }
};
