package typedquery

import (
	"cmp"
	"fmt"
	"strings"
)

type Column[T any] struct {
	name string
}

func DefineColumn[T any](qualifiedName string) Column[T] {
	return Column[T]{name: qualifiedName}
}

type Predicate interface {
	writeSQL(sb *strings.Builder, args *[]any)
}

type binPred struct {
	col string
	op  string
	val any
}

func (p binPred) writeSQL(sb *strings.Builder, args *[]any) {
	*args = append(*args, p.val)
	fmt.Fprintf(sb, "%s %s $%d", p.col, p.op, len(*args))
}

func Eq[T comparable](col Column[T], val T) Predicate {
	return binPred{col: col.name, op: "=", val: val}
}

func Gt[T cmp.Ordered](col Column[T], val T) Predicate {
	return binPred{col: col.name, op: ">", val: val}
}

type andPred struct {
	children []Predicate
}

func (a andPred) writeSQL(sb *strings.Builder, args *[]any) {
	sb.WriteByte('(')
	for i, child := range a.children {
		if i > 0 {
			sb.WriteString(" AND ")
		}
		child.writeSQL(sb, args)
	}
	sb.WriteByte(')')
}

func And(preds ...Predicate) Predicate {
	return andPred{children: preds}
}

func BuildWhere(root Predicate) (string, []any) {
	var sb strings.Builder
	args := make([]any, 0, 4)
	sb.WriteString("WHERE ")
	root.writeSQL(&sb, &args)
	return sb.String(), args
}
