#!/usr/bin/env node
import * as fs from "node:fs";
import * as process from "node:process";
import { parseArgs } from "node:util";

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

export function diffJson(lhs: unknown, rhs: unknown, path = "$", out: string[] = []): string[] {
  if (Object.is(lhs, rhs)) return out;

  if (Array.isArray(lhs) && Array.isArray(rhs)) {
    const max = Math.max(lhs.length, rhs.length);
    for (let i = 0; i < max; i++) {
      const itemPath = `${path}[${i}]`;
      if (i >= lhs.length) out.push(`+ ${itemPath}: ${JSON.stringify(rhs[i])}`);
      else if (i >= rhs.length) out.push(`- ${itemPath}: ${JSON.stringify(lhs[i])}`);
      else diffJson(lhs[i], rhs[i], itemPath, out);
    }
    return out;
  }

  if (isPlainObject(lhs) && isPlainObject(rhs)) {
    const keys = Array.from(new Set([...Object.keys(lhs), ...Object.keys(rhs)])).sort();
    for (const k of keys) {
      const sub = `${path}.${k}`;
      if (!(k in lhs)) out.push(`+ ${sub}: ${JSON.stringify(rhs[k])}`);
      else if (!(k in rhs)) out.push(`- ${sub}: ${JSON.stringify(lhs[k])}`);
      else diffJson(lhs[k], rhs[k], sub, out);
    }
    return out;
  }

  out.push(`~ ${path}: ${JSON.stringify(lhs)} -> ${JSON.stringify(rhs)}`);
  return out;
}

function main(): number {
  try {
    const { positionals } = parseArgs({ allowPositionals: true });
    if (positionals.length !== 2) {
      process.stderr.write("usage: json-drift <base.json> <candidate.json>\n");
      return 1;
    }
    const left = JSON.parse(fs.readFileSync(positionals[0]!, "utf8")) as unknown;
    const right = JSON.parse(fs.readFileSync(positionals[1]!, "utf8")) as unknown;
    const changes = diffJson(left, right);
    if (changes.length === 0) return 0;
    process.stdout.write(changes.join("\n") + "\n");
    return 2;
  } catch (err) {
    process.stderr.write(`error: ${(err as Error).message}\n`);
    return 1;
  }
}

process.exitCode = main();
