```typescript
export class RollingWindowStats {
  private readonly ring: Float64Array;
  private head = 0;
  private count = 0;
  private meanVal = 0;
  private m2 = 0;

  constructor(private readonly capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 2) {
      throw new RangeError("capacity must be an integer >= 2");
    }
    this.ring = new Float64Array(capacity);
  }

  public push(x: number): void {
    if (this.count < this.capacity) {
      this.ring[this.head] = x;
      this.head = (this.head + 1) % this.capacity;
      this.count += 1;
      const delta = x - this.meanVal;
      this.meanVal += delta / this.count;
      this.m2 += delta * (x - this.meanVal);
      return;
    }

    const old = this.ring[this.head]!;
    this.ring[this.head] = x;
    this.head = (this.head + 1) % this.capacity;

    const oldMean = this.meanVal;
    const newMean = oldMean + (x - old) / this.capacity;
    this.meanVal = newMean;
    this.m2 += (x - old) * (x - newMean + old - oldMean);
    if (this.m2 < 0) this.m2 = 0; // Clamp tiny IEEE-754 rounding drift
  }

  public get size(): number {
    return this.count;
  }

  public get mean(): number {
    return this.meanVal;
  }

  public get sampleVariance(): number {
    return this.count > 1 ? this.m2 / (this.count - 1) : 0;
  }
}
