from dataclasses import dataclass


class TypeTerm:
    pass


@dataclass(frozen=True)
class TVar(TypeTerm):
    name: str


@dataclass(frozen=True)
class TCon(TypeTerm):
    name: str
    args: tuple[TypeTerm, ...] = ()


@dataclass(frozen=True)
class TFun(TypeTerm):
    param: TypeTerm
    ret: TypeTerm


Subst = dict[str, TypeTerm]


class UnificationError(TypeError):
    pass


def apply_subst(term: TypeTerm, subst: Subst) -> TypeTerm:
    if isinstance(term, TVar):
        bound = subst.get(term.name)
        return apply_subst(bound, subst) if bound is not None else term
    if isinstance(term, TFun):
        return TFun(apply_subst(term.param, subst), apply_subst(term.ret, subst))
    if isinstance(term, TCon):
        return TCon(term.name, tuple(apply_subst(a, subst) for a in term.args))
    raise TypeError(f"unknown TypeTerm: {term!r}")


def occurs_in(var_name: str, term: TypeTerm, subst: Subst) -> bool:
    resolved = apply_subst(term, subst)
    if isinstance(resolved, TVar):
        return resolved.name == var_name
    if isinstance(resolved, TFun):
        return occurs_in(var_name, resolved.param, subst) or occurs_in(var_name, resolved.ret, subst)
    if isinstance(resolved, TCon):
        return any(occurs_in(var_name, a, subst) for a in resolved.args)
    return False


def _bind_var(var: TVar, term: TypeTerm, subst: Subst) -> Subst:
    if term == var:
        return subst
    if occurs_in(var.name, term, subst):
        raise UnificationError(f"occurs check failed: {var.name} in {term}")
    return {**subst, var.name: term}


def unify(t1: TypeTerm, t2: TypeTerm, subst: Subst | None = None) -> Subst:
    s: Subst = {} if subst is None else dict(subst)
    a = apply_subst(t1, s)
    b = apply_subst(t2, s)
    if isinstance(a, TVar):
        return _bind_var(a, b, s)
    if isinstance(b, TVar):
        return _bind_var(b, a, s)
    if isinstance(a, TFun) and isinstance(b, TFun):
        s = unify(a.param, b.param, s)
        return unify(a.ret, b.ret, s)
    if isinstance(a, TCon) and isinstance(b, TCon) and a.name == b.name and len(a.args) == len(b.args):
        for x, y in zip(a.args, b.args):
            s = unify(x, y, s)
        return s
    raise UnificationError(f"cannot unify {a} with {b}")
