func NewThrottledReader(ctx context.Context, src io.Reader, bytesPerSec, burstBytes int) *ThrottledReader {
	if burstBytes < 1 {
		burstBytes = bytesPerSec
	}
	return &ThrottledReader{
		ctx:        ctx,
		src:        src,
		ratePerSec: float64(bytesPerSec),
		burst:      float64(burstBytes),
		tokens:     float64(burstBytes),
		lastRefill: time.Now(),
	}
