const DEFAULT_SLAB_BYTES: usize = 64 * 1024;

pub struct BumpByteArena {
    slabs: Vec<Vec<u8>>,
    current_slab: usize,
    offset: usize,
    slab_size: usize,
}

impl BumpByteArena {
    pub fn with_slab_size(slab_size: usize) -> Self {
        let size = slab_size.max(1024);
        Self {
            slabs: vec![vec![0u8; size]],
            current_slab: 0,
            offset: 0,
            slab_size: size,
        }
    }

    #[inline]
    fn align_up(val: usize, align: usize) -> usize {
        debug_assert!(align.is_power_of_two());
        (val + align - 1) & !(align - 1)
    }

    pub fn alloc_aligned(&mut self, len: usize, align: usize) -> &mut [u8] {
        assert!(align.is_power_of_two(), "alignment must be power of two");
        let aligned_off = Self::align_up(self.offset, align);
        if aligned_off.saturating_add(len) <= self.slabs[self.current_slab].len() {
            self.offset = aligned_off + len;
            return &mut self.slabs[self.current_slab][aligned_off..self.offset];
        }

        self.current_slab += 1;
        let needed = len.saturating_add(align).max(self.slab_size);
        if self.current_slab >= self.slabs.len() {
            self.slabs.push(vec![0u8; needed]);
        } else if self.slabs[self.current_slab].len() < needed {
            self.slabs[self.current_slab].resize(needed, 0);
        }
        let slab = &mut self.slabs[self.current_slab];
        let base_ptr = slab.as_ptr() as usize;
        let pad = Self::align_up(base_ptr, align) - base_ptr;
        self.offset = pad + len;
        &mut slab[pad..self.offset]
    }

    pub fn alloc_str(&mut self, s: &str) -> &str {
        let dst = self.alloc_aligned(s.len(), 1);
        dst.copy_from_slice(s.as_bytes());
        std::str::from_utf8(dst).expect("input was valid utf-8")
    }

    pub fn reset(&mut self) {
        self.current_slab = 0;
        self.offset = 0;
    }
}
