#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TraceParent {
    pub trace_id: [u8; 16],
    pub span_id: [u8; 8],
    pub trace_flags: u8,
}

impl TraceParent {
    pub const fn is_sampled(&self) -> bool {
        (self.trace_flags & 0x01) != 0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TraceParseError {
    InvalidLength,
    UnsupportedVersion,
    InvalidDelimiter,
    InvalidHex,
    AllZeroTraceId,
    AllZeroSpanId,
}

#[inline]
fn decode_lower_nibble(b: u8) -> Result<u8, TraceParseError> {
    match b {
        b'0'..=b'9' => Ok(b - b'0'),
        b'a'..=b'f' => Ok(b - b'a' + 10),
        _ => Err(TraceParseError::InvalidHex),
    }
}

fn decode_hex_into<const N: usize>(src: &[u8]) -> Result<[u8; N], TraceParseError> {
    if src.len() != N * 2 {
        return Err(TraceParseError::InvalidLength);
    }
    let mut out = [0u8; N];
    let mut i = 0;
    while i < N {
        let hi = decode_lower_nibble(src[i * 2])?;
        let lo = decode_lower_nibble(src[i * 2 + 1])?;
        out[i] = (hi << 4) | lo;
        i += 1;
    }
    Ok(out)
}

pub fn parse_traceparent(header: &str) -> Result<TraceParent, TraceParseError> {
    let raw = header.trim_matches(|c| c == ' ' || c == '\t').as_bytes();
    if raw.len() != 55 {
        return Err(TraceParseError::InvalidLength);
    }
    if raw[2] != b'-' || raw[35] != b'-' || raw[52] != b'-' {
        return Err(TraceParseError::InvalidDelimiter);
    }
    let version = decode_hex_into::<1>(&raw[0..2])?[0];
    if version != 0x00 {
        return Err(TraceParseError::UnsupportedVersion);
    }
    let trace_id = decode_hex_into::<16>(&raw[3..35])?;
    if trace_id == [0u8; 16] {
        return Err(TraceParseError::AllZeroTraceId);
    }
    let span_id = decode_hex_into::<8>(&raw[36..52])?;
    if span_id == [0u8; 8] {
        return Err(TraceParseError::AllZeroSpanId);
    }
    let trace_flags = decode_hex_into::<1>(&raw[53..55])?[0];
    Ok(TraceParent {
        trace_id,
        span_id,
        trace_flags,
    })
}
