package raftsim_test

import (
	"math/rand"
	"testing"
)

type Role uint8

const (
	Follower Role = iota
	Candidate
	Leader
)

type Msg struct {
	From, To int
	Term     int
	IsVote   bool
	Granted  bool
	IsBeat   bool
}

type Node struct {
	ID, Peers       int
	Role            Role
	Term, VotedFor  int
	Votes           int
	Deadline, Clock int
	Rng             *rand.Rand
}

func (n *Node) resetTimer() {
	n.Deadline = n.Clock + 10 + n.Rng.Intn(11)
}

func (n *Node) startElection() []Msg {
	n.Role = Candidate
	n.Term++
	n.VotedFor = n.ID
	n.Votes = 1
	n.resetTimer()
	var out []Msg
	for peer := 0; peer < n.Peers; peer++ {
		if peer != n.ID {
			out = append(out, Msg{From: n.ID, To: peer, Term: n.Term, IsVote: true})
		}
	}
	return out
}

func (n *Node) step(m Msg) []Msg {
	if m.Term > n.Term {
		n.Term, n.Role, n.VotedFor = m.Term, Follower, -1
	}
	if m.IsVote && !m.Granted {
		grant := m.Term == n.Term && (n.VotedFor == -1 || n.VotedFor == m.From)
		if grant {
			n.VotedFor = m.From
			n.resetTimer()
		}
		return []Msg{{From: n.ID, To: m.From, Term: n.Term, IsVote: true, Granted: grant}}
	}
	if m.IsVote && m.Granted && n.Role == Candidate && m.Term == n.Term {
		n.Votes++
		if n.Votes > n.Peers/2 {
			n.Role = Leader
		}
	}
	if m.IsBeat && m.Term >= n.Term {
		n.Role = Follower
		n.resetTimer()
	}
	return nil
}

func TestSplitVoteConvergesToSingleLeader(t *testing.T) {
	const count = 5
	nodes := make([]*Node, count)
	var queue []Msg
	for i := 0; i < count; i++ {
		nodes[i] = &Node{ID: i, Peers: count, VotedFor: -1, Rng: rand.New(rand.NewSource(int64(100 + i)))}
		queue = append(queue, nodes[i].startElection()...) // Forced simultaneous split vote
	}

	for tick := 1; tick <= 80; tick++ {
		nextQueue := make([]Msg, 0)
		for _, m := range queue {
			nextQueue = append(nextQueue, nodes[m.To].step(m)...)
		}
		leaders, leaderTerm := 0, -1
		for _, n := range nodes {
			n.Clock = tick
			if n.Role == Leader {
				leaders++
				leaderTerm = n.Term
				for p := 0; p < count; p++ {
					if p != n.ID {
						nextQueue = append(nextQueue, Msg{From: n.ID, To: p, Term: n.Term, IsBeat: true})
					}
				}
			} else if tick >= n.Deadline {
				nextQueue = append(nextQueue, n.startElection()...)
			}
		}
		if leaders == 1 {
			if leaderTerm < 2 {
				t.Fatalf("expected split vote on term 1 before leader election, got term %d", leaderTerm)
			}
			return
		}
		if leaders > 1 {
			t.Fatalf("split-brain: %d leaders at tick %d", leaders, tick)
		}
		queue = nextQueue
	}
	t.Fatal("cluster failed to elect a single leader within 80 ticks")
}
