#include <array>
#include <cstdint>
#include <string_view>

namespace hashutil {

consteval std::array<std::uint32_t, 256> make_crc32_table() noexcept {
    std::array<std::uint32_t, 256> table{};
    for (std::uint32_t i = 0; i < 256; ++i) {
        std::uint32_t crc = i;
        for (int bit = 0; bit < 8; ++bit) {
            crc = (crc & 1u) ? ((crc >> 1u) ^ 0xEDB88320u) : (crc >> 1u);
        }
        table[i] = crc;
    }
    return table;
}

inline constexpr auto kCrc32Table = make_crc32_table();

[[nodiscard]] constexpr std::uint32_t crc32_ieee(std::string_view sv) noexcept {
    std::uint32_t crc = 0xFFFFFFFFu;
    for (unsigned char ch : sv) {
        const auto idx = (crc ^ ch) & 0xFFu;
        crc = (crc >> 8u) ^ kCrc32Table[idx];
    }
    return ~crc;
}

[[nodiscard]] constexpr std::uint64_t fnv1a_64(std::string_view sv) noexcept {
    std::uint64_t hash = 0xCBF29CE484222325ull;
    for (unsigned char ch : sv) {
        hash ^= static_cast<std::uint64_t>(ch);
        hash *= 0x00000100000001B3ull;
    }
    return hash;
}

static_assert(crc32_ieee("") == 0x00000000u);
static_assert(crc32_ieee("123456789") == 0xCBF43926u);
static_assert(fnv1a_64("") == 0xCBF29CE484222325ull);
static_assert(fnv1a_64("foobar") == 0x85944171F73967E8ull);

} // namespace hashutil
