import ast
from dataclasses import dataclass

MUTABLE_LITERALS = (ast.List, ast.Dict, ast.Set)


@dataclass(frozen=True, order=True)
class LintIssue:
    filename: str
    line: int
    col: int
    code: str
    message: str

    def format(self) -> str:
        return f"{self.filename}:{self.line}:{self.col}: {self.code} {self.message}"


class HygieneVisitor(ast.NodeVisitor):
    def __init__(self, filename: str) -> None:
        self.filename = filename
        self.issues: list[LintIssue] = []

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name) and node.func.id == "print":
            self.issues.append(
                LintIssue(self.filename, node.lineno, node.col_offset + 1, "L001", "avoid debug print() call")
            )
        self.generic_visit(node)

    def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:
        if node.type is None:
            self.issues.append(
                LintIssue(self.filename, node.lineno, node.col_offset + 1, "L002", "bare except: catches BaseException")
            )
        self.generic_visit(node)

    def _check_function(self, node: ast.FunctionDef | ast.AsyncFunctionDef) -> None:
        defaults = list(node.args.defaults) + [d for d in node.args.kw_defaults if d is not None]
        for expr in defaults:
            if isinstance(expr, MUTABLE_LITERALS):
                self.issues.append(
                    LintIssue(
                        self.filename,
                        expr.lineno,
                        expr.col_offset + 1,
                        "L003",
                        f"mutable default literal in '{node.name}'; use None sentinel",
                    )
                )
        self.generic_visit(node)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        self._check_function(node)

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        self._check_function(node)


def lint_source(source: str, filename: str = "<stdin>") -> list[LintIssue]:
    tree = ast.parse(source, filename=filename)
    visitor = HygieneVisitor(filename)
    visitor.visit(tree)
    return sorted(visitor.issues)
