use std::env;
use std::fs;
use std::io;

#[derive(Default)]
struct ProcStats {
    pid: u32,
    comm: String,
    rss_kb: u64,
    pss_kb: u64,
    swap_pss_kb: u64,
    read_bytes: u64,
    write_bytes: u64,
}

fn parse_first_u64(val: &str) -> u64 {
    val.split_whitespace()
        .next()
        .and_then(|tok| tok.parse::<u64>().ok())
        .unwrap_or(0)
}

fn collect_pid(pid: u32) -> io::Result<ProcStats> {
    let base = format!("/proc/{pid}");
    let comm = fs::read_to_string(format!("{base}/comm"))?.trim().to_owned();
    let rollup = fs::read_to_string(format!("{base}/smaps_rollup"))?;
    let mut stats = ProcStats {
        pid,
        comm,
        ..Default::default()
    };
    for line in rollup.lines() {
        if let Some((k, v)) = line.split_once(':') {
            match k {
                "Rss" => stats.rss_kb = parse_first_u64(v),
                "Pss" => stats.pss_kb = parse_first_u64(v),
                "SwapPss" => stats.swap_pss_kb = parse_first_u64(v),
                _ => {}
            }
        }
    }
    if let Ok(io_txt) = fs::read_to_string(format!("{base}/io")) {
        for line in io_txt.lines() {
            if let Some((k, v)) = line.split_once(':') {
                match k {
                    "read_bytes" => stats.read_bytes = parse_first_u64(v),
                    "write_bytes" => stats.write_bytes = parse_first_u64(v),
                    _ => {}
                }
            }
