package pgwire

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

const (
	ProtocolV3     uint32 = 196608 // 3.0 -> (3 << 16) | 0
	SSLRequestCode uint32 = 80877103
)

type StartupPacket struct {
	IsSSLRequest bool
	Params       map[string]string
}

type FrontendFrame struct {
	Tag     byte
	Payload []byte
}

func ReadStartupPacket(r io.Reader, maxFrameBytes int) (*StartupPacket, error) {
	var hdr [8]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return nil, err
	}
	totalLen := int(int32(binary.BigEndian.Uint32(hdr[0:4])))
	code := binary.BigEndian.Uint32(hdr[4:8])
	if totalLen < 8 || totalLen > maxFrameBytes {
		return nil, fmt.Errorf("invalid startup length: %d", totalLen)
	}
	if code == SSLRequestCode && totalLen == 8 {
		return &StartupPacket{IsSSLRequest: true}, nil
	}
	if code != ProtocolV3 {
		return nil, fmt.Errorf("unsupported protocol version: %d", code)
	}
	body := make([]byte, totalLen-8)
	if _, err := io.ReadFull(r, body); err != nil {
		return nil, err
	}
	if len(body) == 0 || body[len(body)-1] != 0 {
		return nil, errors.New("startup parameters missing trailing nul")
	}
	parts := bytes.Split(body[:len(body)-1], []byte{0})
	if len(parts) > 0 && len(parts[len(parts)-1]) == 0 {
		parts = parts[:len(parts)-1]
	}
	if len(parts)%2 != 0 {
		return nil, errors.New("unpaired startup key/value tokens")
	}
	params := make(map[string]string, len(parts)/2)
	for i := 0; i < len(parts); i += 2 {
		params[string(parts[i])] = string(parts[i+1])
	}
	return &StartupPacket{Params: params}, nil
}

func ReadFrontendFrame(r io.Reader, maxFrameBytes int) (*FrontendFrame, error) {
	var hdr [5]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return nil, err
	}
	tag := hdr[0]
	frameLen := int(int32(binary.BigEndian.Uint32(hdr[1:5])))
	if frameLen < 4 || frameLen > maxFrameBytes {
		return nil, fmt.Errorf("invalid frame length %d for tag %q", frameLen, tag)
	}
	payload := make([]byte, frameLen-4)
	if _, err := io.ReadFull(r, payload); err != nil {
		return nil, err
	}
	return &FrontendFrame{Tag: tag, Payload: payload}, nil
}
