use std::ops::Range;

pub struct FenwickTree {
    tree: Vec<i64>,
}

impl FenwickTree {
    pub fn new(len: usize) -> Self {
        Self {
            tree: vec![0; len + 1],
        }
    }

    pub fn from_slice(values: &[i64]) -> Self {
        let n = values.len();
        let mut tree = vec![0i64; n + 1];
        tree[1..=n].copy_from_slice(values);
        for i in 1..=n {
            let parent = i + (i & i.wrapping_neg());
            if parent <= n {
                tree[parent] += tree[i];
            }
        }
        Self { tree }
    }

    pub fn len(&self) -> usize {
        self.tree.len() - 1
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    pub fn add(&mut self, idx: usize, delta: i64) {
        assert!(idx < self.len(), "index out of bounds");
        let n = self.len();
        let mut i = idx + 1;
        while i <= n {
            self.tree[i] += delta;
            i += i & i.wrapping_neg();
        }
    }

    pub fn prefix_sum(&self, exclusive_end: usize) -> i64 {
        assert!(exclusive_end <= self.len(), "bound out of range");
        let mut sum = 0i64;
        let mut i = exclusive_end;
        while i > 0 {
            sum += self.tree[i];
            i &= i - 1;
        }
        sum
    }

    pub fn range_sum(&self, range: Range<usize>) -> i64 {
        assert!(range.start <= range.end && range.end <= self.len());
        self.prefix_sum(range.end) - self.prefix_sum(range.start)
    }

    /// Smallest `k` in `0..=len` with `prefix_sum(k) >= target` (for non-negative weights),
    /// or `len + 1` if total sum < target.
    pub fn lower_bound(&self, target: i64) -> usize {
        if target <= 0 {
            return 0;
        }
        let n = self.len();
        let mut pos = 0usize;
        let mut acc = 0i64;
        let mut bit = if n == 0 { 0 } else { 1usize << n.ilog2() };
        while bit > 0 {
            let next = pos + bit;
            if next <= n && acc + self.tree[next] < target {
                acc += self.tree[next];
                pos = next;
            }
            bit >>= 1;
        }
        pos + 1
    }
}
