from collections.abc import Iterable, Iterator
import heapq
import random
import pytest

Entry = tuple[bytes, int, bytes | None]


def merge_sstable_runs(
    runs: Iterable[Iterable[Entry]],
    *, 
    bottommost: bool = False,
) -> Iterator[Entry]:
    merged = heapq.merge(*runs, key=lambda item: (item[0], -item[1]))
    last_user_key: bytes | None = None
    for user_key, seq, value in merged:
        if user_key == last_user_key:
            continue
        last_user_key = user_key
        if bottommost and value is None:
            continue
        yield user_key, seq, value


def reference_oracle(runs: list[list[Entry]], *, bottommost: bool) -> list[Entry]:
    best: dict[bytes, tuple[int, bytes | None]] = {}
    for run in runs:
        for key, seq, val in run:
            if key not in best or seq > best[key][0]:
                best[key] = (seq, val)
    out: list[Entry] = []
    for key in sorted(best):
        seq, val = best[key]
        if bottommost and val is None:
            continue
        out.append((key, seq, val))
    return out


@pytest.mark.parametrize("bottommost", [False, True])
@pytest.mark.parametrize("seed", range(10))
def test_merge_sstable_runs_differential(bottommost: bool, seed: int) -> None:
    rng = random.Random(seed)
    alphabet = [f"k{i:02d}".encode() for i in range(18)]
    seq = 0
    runs: list[list[Entry]] = []
    for _ in range(4):
        by_key: dict[bytes, list[Entry]] = {}
        for _ in range(30):
            seq += 1
            k = rng.choice(alphabet)
            val = None if rng.random() < 0.3 else f"v{seq}".encode()
            by_key.setdefault(k, []).append((k, seq, val))
        run: list[Entry] = []
        for k in sorted(by_key):
            run.extend(sorted(by_key[k], key=lambda x: -x[1]))
        runs.append(run)

    actual = list(merge_sstable_runs(runs, bottommost=bottommost))
    assert actual == reference_oracle(runs, bottommost=bottommost)
