export interface StreamTimingMetrics {
  bytesTransferred: number;
  ttfbMs: number | null;
  totalMs: number;
}

export function createTimedByteStream(maxBytes = Infinity): {
  stream: TransformStream<Uint8Array, Uint8Array>;
  getMetrics: () => StreamTimingMetrics;
} {
  const startedAt = performance.now();
  let ttfbMs: number | null = null;
  let endedAt: number | null = null;
  let bytesTransferred = 0;

  const stream = new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      if (chunk.byteLength === 0) {
        return;
      }
      if (ttfbMs === null) {
        ttfbMs = performance.now() - startedAt;
      }
      bytesTransferred += chunk.byteLength;
      if (bytesTransferred > maxBytes) {
        endedAt = performance.now();
        controller.error(new RangeError(`Stream exceeded byte budget of ${maxBytes} bytes`));
        return;
      }
      controller.enqueue(chunk);
    },
    flush() {
      endedAt = performance.now();
    },
  });

  return {
    stream,
    getMetrics: () => ({
      bytesTransferred,
      ttfbMs,
      totalMs: (endedAt ?? performance.now()) - startedAt,
    }),
  };
}

export function formatServerTiming(metrics: StreamTimingMetrics): string {
  const parts: string[] = [];
  if (metrics.ttfbMs !== null) {
    parts.push(`ttfb;dur=${metrics.ttfbMs.toFixed(2)}`);
  }
  parts.push(`stream;dur=${metrics.totalMs.toFixed(2)};desc="bytes=${metrics.bytesTransferred}"`);
  return parts.join(", ");
}
