use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;

#[repr(align(64))]
struct CachePaddedAtomic {
    value: AtomicU64,
}

impl Default for CachePaddedAtomic {
    fn default() -> Self {
        Self {
            value: AtomicU64::new(0),
        }
    }
}

thread_local! {
    static THREAD_STRIPE_HASH: usize = {
        let mut hasher = DefaultHasher::new();
        thread::current().id().hash(&mut hasher);
        hasher.finish() as usize
    };
}

pub struct StripedCounter<const STRIPES: usize = 16> {
    stripes: [CachePaddedAtomic; STRIPES],
}

impl<const STRIPES: usize> Default for StripedCounter<STRIPES> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const STRIPES: usize> StripedCounter<STRIPES> {
    pub fn new() -> Self {
        assert!(STRIPES.is_power_of_two(), "STRIPES must be a power of two");
        Self {
            stripes: std::array::from_fn(|_| CachePaddedAtomic::default()),
        }
    }

    #[inline]
    pub fn add(&self, delta: u64) {
        let idx = THREAD_STRIPE_HASH.with(|h| *h) & (STRIPES - 1);
        self.stripes[idx].value.fetch_add(delta, Ordering::Relaxed);
    }

    pub fn get(&self) -> u64 {
        self.stripes
            .iter()
            .map(|slot| slot.value.load(Ordering::Relaxed))
            .fold(0u64, u64::wrapping_add)
    }
}
