use std::iter::{FusedIterator, Peekable};

pub struct ByteBudgetChunks<I: Iterator> {
    inner: Peekable<I>,
    max_bytes: usize,
    max_items: usize,
}

impl<I: Iterator> ByteBudgetChunks<I> {
    pub fn new(iter: I, max_bytes: usize, max_items: usize) -> Self {
        assert!(max_bytes > 0 && max_items > 0, "limits must be positive");
        Self {
            inner: iter.peekable(),
            max_bytes,
            max_items,
        }
    }
}

impl<I> Iterator for ByteBudgetChunks<I>
where
    I: Iterator,
    I::Item: AsRef<[u8]>,
{
    type Item = Vec<I::Item>;

    fn next(&mut self) -> Option<Self::Item> {
        let first = self.inner.next()?;
        let mut used_bytes = first.as_ref().len();
        let mut batch = Vec::with_capacity(self.max_items.min(16));
        batch.push(first);

        while batch.len() < self.max_items {
            let Some(next_item) = self.inner.peek() else {
                break;
            };
            let next_len = next_item.as_ref().len();
            if used_bytes.saturating_add(next_len) > self.max_bytes {
                break;
            }
            used_bytes += next_len;
            batch.push(self.inner.next().expect("peeked item exists"));
        }
        Some(batch)
    }
}

impl<I> FusedIterator for ByteBudgetChunks<I>
where
    I: Iterator,
    I::Item: AsRef<[u8]>,
{
}

pub trait ByteBudgetExt: Iterator + Sized {
    fn byte_budget_chunks(self, max_bytes: usize, max_items: usize) -> ByteBudgetChunks<Self> {
        ByteBudgetChunks::new(self, max_bytes, max_items)
    }
}

impl<I: Iterator> ByteBudgetExt for I {}
