package quorum

import (
	"context"
	"errors"
	"fmt"
)

type result[T any] struct {
	val T
	err error
}

func QuorumCall[T any](
	ctx context.Context,
	peers []string,
	required int,
	rpc func(ctx context.Context, peer string) (T, error),
) ([]T, error) {
	if required <= 0 || required > len(peers) {
		return nil, fmt.Errorf("invalid quorum %d for %d peers", required, len(peers))
	}

	callCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	ch := make(chan result[T], len(peers))
	for _, p := range peers {
		peer := p
		go func() {
			v, err := rpc(callCtx, peer)
			ch <- result[T]{val: v, err: err}
		}()
	}

	oks := make([]T, 0, required)
	var errs []error
	for i := 0; i < len(peers); i++ {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case res := <-ch:
			if res.err == nil {
				oks = append(oks, res.val)
				if len(oks) == required {
					return oks, nil
				}
			} else {
				errs = append(errs, res.err)
			}
			remaining := len(peers) - (i + 1)
			if len(oks)+remaining < required {
				return nil, fmt.Errorf("quorum %d unreachable: %w", required, errors.Join(errs...))
			}
		}
	}
	return nil, errors.Join(errs...)
}
