package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"os/signal"
	"syscall"
	"time"
)

const exitTempFail = 75

func acquireFlock(path string, wait time.Duration) (*os.File, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, err
	}
	deadline := time.Now().Add(wait)
	for {
		err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB)
		if err == nil {
			return f, nil
		}
		if !errors.Is(err, syscall.EWOULDBLOCK) && !errors.Is(err, syscall.EAGAIN) {
			_ = f.Close()
			return nil, err
		}
		if time.Now().After(deadline) {
			_ = f.Close()
			return nil, fmt.Errorf("lock %s busy after %s", path, wait)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func main() {
	lockPath := flag.String("lock", "", "path to advisory lockfile")
	wait := flag.Duration("wait", 0, "max wait duration to acquire lock")
	flag.Parse()
	args := flag.Args()
	if *lockPath == "" || len(args) == 0 {
		fmt.Fprintln(os.Stderr, "usage: run-locked --lock <file> [--wait 5s] -- <cmd> [args...]")
		os.Exit(2)
	}

	lockFile, err := acquireFlock(*lockPath, *wait)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(exitTempFail)
	}
	defer lockFile.Close()

	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
	if err := cmd.Start(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(127)
	}

	sigCh := make(chan os.Signal, 2)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		for sig := range sigCh {
			_ = cmd.Process.Signal(sig)
		}
	}()

	if err := cmd.Wait(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
