export type SharedCacheState = "bypass" | "fresh" | "stale-revalidate" | "expired";

export function parseCacheControl(header: string): Map<string, string | true> {
  const out = new Map<string, string | true>();
  let i = 0;
  const n = header.length;

  const skipWsAndCommas = () => {
    while (i < n && (header[i] === " " || header[i] === "\t" || header[i] === ",")) {
      i++;
    }
  };

  while (i < n) {
    skipWsAndCommas();
    if (i >= n) break;
    const keyStart = i;
    while (i < n && header[i] !== "=" && header[i] !== "," && header[i] !== " " && header[i] !== "\t") {
      i++;
    }
    const key = header.slice(keyStart, i).toLowerCase();
    while (i < n && (header[i] === " " || header[i] === "\t")) i++;

    if (i >= n || header[i] !== "=") {
      if (key) out.set(key, true);
      while (i < n && header[i] !== ",") i++;
      continue;
    }
    i++; // consume '='
    while (i < n && (header[i] === " " || header[i] === "\t")) i++;

    let val = "";
    if (i < n && header[i] === '"') {
      i++;
      while (i < n && header[i] !== '"') {
        if (header[i] === "\\" && i + 1 < n) {
          i++;
        }
        val += header[i++];
      }
      if (i < n && header[i] === '"') i++;
    } else {
      const valStart = i;
      while (i < n && header[i] !== "," && header[i] !== " " && header[i] !== "\t") i++;
      val = header.slice(valStart, i);
    }
    if (key) out.set(key, val);
    while (i < n && header[i] !== ",") i++;
  }
  return out;
}

function parseDeltaSeconds(v: string | true | undefined): number | null {
  if (typeof v !== "string" || v.length === 0) return null;
  for (let i = 0; i < v.length; i++) {
    const code = v.charCodeAt(i);
    if (code < 48 || code > 57) return null;
  }
  return Number(v);
}

export function evaluateSharedCacheState(header: string, ageSeconds: number): SharedCacheState {
  const dirs = parseCacheControl(header);
  if (dirs.has("no-store") || dirs.has("private") || dirs.has("no-cache")) {
    return "bypass";
  }
  const lifetime = parseDeltaSeconds(dirs.get("s-maxage")) ?? parseDeltaSeconds(dirs.get("max-age"));
  if (lifetime === null) {
    return "bypass";
  }
  if (ageSeconds < lifetime) {
    return "fresh";
  }
  const swr = parseDeltaSeconds(dirs.get("stale-while-revalidate")) ?? 0;
  if (ageSeconds < lifetime + swr) {
    return "stale-revalidate";
  }
  return "expired";
}
