type ReservoirSampler[T any] struct {
	capacity int
	seen     uint64
	buf      []T
	rng      *rand.Rand
}

func NewReservoirSampler[T any](capacity int, rng *rand.Rand) *ReservoirSampler[T] {
	if capacity <= 0 {
		panic("reservoir capacity must be > 0")
	}
	if rng == nil {
		rng = rand.New(rand.NewPCG(1, 2))
	}
	return &ReservoirSampler[T]{
		capacity: capacity,
		buf:      make([]T, 0, capacity),
		rng:      rng,
	}
}

func (s *ReservoirSampler[T]) Observe(item T) {
	s.seen++
	if len(s.buf) < s.capacity {
		s.buf = append(s.buf, item)
		return
	}
	j := s.rng.Uint64N(s.seen)
	if j < uint64(s.capacity) {
		s.buf[int(j)] = item
	}
}

func (s *ReservoirSampler[T]) Seen() uint64 {
	return s.seen
}

func (s *ReservoirSampler[T]) Sample() []T {
	out := make([]T, len(s.buf))
	copy(out, s.buf)
	return out
}
