use std::env;
use std::fs;
use std::path::Path;

pub fn strip_byte_spans(sexpr: &str) -> String {
    let bytes = sexpr.as_bytes();
    let mut out = String::with_capacity(sexpr.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'@' {
            let mut j = i + 1;
            while j < bytes.len() && bytes[j].is_ascii_digit() {
                j += 1;
            }
            if j > i + 1 && bytes.get(j..j + 2) == Some(b"..") {
                let mut k = j + 2;
                while k < bytes.len() && bytes[k].is_ascii_digit() {
                    k += 1;
                }
                if k > j + 2 {
                    i = k;
                    continue;
                }
            }
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out
}

pub fn assert_golden_sexpr(golden_path: &Path, raw_actual: &str, ignore_spans: bool) {
    let actual = if ignore_spans {
        strip_byte_spans(raw_actual)
    } else {
        raw_actual.to_owned()
    };
    if env::var_os("UPDATE_GOLDENS").as_deref() == Some("1".as_ref()) {
        if let Some(parent) = golden_path.parent() {
            fs::create_dir_all(parent).expect("create golden parent dir");
        }
        fs::write(golden_path, &actual).expect("write updated golden file");
        return;
    }
    let expected = fs::read_to_string(golden_path)
        .unwrap_or_else(|e| panic!("missing golden {}: {e}", golden_path.display()));
    if expected == actual {
        return;
    }
    let exp_lines: Vec<&str> = expected.lines().collect();
    let act_lines: Vec<&str> = actual.lines().collect();
    let max_len = exp_lines.len().max(act_lines.len());
    let mut diff = String::new();
    for idx in 0..max_len {
        let e = exp_lines.get(idx).copied();
        let a = act_lines.get(idx).copied();
        if e != a {
            diff.push_str(&format!("L{:03} - expected: {:?}\n", idx + 1, e));
            diff.push_str(&format!("L{:03} +   actual: {:?}\n", idx + 1, a));
        }
    }
    panic!("AST golden mismatch in {}:\n{diff}", golden_path.display());
}
