const SUB_BITS = 4;
const SUB_COUNT = 1 << SUB_BITS; // 16 sub-buckets per octave
const TOTAL_BUCKETS = (32 - SUB_BITS) * SUB_COUNT;

export class MicrosHistogram {
  private readonly counts = new Uint32Array(TOTAL_BUCKETS);
  private totalCount = 0;

  get count(): number {
    return this.totalCount;
  }

  record(latencyUs: number): void {
    const clamped = latencyUs <= 0 ? 0 : latencyUs >= 0x7fffffff ? 0x7fffffff : latencyUs | 0;
    const idx = MicrosHistogram.bucketFor(clamped);
    this.counts[idx]++;
    this.totalCount++;
  }

  percentile(p: number): number {
    if (this.totalCount === 0) return 0;
    const target = Math.ceil((Math.min(100, Math.max(0, p)) / 100) * this.totalCount);
    let cumulative = 0;
    for (let idx = 0; idx < TOTAL_BUCKETS; idx++) {
      cumulative += this.counts[idx];
      if (cumulative >= target) {
        return MicrosHistogram.upperBoundFor(idx);
      }
    }
    return MicrosHistogram.upperBoundFor(TOTAL_BUCKETS - 1);
  }

  reset(): void {
    this.counts.fill(0);
    this.totalCount = 0;
  }

  static bucketFor(v: number): number {
    if (v < SUB_COUNT) {
      return v;
    }
    const msb = 31 - Math.clz32(v);
    const shift = msb - SUB_BITS;
    const sub = (v >>> shift) & (SUB_COUNT - 1);
    return (shift + 1) * SUB_COUNT + sub;
  }

  static upperBoundFor(idx: number): number {
    if (idx < SUB_COUNT) {
      return idx;
    }
    const group = Math.floor(idx / SUB_COUNT) - 1;
    const sub = idx & (SUB_COUNT - 1);
    return ((SUB_COUNT + sub + 1) << group) - 1;
  }
}
