#include <span>
#include <type_traits>

template <typename T>
concept WireScalar =
    (std::integral<T> || std::floating_point<T>) &&
    !std::same_as<std::remove_cv_t<T>, bool> &&
    std::is_trivially_copyable_v<T>;

class BytecodeReader {
public:
    explicit constexpr BytecodeReader(std::span<const std::byte> buf) noexcept
        : buf_(buf) {}

    [[nodiscard]] constexpr std::size_t remaining() const noexcept {
        return buf_.size() - pos_;
    }

    template <WireScalar T>
    [[nodiscard]] std::optional<T> read_le() noexcept {
        if (remaining() < sizeof(T)) {
            return std::nullopt;
        }
        std::array<std::byte, sizeof(T)> raw{};
        std::copy_n(buf_.data() + pos_, sizeof(T), raw.data());
        pos_ += sizeof(T);
        if constexpr (std::endian::native == std::endian::big && sizeof(T) > 1) {
            std::reverse(raw.begin(), raw.end());
        }
        return std::bit_cast<T>(raw);
    }

private:
    std::span<const std::byte> buf_;
    std::size_t pos_{0};
};

static_assert(WireScalar<std::uint32_t>);
static_assert(WireScalar<double>);
static_assert(!WireScalar<bool>);
static_assert(!WireScalar<const void*>);
