use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::sync::{OwnedSemaphorePermit, Semaphore};

struct State {
    limit: usize,
    debt: usize,
    window_ok: usize,
}

pub struct AimdLimiter {
    sem: Arc<Semaphore>,
    state: Mutex<State>,
    min_limit: usize,
    max_limit: usize,
    rtt_budget: Duration,
}

pub struct AimdGuard<'a> {
    limiter: &'a AimdLimiter,
    permit: Option<OwnedSemaphorePermit>,
}

impl AimdLimiter {
    pub fn new(initial: usize, min_limit: usize, max_limit: usize, rtt_budget: Duration) -> Self {
        let init = initial.clamp(min_limit, max_limit);
        Self {
            sem: Arc::new(Semaphore::new(init)),
            state: Mutex::new(State { limit: init, debt: 0, window_ok: 0 }),
            min_limit,
            max_limit,
            rtt_budget,
        }
    }

    pub async fn acquire(&self) -> AimdGuard<'_> {
        let permit = self.sem.clone().acquire_owned().await.expect("semaphore open");
        AimdGuard { limiter: self, permit: Some(permit) }
    }

    fn record(&self, rtt: Duration, overloaded: bool, permit: OwnedSemaphorePermit) {
        let mut st = self.state.lock().unwrap();
        if overloaded || rtt > self.rtt_budget {
            let next = (st.limit / 2).max(self.min_limit);
            st.debt += st.limit - next;
            st.limit = next;
            st.window_ok = 0;
        } else {
            st.window_ok += 1;
            if st.window_ok >= st.limit && st.limit < self.max_limit {
                st.limit += 1;
                st.window_ok = 0;
                if st.debt > 0 {
                    st.debt -= 1;
                } else {
                    self.sem.add_permits(1);
                }
            }
        }
        if st.debt > 0 {
            st.debt -= 1;
            permit.forget();
        } else {
            drop(permit);
        }
    }
}

impl AimdGuard<'_> {
    pub fn complete(mut self, rtt: Duration, overloaded: bool) {
        if let Some(p) = self.permit.take() {
            self.limiter.record(rtt, overloaded, p);
        }
    }
}
