#include <array>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <optional>
#include <span>

class SlottedPage {
public:
    static constexpr std::uint16_t kPageSize = 4096;
    static constexpr std::uint16_t kDeleted = 0xFFFFu;

    SlottedPage() noexcept {
        set_u16(0, 0);         // slot_count
        set_u16(2, kPageSize); // free_end
    }

    [[nodiscard]] std::optional<std::uint16_t> insert(std::span<const std::byte> tuple) noexcept {
        if (tuple.size() >= kDeleted) return std::nullopt;
        const auto count = get_u16(0);
        const auto free_end = get_u16(2);
        const auto slots_end = static_cast<std::uint16_t>(4u + (count + 1u) * 4u);
        if (free_end < slots_end || static_cast<std::size_t>(free_end - slots_end) < tuple.size()) {
            return std::nullopt;
        }
        const auto dst = static_cast<std::uint16_t>(free_end - tuple.size());
        if (!tuple.empty()) {
            std::memcpy(buf_.data() + dst, tuple.data(), tuple.size());
        }
        const auto slot_off = static_cast<std::uint16_t>(4u + count * 4u);
        set_u16(slot_off, dst);
        set_u16(slot_off + 2u, static_cast<std::uint16_t>(tuple.size()));
        set_u16(0, count + 1u);
        set_u16(2, dst);
        return count;
    }

    [[nodiscard]] std::optional<std::span<const std::byte>> get(std::uint16_t slot_id) const noexcept {
        if (slot_id >= get_u16(0)) return std::nullopt;
        const auto slot_off = static_cast<std::uint16_t>(4u + slot_id * 4u);
        const auto off = get_u16(slot_off);
        const auto len = get_u16(slot_off + 2u);
        if (len == kDeleted) return std::nullopt;
        return std::span<const std::byte>(buf_.data() + off, len);
    }

    bool erase(std::uint16_t slot_id) noexcept {
        if (slot_id >= get_u16(0)) return false;
        const auto len_off = static_cast<std::uint16_t>(4u + slot_id * 4u + 2u);
        if (get_u16(len_off) == kDeleted) return false;
        set_u16(len_off, kDeleted);
        return true;
    }

private:
    [[nodiscard]] std::uint16_t get_u16(std::uint16_t p) const noexcept {
        return std::to_integer<std::uint16_t>(buf_[p]) |
               static_cast<std::uint16_t>(std::to_integer<std::uint16_t>(buf_[p + 1]) << 8u);
    }
    void set_u16(std::uint16_t p, std::uint16_t v) noexcept {
        buf_[p] = static_cast<std::byte>(v & 0xFFu);
        buf_[p + 1] = static_cast<std::byte>(v >> 8u);
    }

    alignas(8) std::array<std::byte, kPageSize> buf_{};
};
