export async function readAllWithStallTimeout(res: Response, stallTimeoutMs: number): Promise<Uint8Array> {
  if (!res.body) return new Uint8Array(0);
  const reader = res.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;

  try {
    while (true) {
      let timer: ReturnType<typeof setTimeout> | undefined;
      const timeout = new Promise<never>((_, reject) => {
        timer = setTimeout(() => {
          reject(new DOMException(`Stream stalled > ${stallTimeoutMs}ms`, "TimeoutError"));
        }, stallTimeoutMs);
      });
      const { done, value } = await Promise.race([reader.read(), timeout]).finally(() => {
        if (timer !== undefined) clearTimeout(timer);
      });
      if (done) break;
      chunks.push(value);
      total += value.byteLength;
    }
  } catch (err) {
    await reader.cancel(err).catch(() => {});
    throw err;
  }

  const out = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) {
    out.set(c, offset);
    offset += c.byteLength;
  }
  return out;
}

export function createControlledResponse(): {
  response: Response;
  push: (chunk: Uint8Array) => void;
  close: () => void;
} {
  let ctrl!: ReadableStreamDefaultController<Uint8Array>;
  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      ctrl = c;
    },
  });
  return {
    response: new Response(stream, { status: 200 }),
    push: (chunk) => ctrl.enqueue(chunk),
    close: () => ctrl.close(),
  };
}
