package symbols

import "unsafe"

const slabBytes = 64 * 1024

type SymbolID uint32

type SymbolInterner struct {
	index map[string]SymbolID
	sym   []string
	slab  []byte
}

func NewSymbolInterner(expected int) *SymbolInterner {
	return &SymbolInterner{
		index: make(map[string]SymbolID, expected),
		sym:   make([]string, 0, expected),
	}
}

func (in *SymbolInterner) InternBytes(tok []byte) SymbolID {
	if len(tok) == 0 {
		return in.InternString("")
	}
	// Zero-alloc map probe via temporary unsafe string view
	temp := unsafe.String(unsafe.SliceData(tok), len(tok))
	if id, ok := in.index[temp]; ok {
		return id
	}
	return in.allocAndStore(tok)
}

func (in *SymbolInterner) InternString(s string) SymbolID {
	if id, ok := in.index[s]; ok {
		return id
	}
	return in.allocAndStore(unsafe.Slice(unsafe.StringData(s), len(s)))
}

func (in *SymbolInterner) allocAndStore(src []byte) SymbolID {
	n := len(src)
	var backed string
	if n > 0 {
		if len(in.slab) < n {
			alloc := slabBytes
			if n > alloc {
				alloc = n
			}
			in.slab = make([]byte, alloc)
		}
		dst := in.slab[:n:n]
		in.slab = in.slab[n:]
		copy(dst, src)
		backed = unsafe.String(unsafe.SliceData(dst), n)
	}
	id := SymbolID(len(in.sym))
	in.sym = append(in.sym, backed)
	in.index[backed] = id
	return id
}

func (in *SymbolInterner) Resolve(id SymbolID) string {
	return in.sym[id]
}
