export type ValType = "number" | "boolean";
export type Expr =
  | { kind: "num"; value: number }
  | { kind: "bool"; value: boolean }
  | { kind: "unary"; op: "-" | "!"; rhs: Expr }
  | { kind: "binary"; op: "+" | "*" | "^" | "<" | "=="; lhs: Expr; rhs: Expr };

const INFIX_BP: Record<string, [number, number]> = {
  "==": [10, 11],
  "<": [20, 21],
  "+": [30, 31],
  "*": [40, 41],
  "^": [51, 50], // right-associative: rBp < lBp
};

export function parsePratt(tokens: string[]): Expr {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseExpr(minBp: number): Expr {
    const tok = next();
    if (tok === undefined) throw new SyntaxError("Unexpected EOF");
    let lhs: Expr;
    if (tok === "-" || tok === "!") {
      lhs = { kind: "unary", op: tok, rhs: parseExpr(60) };
    } else if (tok === "(") {
      lhs = parseExpr(0);
      if (next() !== ")") throw new SyntaxError("Expected ')'");
    } else if (tok === "true" || tok === "false") {
      lhs = { kind: "bool", value: tok === "true" };
    } else if (!Number.isNaN(Number(tok))) {
      lhs = { kind: "num", value: Number(tok) };
    } else {
      throw new SyntaxError(`Unexpected token: ${tok}`);
    }
    while (peek() !== undefined && peek() in INFIX_BP) {
      const op = peek() as Expr & { kind: "binary" }["op"];
      const [lBp, rBp] = INFIX_BP[op];
      if (lBp < minBp) break;
      next();
      lhs = { kind: "binary", op: op as "+" | "*" | "^" | "<" | "==", lhs, rhs: parseExpr(rBp) };
    }
    return lhs;
  }

  const ast = parseExpr(0);
  if (pos !== tokens.length) throw new SyntaxError(`Trailing token: ${peek()}`);
  return ast;
}

export function inferType(expr: Expr): ValType {
  switch (expr.kind) {
    case "num": return "number";
    case "bool": return "boolean";
    case "unary": {
      const rt = inferType(expr.rhs);
      if (expr.op === "-" && rt === "number") return "number";
      if (expr.op === "!" && rt === "boolean") return "boolean";
      throw new TypeError(`Operator '${expr.op}' incompatible with ${rt}`);
    }
    case "binary": {
      const lt = inferType(expr.lhs), rt = inferType(expr.rhs);
      if (lt !== rt) throw new TypeError(`Operand mismatch: ${lt} ${expr.op} ${rt}`);
      if (expr.op === "==") return "boolean";
      if (lt !== "number") throw new TypeError(`Operator '${expr.op}' requires numbers`);
      return expr.op === "<" ? "boolean" : "number";
    }
  }
}
