#include <charconv>
#include <cstddef>
#include <cstdint>
#include <string_view>

enum class RespStatus : std::uint8_t { Ok, Incomplete, Malformed };
enum class RespKind : std::uint8_t { Simple, Error, Integer, Bulk, NullBulk };

struct RespFrame {
    RespKind kind{};
    std::string_view str{};
    std::int64_t integer{0};
    std::size_t consumed{0};
};

struct RespParseOutcome {
    RespStatus status{};
    RespFrame frame{};
};

[[nodiscard]] inline RespParseOutcome parse_resp2_frame(std::string_view buf) noexcept {
    if (buf.empty()) return {RespStatus::Incomplete, {}};
    const auto crlf = buf.find("\r\n");
    if (crlf == std::string_view::npos) return {RespStatus::Incomplete, {}};

    const char prefix = buf[0];
    const std::string_view head = buf.substr(1, crlf - 1);
    const std::size_t after_line = crlf + 2;

    if (prefix == '+' || prefix == '-') {
        const auto kind = (prefix == '+') ? RespKind::Simple : RespKind::Error;
        return {RespStatus::Ok, {kind, head, 0, after_line}};
    }
    if (prefix == ':') {
        std::int64_t val = 0;
        auto [ptr, ec] = std::from_chars(head.data(), head.data() + head.size(), val);
        if (ec != std::errc{} || ptr != head.data() + head.size()) {
            return {RespStatus::Malformed, {}};
        }
        return {RespStatus::Ok, {RespKind::Integer, {}, val, after_line}};
    }
    if (prefix == '$') {
        std::int64_t len = 0;
        auto [ptr, ec] = std::from_chars(head.data(), head.data() + head.size(), len);
        if (ec != std::errc{} || ptr != head.data() + head.size() || len < -1) {
            return {RespStatus::Malformed, {}};
        }
        if (len == -1) {
            return {RespStatus::Ok, {RespKind::NullBulk, {}, 0, after_line}};
        }
        const auto ulen = static_cast<std::size_t>(len);
        if (buf.size() < after_line + ulen + 2) return {RespStatus::Incomplete, {}};
        if (buf.substr(after_line + ulen, 2) != "\r\n") return {RespStatus::Malformed, {}};
        return {RespStatus::Ok, {RespKind::Bulk, buf.substr(after_line, ulen), 0, after_line + ulen + 2}};
    }
    return {RespStatus::Malformed, {}};
}
