const LOGICAL_BITS = 16n;
const MAX_LOGICAL = (1n << LOGICAL_BITS) - 1n;

export class HybridLogicalClock {
  private lastWallMs = 0n;
  private logical = 0n;

  constructor(
    private readonly physClockMs: () => bigint = () => BigInt(Date.now()),
    private readonly maxDriftMs: bigint = 60_000n,
  ) {}

  now(): bigint {
    const phys = this.physClockMs();
    if (phys > this.lastWallMs) {
      this.lastWallMs = phys;
      this.logical = 0n;
    } else {
      this.logical += 1n;
      if (this.logical > MAX_LOGICAL) {
        throw new RangeError("HLC logical counter overflow");
      }
    }
    return HybridLogicalClock.pack(this.lastWallMs, this.logical);
  }

  update(remoteStamp: bigint): bigint {
    const phys = this.physClockMs();
    const { wallMs: rWall, logical: rLog } = HybridLogicalClock.unpack(remoteStamp);
    if (rWall - phys > this.maxDriftMs) {
      throw new RangeError(`Remote HLC drift ${rWall - phys}ms exceeds ${this.maxDriftMs}ms`);
    }
    const nextWall = phys >= this.lastWallMs && phys >= rWall
      ? phys
      : this.lastWallMs >= rWall ? this.lastWallMs : rWall;

    if (nextWall === this.lastWallMs && nextWall === rWall) {
      this.logical = (this.logical > rLog ? this.logical : rLog) + 1n;
    } else if (nextWall === this.lastWallMs) {
      this.logical += 1n;
    } else if (nextWall === rWall) {
      this.logical = rLog + 1n;
    } else {
      this.logical = 0n;
    }
    if (this.logical > MAX_LOGICAL) throw new RangeError("HLC logical counter overflow");
    this.lastWallMs = nextWall;
    return HybridLogicalClock.pack(this.lastWallMs, this.logical);
  }

  static pack(wallMs: bigint, logical: bigint): bigint {
    return (wallMs << LOGICAL_BITS) | (logical & MAX_LOGICAL);
  }

  static unpack(stamp: bigint): { wallMs: bigint; logical: bigint } {
    return { wallMs: stamp >> LOGICAL_BITS, logical: stamp & MAX_LOGICAL };
  }

  static toSortableHex(stamp: bigint): string {
    return stamp.toString(16).padStart(16, "0");
  }
}
