package blobhttp

import (
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"
)

func parseSingleRange(hdr string, size int64) (start, length int64, ok bool) {
	if !strings.HasPrefix(hdr, "bytes=") || strings.Contains(hdr, ",") || size <= 0 {
		return 0, 0, false
	}
	a, b, found := strings.Cut(strings.TrimPrefix(hdr, "bytes="), "-")
	if !found {
		return 0, 0, false
	}
	if a == "" {
		suffix, err := strconv.ParseInt(b, 10, 64)
		if err != nil || suffix <= 0 {
			return 0, 0, false
		}
		if suffix > size {
			suffix = size
		}
		return size - suffix, suffix, true
	}
	s, err := strconv.ParseInt(a, 10, 64)
	if err != nil || s < 0 || s >= size {
		return 0, 0, false
	}
	e := size - 1
	if b != "" {
		e, err = strconv.ParseInt(b, 10, 64)
		if err != nil || e < s {
			return 0, 0, false
		}
		if e >= size {
			e = size - 1
		}
	}
	return s, (e - s) + 1, true
}

func ServeImmutableBlob(w http.ResponseWriter, req *http.Request, r io.ReaderAt, size int64, etag string) {
	w.Header().Set("Accept-Ranges", "bytes")
	w.Header().Set("ETag", etag)
	rangeHdr := req.Header.Get("Range")
	if ifRange := req.Header.Get("If-Range"); ifRange != "" && ifRange != etag {
		rangeHdr = ""
	}
	if rangeHdr == "" {
		w.Header().Set("Content-Length", strconv.FormatInt(size, 10))
		w.WriteHeader(http.StatusOK)
		_, _ = io.Copy(w, io.NewSectionReader(r, 0, size))
		return
	}
	start, length, ok := parseSingleRange(rangeHdr, size)
	if !ok {
		w.Header().Set("Content-Range", fmt.Sprintf("bytes */%d", size))
		w.WriteHeader(http.StatusRequestedRangeNotSatisfiable)
		return
	}
	w.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, start+length-1, size))
	w.Header().Set("Content-Length", strconv.FormatInt(length, 10))
	w.WriteHeader(http.StatusPartialContent)
	_, _ = io.Copy(w, io.NewSectionReader(r, start, length))
}
