import mmap
from pathlib import Path
import struct
from types import TracebackType

RECORD = struct.Struct("<16sQ")
KEY_WIDTH = 16


class MmapSortedIndex:
    def __init__(self, path: Path) -> None:
        self._file = path.open("rb")
        size = path.stat().st_size
        if size % RECORD.size != 0:
            self._file.close()
            raise ValueError(f"corrupt index size {size}: not a multiple of {RECORD.size}")
        self._count = size // RECORD.size
        self._mm = mmap.mmap(self._file.fileno(), 0, access=mmap.ACCESS_READ) if size > 0 else None

    def __len__(self) -> int:
        return self._count

    def close(self) -> None:
        if self._mm is not None:
            self._mm.close()
            self._mm = None
        self._file.close()

    def __enter__(self) -> "MmapSortedIndex":
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.close()

    def lookup(self, key: bytes) -> int | None:
        if len(key) != KEY_WIDTH:
            raise ValueError(f"expected {KEY_WIDTH}-byte key")
        if self._mm is None:
            return None
        lo, hi = 0, self._count - 1
        while lo <= hi:
            mid = (lo + hi) >> 1
            rec_key, data_offset = RECORD.unpack_from(self._mm, mid * RECORD.size)
            if rec_key == key:
                return data_offset
            if rec_key < key:
                lo = mid + 1
            else:
                hi = mid - 1
        return None
