func ComputeIDom(numBlocks int, rpo []int, preds [][]int) []int {
	rpoIdx := make([]int, numBlocks)
	idom := make([]int, numBlocks)
	for i := range idom {
		idom[i] = -1
	}
	for order, blk := range rpo {
		rpoIdx[blk] = order
	}
	idom[rpo[0]] = rpo[0]

	intersect := func(b1, b2 int) int {
		for b1 != b2 {
			for rpoIdx[b1] > rpoIdx[b2] {
				b1 = idom[b1]
			}
			for rpoIdx[b2] > rpoIdx[b1] {
				b2 = idom[b2]
			}
