import asyncio
from collections.abc import Awaitable, Callable
from typing import TypeVar

T = TypeVar("T")


async def hedged_rpc(
    primary: Callable[[], Awaitable[T]],
    backup: Callable[[], Awaitable[T]],
    hedge_delay_sec: float,
) -> T:
    t1 = asyncio.create_task(primary())
    done, _ = await asyncio.wait({t1}, timeout=max(0.0, hedge_delay_sec))
    if t1 in done and t1.exception() is None:
        return t1.result()

    t2 = asyncio.create_task(backup())
    active: set[asyncio.Task[T]] = {t2} if t1 in done else {t1, t2}
    first_err: BaseException | None = t1.exception() if t1 in done else None

    try:
        while active:
            finished, active = await asyncio.wait(active, return_when=asyncio.FIRST_COMPLETED)
            for task in finished:
                exc = task.exception()
                if exc is None:
                    return task.result()
                if first_err is None:
                    first_err = exc
        assert first_err is not None
        raise first_err
    finally:
        losers = [t for t in (t1, t2) if not t.done()]
        for t in losers:
            t.cancel()
        if losers:
            await asyncio.gather(*losers, return_exceptions=True)
