#!/usr/bin/env node
import { createInterface } from "node:readline";
import { parseArgs } from "node:util";

const { values } = parseArgs({
  options: {
    "window-sec": { type: "string", default: "10" },
  },
});
const windowMs = Math.max(1, Number(values["window-sec"])) * 1000;

let latencies: number[] = [];
let errors5xx = 0;
let flushed = false;

function quantile(sorted: number[], q: number): number {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.ceil(q * sorted.length) - 1);
  return sorted[Math.max(0, idx)];
}

function flushWindow(): void {
  if (latencies.length === 0) return;
  latencies.sort((a, b) => a - b);
  const summary = {
    ts: new Date().toISOString(),
    requests: latencies.length,
    errors_5xx: errors5xx,
    p95_ms: quantile(latencies, 0.95),
    p99_ms: quantile(latencies, 0.99),
  };
  process.stdout.write(`${JSON.stringify(summary)}\n`);
  latencies = [];
  errors5xx = 0;
}

const timer = setInterval(flushWindow, windowMs);
timer.unref();

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
rl.on("line", (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;
  try {
    const rec = JSON.parse(trimmed) as { status?: number; latency_ms?: number };
    if (typeof rec.latency_ms === "number" && Number.isFinite(rec.latency_ms)) {
      latencies.push(rec.latency_ms);
      if (typeof rec.status === "number" && rec.status >= 500) errors5xx++;
    }
  } catch {
    // Skip malformed NDJSON lines
  }
});

function finish(): void {
  if (flushed) return;
  flushed = true;
  clearInterval(timer);
  flushWindow();
}

rl.on("close", finish);
process.once("SIGINT", () => {
  rl.close();
  finish();
});
