#[inline]
fn splitmix64(mut x: u64) -> u64 {
    x = x.wrapping_add(0x9E3779B97F4A7C15);
    x = (x ^ (x >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94D049BB133111EB);
    x ^ (x >> 31)
}

#[inline]
fn hash_bytes_with_seed(seed: u64, data: &[u8]) -> u64 {
    let mut h = seed ^ (data.len() as u64);
    for &b in data {
        h ^= b as u64;
        h = splitmix64(h);
    }
    h
}

impl<const D: usize, const W: usize> Default for CountMinSketch<D, W> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const D: usize, const W: usize> CountMinSketch<D, W> {
    pub fn new() -> Self {
        assert!(D > 0 && W.is_power_of_two(), "W must be a power of two");
