            table: [[0u32; W]; D],
            seeds,
        }
    }

    #[inline]
    fn col_index(&self, row: usize, item: &[u8]) -> usize {
        (hash_bytes_with_seed(self.seeds[row], item) as usize) & (W - 1)
    }

    pub fn insert_conservative(&mut self, item: &[u8], delta: u32) -> u32 {
        let mut cols = [0usize; D];
        let mut min_val = u32::MAX;
        for r in 0..D {
            let c = self.col_index(r, item);
            cols[r] = c;
            min_val = min_val.min(self.table[r][c]);
        }
        let target = min_val.saturating_add(delta);
        for r in 0..D {
            let cell = &mut self.table[r][cols[r]];
            if *cell < target {
                *cell = target;
            }
        }
        target
    }

    pub fn estimate(&self, item: &[u8]) -> u32 {
        (0..D)
            .map(|r| self.table[r][self.col_index(r, item)])
            .min()
            .unwrap_or(0)
    }
