from dataclasses import dataclass
from functools import lru_cache
from typing import Literal
import pytest


@dataclass(frozen=True)
class RegOp:
    kind: Literal["write", "read"]
    val: int | None
    inv_ts: int
    res_ts: int


def is_linearizable(ops: list[RegOp], initial: int | None = None) -> bool:
    n = len(ops)
    full_mask = (1 << n) - 1

    @lru_cache(maxsize=None)
    def search(rem_mask: int, reg_val: int | None) -> bool:
        if rem_mask == 0:
            return True
        earliest_res = min(ops[i].res_ts for i in range(n) if (rem_mask >> i) & 1)
        for i in range(n):
            if not ((rem_mask >> i) & 1):
                continue
            op = ops[i]
            if op.inv_ts > earliest_res:
                continue  # Cannot linearize after an already-returned op
            if op.kind == "write":
                if search(rem_mask ^ (1 << i), op.val):
                    return True
            elif op.val == reg_val:
                if search(rem_mask ^ (1 << i), reg_val):
                    return True
        return False

    return search(full_mask, initial)


def test_overlapping_write_and_read_linearizable() -> None:
    history = [
        RegOp("write", 10, inv_ts=1, res_ts=6),
        RegOp("read", 10, inv_ts=2, res_ts=5),
        RegOp("read", None, inv_ts=0, res_ts=3),
    ]
