#include <vector>

class UniqueFd {
public:
    UniqueFd() noexcept = default;
    explicit UniqueFd(int fd) noexcept : fd_(fd) {}
    ~UniqueFd() { reset(); }
    UniqueFd(const UniqueFd&) = delete;
    UniqueFd& operator=(const UniqueFd&) = delete;
    UniqueFd(UniqueFd&& o) noexcept : fd_(std::exchange(o.fd_, -1)) {}
    UniqueFd& operator=(UniqueFd&& o) noexcept {
        if (this != &o) reset(std::exchange(o.fd_, -1));
        return *this;
    }
    [[nodiscard]] int get() const noexcept { return fd_; }
    void reset(int next = -1) noexcept {
        if (fd_ >= 0) ::close(fd_);
        fd_ = next;
    }
private:
    int fd_{-1};
};

inline void accept_until_eagain(int epfd, int listen_fd, std::vector<UniqueFd>& pool) {
    while (true) {
        sockaddr_storage peer{};
        socklen_t len = sizeof(peer);
        int cfd = ::accept4(listen_fd, reinterpret_cast<sockaddr*>(&peer), &len, SOCK_NONBLOCK | SOCK_CLOEXEC);
        if (cfd < 0) {
            if (errno == EINTR) continue;
            break; // EAGAIN / EWOULDBLOCK
        }
        UniqueFd guard(cfd);
        epoll_event ev{};
        ev.events = EPOLLIN | EPOLLRDHUP | EPOLLET;
        ev.data.fd = guard.get();
        if (::epoll_ctl(epfd, EPOLL_CTL_ADD, guard.get(), &ev) == 0) {
            pool.push_back(std::move(guard));
        }
    }
}

[[nodiscard]] inline bool drain_until_eagain(int fd, std::vector<std::byte>& sink) {
    std::byte buf[8192];
    while (true) {
        ssize_t n = ::recv(fd, buf, sizeof(buf), 0);
        if (n > 0) {
            sink.insert(sink.end(), buf, buf + n);
            continue;
        }
        if (n == 0) return false; // Peer EOF
        if (errno == EINTR) continue;
        return (errno == EAGAIN || errno == EWOULDBLOCK);
    }
}
