from dataclasses import dataclass


@dataclass(frozen=True)
class TVar:
    name: str


@dataclass(frozen=True)
class TCon:
    name: str
    args: tuple["Type", ...] = ()


@dataclass(frozen=True)
class TFun:
    param: "Type"
    ret: "Type"


Type = TVar | TCon | TFun
Subst = dict[str, Type]


class UnificationError(TypeError):
    pass


def apply_subst(ty: Type, subst: Subst) -> Type:
    if isinstance(ty, TVar):
        return apply_subst(subst[ty.name], subst) if ty.name in subst else ty
    if isinstance(ty, TFun):
        return TFun(apply_subst(ty.param, subst), apply_subst(ty.ret, subst))
    return TCon(ty.name, tuple(apply_subst(a, subst) for a in ty.args))


def occurs_in(var_name: str, ty: Type, subst: Subst) -> bool:
    resolved = apply_subst(ty, subst)
    if isinstance(resolved, TVar):
        return resolved.name == var_name
    if isinstance(resolved, TFun):
        return occurs_in(var_name, resolved.param, subst) or occurs_in(var_name, resolved.ret, subst)
    return any(occurs_in(var_name, a, subst) for a in resolved.args)


def _bind_var(var: TVar, ty: Type, subst: Subst) -> Subst:
    if ty == var:
        return subst
    if occurs_in(var.name, ty, subst):
        raise UnificationError(f"occurs check failed: {var.name} in {ty}")
    updated = {k: apply_subst(v, {var.name: ty}) for k, v in subst.items()}
    updated[var.name] = ty
    return updated


def unify(lhs: Type, rhs: Type, subst: Subst | None = None) -> Subst:
    s: Subst = {} if subst is None else dict(subst)
    t1, t2 = apply_subst(lhs, s), apply_subst(rhs, s)
    if isinstance(t1, TVar):
        return _bind_var(t1, t2, s)
    if isinstance(t2, TVar):
        return _bind_var(t2, t1, s)
    if isinstance(t1, TFun) and isinstance(t2, TFun):
        s = unify(t1.param, t2.param, s)
        return unify(t1.ret, t2.ret, s)
    if isinstance(t1, TCon) and isinstance(t2, TCon) and t1.name == t2.name and len(t1.args) == len(t2.args):
        for a1, a2 in zip(t1.args, t2.args, strict=True):
            s = unify(a1, a2, s)
        return s
    raise UnificationError(f"cannot unify {t1} with {t2}")
