```typescript
export interface PageEnvelope<T> {
  items: T[];
  next_cursor: string | null;
}

export interface PaginatedFetchOptions {
  signal?: AbortSignal;
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  headers?: Record<string, string>;
}

function sleepWithAbort(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) return Promise.reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
  return new Promise((resolve, reject) => {
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal?.reason ?? new DOMException("Aborted", "AbortError"));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

function parseRetryAfterMs(header: string | null): number | null {
  if (!header) return null;
  const secs = Number(header);
  if (Number.isFinite(secs) && secs >= 0) return secs * 1000;
  const dateMs = Date.parse(header);
  return Number.isNaN(dateMs) ? null : Math.max(0, dateMs - Date.now());
}

export async function* fetchCursorPages<T>(
  endpoint: string,
  opts: PaginatedFetchOptions = {},
): AsyncGenerator<T[], void, undefined> {
  const { signal, maxRetries = 4, baseDelayMs = 200, maxDelayMs = 8000, headers = {} } = opts;
  let cursor: string | null = null;

  do {
    const url = new URL(endpoint);
    if (cursor !== null) url.searchParams.set("cursor", cursor);

    let page: PageEnvelope<T> | undefined;
    for (let attempt = 0; ; attempt++) {
      signal?.throwIfAborted();
      const resp = await fetch(url, { headers: { Accept: "application/json", ...headers }, signal });
      if (resp.ok) {
        page = (await resp.json()) as PageEnvelope<T>;
        break;
      }
      const retryable = resp.status === 429 || (resp.status >= 500 && resp.status <= 599);
      if (!retryable || attempt >= maxRetries) {
        throw new Error(`HTTP ${resp.status} fetching ${url.toString()}`);
      }
      const expCap = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
      const waitMs = parseRetryAfterMs(resp.headers.get("Retry-After")) ?? Math.floor(Math.random() * expCap);
      await sleepWithAbort(waitMs, signal);
    }

    if (page.items.length > 0) yield page.items;
    cursor = page.next_cursor;
  } while (cursor !== null && cursor !== "");
}
