#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DnsErr { Truncated, BadLabel, PointerLoop, NameTooLong }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DnsHeader {
    pub id: u16,
    pub flags: u16,
    pub qdcount: u16,
    pub ancount: u16,
    pub nscount: u16,
    pub arcount: u16,
}

impl DnsHeader {
    pub fn parse(pkt: &[u8]) -> Result<Self, DnsErr> {
        if pkt.len() < 12 { return Err(DnsErr::Truncated); }
        let rd = |o: usize| u16::from_be_bytes([pkt[o], pkt[o + 1]]);
        Ok(Self { id: rd(0), flags: rd(2), qdcount: rd(4), ancount: rd(6), nscount: rd(8), arcount: rd(10) })
    }
}

pub fn decode_qname<'b>(pkt: &[u8], start: usize, out: &'b mut [u8; 255]) -> Result<(&'b [u8], usize), DnsErr> {
    let (mut pos, mut end_after, mut jumps, mut n) = (start, None, 0usize, 0usize);
    loop {
        let &b = pkt.get(pos).ok_or(DnsErr::Truncated)?;
        if b == 0 {
            return Ok((&out[..n], end_after.unwrap_or(pos + 1)));
        }
        match b & 0xC0 {
            0x00 => {
                let len = usize::from(b);
                let lab = pkt.get(pos + 1..pos + 1 + len).ok_or(DnsErr::Truncated)?;
                let sep = usize::from(n > 0);
                if n + sep + len > 253 { return Err(DnsErr::NameTooLong); }
                if sep == 1 { out[n] = b'.'; n += 1; }
                out[n..n + len].copy_from_slice(lab);
                n += len;
                pos += 1 + len;
            }
            0xC0 => {
                let &lo = pkt.get(pos + 1).ok_or(DnsErr::Truncated)?;
                jumps += 1;
                if jumps > 16 { return Err(DnsErr::PointerLoop); }
                end_after.get_or_insert(pos + 2);
                let target = (usize::from(b & 0x3F) << 8) | usize::from(lo);
                if target >= pkt.len() { return Err(DnsErr::Truncated); }
                pos = target;
            }
            _ => return Err(DnsErr::BadLabel),
        }
    }
}

pub fn parse_question<'b>(pkt: &[u8], off: usize, buf: &'b mut [u8; 255]) -> Result<((&'b [u8], u16, u16), usize), DnsErr> {
    let (qname, end) = decode_qname(pkt, off, buf)?;
    let tail = pkt.get(end..end + 4).ok_or(DnsErr::Truncated)?;
    let qtype = u16::from_be_bytes([tail[0], tail[1]]);
    let qclass = u16::from_be_bytes([tail[2], tail[3]]);
    Ok(((qname, qtype, qclass), end + 4))
}
