#include <cstddef>
#include <cstdint>

struct IntrusiveHook {
    IntrusiveHook* prev{nullptr};
    IntrusiveHook* next{nullptr};

    [[nodiscard]] bool is_linked() const noexcept { return next != nullptr; }

    void unlink() noexcept {
        if (!is_linked()) return;
        prev->next = next;
        next->prev = prev;
        prev = nullptr;
        next = nullptr;
    }
};

template <typename T, IntrusiveHook T::*HookMember>
class IntrusiveList {
public:
    IntrusiveList() noexcept { reset_sentinel(); }
    IntrusiveList(const IntrusiveList&) = delete;
    IntrusiveList& operator=(const IntrusiveList&) = delete;

    [[nodiscard]] bool empty() const noexcept { return root_.next == &root_; }

    void push_back(T& item) noexcept {
        IntrusiveHook& h = item.*HookMember;
        h.unlink();
        h.prev = root_.prev;
        h.next = &root_;
        root_.prev->next = &h;
        root_.prev = &h;
    }

    T* pop_front() noexcept {
        if (empty()) return nullptr;
        IntrusiveHook* first = root_.next;
        first->unlink();
        return node_from_hook(first);
    }

    T* front() noexcept {
        return empty() ? nullptr : node_from_hook(root_.next);
    }

    static void erase(T& item) noexcept { (item.*HookMember).unlink(); }

private:
    IntrusiveHook root_{};

    void reset_sentinel() noexcept {
        root_.prev = &root_;
        root_.next = &root_;
    }

    static T* node_from_hook(IntrusiveHook* h) noexcept {
        const auto offset = reinterpret_cast<std::uintptr_t>(&(static_cast<T*>(nullptr)->*HookMember));
        return reinterpret_cast<T*>(reinterpret_cast<std::byte*>(h) - offset);
    }
};

struct TimerEntry {
    std::uint64_t deadline_ns{};
    IntrusiveHook hook{};
};
