#define _GNU_SOURCE
#include <errno.h>
#include <stdbool.h>
#include <sys/sendfile.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_KERNEL_CHUNK ((size_t)0x7ffff000U)

ssize_t zero_copy_file_range(int in_fd, int out_fd, off_t length) {
    if (length < 0) {
        errno = EINVAL;
        return -1;
    }
    off_t remaining = length;
    off_t copied_total = 0;
    bool use_cfr = true;

    while (remaining > 0) {
        size_t chunk = (remaining > (off_t)MAX_KERNEL_CHUNK)
                           ? MAX_KERNEL_CHUNK
                           : (size_t)remaining;
        ssize_t n;
        if (use_cfr) {
            n = copy_file_range(in_fd, NULL, out_fd, NULL, chunk, 0);
            if (n < 0 && (errno == EXDEV || errno == ENOSYS || errno == EOPNOTSUPP)) {
                use_cfr = false;
                continue;
            }
        } else {
            n = sendfile(out_fd, in_fd, NULL, chunk);
        }

        if (n < 0) {
            if (errno == EINTR) continue;
            return copied_total > 0 ? (ssize_t)copied_total : -1;
        }
        if (n == 0) {
            break; /* unexpected EOF on source */
        }
        remaining -= n;
        copied_total += n;
    }
    return (ssize_t)copied_total;
}
