impl TryFrom<u16> for WireStatus {
    type Error = UnknownStatusError;
    fn try_from(code: u16) -> Result<Self, Self::Error> {
        match code {
            0 => Ok(Self::Ok),
            429 => Ok(Self::RateLimited),
            503 => Ok(Self::Unavailable),
            other => Err(UnknownStatusError(other)),
        }
    }
}

#[derive(Debug)]
pub enum FrameError {
    PayloadTooLarge { got: usize, max: usize },
    BadStatus(UnknownStatusError),
}

impl fmt::Display for FrameError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PayloadTooLarge { got, max } => write!(f, "frame size {} exceeds max {}", got, max),
            Self::BadStatus(e) => write!(f, "invalid frame status: {}", e),
        }
    }
}

impl Error for FrameError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::BadStatus(e) => Some(e),
            Self::PayloadTooLarge { .. } => None,
        }
    }
}

impl From<UnknownStatusError> for FrameError {
    fn from(e: UnknownStatusError) -> Self { Self::BadStatus(e) }
}

#[derive(Debug)]
pub enum RpcError {
    Io(io::Error),
    Frame(FrameError),
}

impl fmt::Display for RpcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e) => write!(f, "transport I/O failure: {}", e),
            Self::Frame(e) => write!(f, "protocol frame failure: {}", e),
        }
    }
}

impl Error for RpcError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            Self::Frame(e) => Some(e),
        }
    }
}

impl From<io::Error> for RpcError {
    fn from(e: io::Error) -> Self { Self::Io(e) }
}

impl From<FrameError> for RpcError {
    fn from(e: FrameError) -> Self { Self::Frame(e) }
}
