	s.mu.Lock()
	_, existed := s.items[key]
	delete(s.items, key)
	s.mu.Unlock()
	return existed
}

func (m *ShardedMap[V]) GetOrCompute(key string, fn func() V) V {
	s := m.shardFor(key)
	s.mu.RLock()
