#!/usr/bin/env python3
import argparse
import difflib
import sys
from pathlib import Path

RED, GRN, CYN, RST = "\033[31m", "\033[32m", "\033[36m", "\033[0m"


def fmt_range(start: int, stop: int) -> str:
    n = stop - start
    return f"{start},0" if n == 0 else (f"{start + 1}" if n == 1 else f"{start + 1},{n}")


def build_hunks(a: list[str], b: list[str], fa: str, fb: str, ctx: int, color: bool) -> list[str]:
    sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
    out: list[str] = []
    wrap = (lambda c, s: f"{c}{s}{RST}") if color else (lambda _, s: s)
    for grp in sm.get_grouped_opcodes(ctx):
        if not out:
            out.extend([wrap(RED, f"--- {fa}\n"), wrap(GRN, f"+++ {fb}\n")])
        r1, r2 = fmt_range(grp[0][1], grp[-1][2]), fmt_range(grp[0][3], grp[-1][4])
        out.append(wrap(CYN, f"@@ -{r1} +{r2} @@\n"))
        for tag, i1, i2, j1, j2 in grp:
            if tag == "equal":
                out.extend(f" {ln}" for ln in a[i1:i2])
            if tag in ("replace", "delete"):
                out.extend(wrap(RED, f"-{ln}") for ln in a[i1:i2])
            if tag in ("replace", "insert"):
                out.extend(wrap(GRN, f"+{ln}") for ln in b[j1:j2])
    return out


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("old_file", type=Path)
    ap.add_argument("new_file", type=Path)
    ap.add_argument("-U", "--unified", type=int, default=3)
    ap.add_argument("--color", choices=("auto", "always", "never"), default="auto")
    args = ap.parse_args(argv)
    try:
        a = args.old_file.read_text(encoding="utf-8").splitlines(keepends=True)
        b = args.new_file.read_text(encoding="utf-8").splitlines(keepends=True)
    except OSError as exc:
        print(f"udiff: {exc}", file=sys.stderr)
        return 2
    color = args.color == "always" or (args.color == "auto" and sys.stdout.isatty())
    hunks = build_hunks(a, b, str(args.old_file), str(args.new_file), max(0, args.unified), color)
    if not hunks:
        return 0
    sys.stdout.writelines(hunks)
    return 1


if __name__ == "__main__":
