```rust
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

#[derive(Debug, Clone)]
pub struct CountMinSketch {
    width: usize,
    depth: usize,
    table: Vec<u32>,
}

impl CountMinSketch {
    pub fn with_bounds(epsilon: f64, delta: f64) -> Self {
        assert!(epsilon > 0.0 && epsilon < 1.0 && delta > 0.0 && delta < 1.0);
        let width = ((std::f64::consts::E / epsilon).ceil() as usize).max(2);
        let depth = ((1.0 / delta).ln().ceil() as usize).max(1);
        Self { width, depth, table: vec![0u32; width * depth] }
    }

    fn hash_pair<T: Hash + ?Sized>(item: &T) -> (u64, u64) {
        let mut h = DefaultHasher::new();
        item.hash(&mut h);
        let base = h.finish();
        let mut z = base.wrapping_add(0x9e3779b97f4a7c15);
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb);
        (base, (z ^ (z >> 31)) | 1)
    }

    pub fn add<T: Hash + ?Sized>(&mut self, item: &T, count: u32) {
        let (h1, h2) = Self::hash_pair(item);
        let w = self.width as u64;
        for row in 0..self.depth {
            let col = (h1.wrapping_add((row as u64).wrapping_mul(h2)) % w) as usize;
            let idx = row * self.width + col;
            self.table[idx] = self.table[idx].saturating_add(count);
        }
    }

    pub fn estimate<T: Hash + ?Sized>(&self, item: &T) -> u32 {
        let (h1, h2) = Self::hash_pair(item);
        let w = self.width as u64;
        (0..self.depth)
            .map(|row| {
                let col = (h1.wrapping_add((row as u64).wrapping_mul(h2)) % w) as usize;
                self.table[row * self.width + col]
            })
            .min()
            .unwrap_or(0)
    }

    pub fn merge(&mut self, other: &Self) -> Result<(), &'static str> {
        if self.width != other.width || self.depth != other.depth {
            return Err("dimension mismatch");
        }
        for (dst, src) in self.table.iter_mut().zip(&other.table) {
            *dst = dst.saturating_add(*src);
        }
        Ok(())
    }
}
