    token: int
    expires_at: float


class LeaseCoordinator:
    def __init__(self, ttl_sec: float = 10.0) -> None:
        self.ttl_sec = ttl_sec
        self._seq = 0
        self._cur: Lease | None = None

    def acquire(self, node_id: str, now: float) -> Lease | None:
        if self._cur and now < self._cur.expires_at and self._cur.holder != node_id:
            return None
        self._seq += 1
        self._cur = Lease(node_id, self._seq, now + self.ttl_sec)
        return self._cur


class FencedKVStore:
