use std::borrow::Cow;

#[inline]
fn escape_entity(b: u8) -> Option<&'static str> {
    match b {
        b'&' => Some("&amp;"),
        b'<' => Some("&lt;"),
        b'>' => Some("&gt;"),
        b'"' => Some("&quot;"),
        b'\'' => Some("&#39;"),
        _ => None,
    }
}

pub fn escape_html_attr<'a>(input: &'a str) -> Cow<'a, str> {
    let bytes = input.as_bytes();
    let Some(first) = bytes.iter().position(|&b| escape_entity(b).is_some()) else {
        return Cow::Borrowed(input);
    };
    let mut out = String::with_capacity(input.len() + 16);
    out.push_str(&input[..first]);
    out.push_str(escape_entity(bytes[first]).unwrap());
    let mut last_clean = first + 1;
    for i in (first + 1)..bytes.len() {
        if let Some(ent) = escape_entity(bytes[i]) {
            if last_clean < i {
                out.push_str(&input[last_clean..i]);
            }
            out.push_str(ent);
            last_clean = i + 1;
        }
    }
    if last_clean < bytes.len() {
        out.push_str(&input[last_clean..]);
    }
    Cow::Owned(out)
}
