```typescript
type BuiltinLeaf = string | number | boolean | bigint | symbol | undefined | null | Date | RegExp | Error;

export type DeepReadonly<T> = T extends BuiltinLeaf
  ? T
  : T extends (...args: infer A) => infer R
    ? (...args: A) => R
    : T extends ReadonlyMap<infer K, infer V>
      ? ReadonlyMap<DeepReadonly<K>, DeepReadonly<V>>
      : T extends ReadonlySet<infer U>
        ? ReadonlySet<DeepReadonly<U>>
        : T extends object
          ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
          : T;

export function deepFreeze<T>(value: T, seen = new WeakSet<object>()): DeepReadonly<T> {
  if (value === null || (typeof value !== "object" && typeof value !== "function")) {
    return value as DeepReadonly<T>;
  }
  const obj = value as object;
  if (seen.has(obj) || Object.isFrozen(obj)) {
    return value as DeepReadonly<T>;
  }
  seen.add(obj);
  if (obj instanceof Map) {
    for (const [k, v] of obj.entries()) {
      deepFreeze(k, seen);
      deepFreeze(v, seen);
    }
  } else if (obj instanceof Set) {
    for (const item of obj.values()) {
      deepFreeze(item, seen);
    }
  } else {
    for (const key of Reflect.ownKeys(obj)) {
      const desc = Object.getOwnPropertyDescriptor(obj, key);
      if (desc && "value" in desc) {
        deepFreeze(desc.value, seen);
      }
    }
  }
  return Object.freeze(obj) as DeepReadonly<T>;
}
