```go
package rpcutil

import (
	"context"
	"errors"
	"time"
)

type outcome[T any] struct {
	val T
	err error
}

func HedgeCall[T any](
	ctx context.Context,
	hedgeDelay time.Duration,
	fn func(context.Context) (T, error),
) (T, error) {
	var zero T
	if err := ctx.Err(); err != nil {
		return zero, err
	}

	resCh := make(chan outcome[T], 2)
	pCtx, cancelPrimary := context.WithCancel(ctx)
	defer cancelPrimary()

	go func() {
		v, err := fn(pCtx)
		resCh <- outcome[T]{val: v, err: err}
	}()

	timer := time.NewTimer(hedgeDelay)
	defer timer.Stop()

	var firstErr error
	select {
	case <-ctx.Done():
		return zero, ctx.Err()
	case r := <-resCh:
		if r.err == nil {
			return r.val, nil
		}
		firstErr = r.err
	case <-timer.C:
	}

	hCtx, cancelHedge := context.WithCancel(ctx)
	defer cancelHedge()

	go func() {
		v, err := fn(hCtx)
		resCh <- outcome[T]{val: v, err: err}
	}()

	needed := 2
	if firstErr != nil {
		needed = 1
	}
	for i := 0; i < needed; i++ {
		select {
		case <-ctx.Done():
			return zero, ctx.Err()
		case r := <-resCh:
			if r.err == nil {
				return r.val, nil
			}
			firstErr = errors.Join(firstErr, r.err)
		}
	}
	return zero, firstErr
}
