MASK64 = (1 << 64) - 1
INT64_MIN = -(1 << 63)
INT64_MAX = (1 << 63) - 1


class VarintError(ValueError):
    pass


def encode_uvarint(value: int, out: bytearray | None = None) -> bytearray:
    if value < 0 or value > MASK64:
        raise VarintError(f"uint64 out of range: {value}")
    buf = out if out is not None else bytearray()
    while value >= 0x80:
        buf.append((value & 0x7F) | 0x80)
        value >>= 7
    buf.append(value)
    return buf


def decode_uvarint_from(buf: bytes | bytearray | memoryview, offset: int = 0) -> tuple[int, int]:
    result = 0
    shift = 0
    n = len(buf)
    pos = offset
    while pos < n:
        b = buf[pos]
        pos += 1
        if shift == 63 and b > 1:
            raise VarintError("varint overflows uint64")
        result |= (b & 0x7F) << shift
        if (b & 0x80) == 0:
            return result, pos
        shift += 7
        if shift > 63:
            raise VarintError("varint exceeds 10-byte limit")
    raise VarintError("truncated varint")


def encode_svarint(value: int, out: bytearray | None = None) -> bytearray:
    if value < INT64_MIN or value > INT64_MAX:
        raise VarintError(f"int64 out of range: {value}")
    zigzag = ((value << 1) ^ (value >> 63)) & MASK64
    return encode_uvarint(zigzag, out)


def decode_svarint_from(buf: bytes | bytearray | memoryview, offset: int = 0) -> tuple[int, int]:
    raw, next_off = decode_uvarint_from(buf, offset)
    signed = (raw >> 1) ^ -(raw & 1)
    return signed, next_off
