```rust
use core::mem::MaybeUninit;
use core::slice;

pub struct ArrayRing<T, const N: usize> {
    buf: [MaybeUninit<T>; N],
    head: usize,
    tail: usize,
}

impl<T, const N: usize> ArrayRing<T, N> {
    const ASSERT_POW2: () = assert!(N > 0 && N.is_power_of_two(), "N must be a power of two");

    pub fn new() -> Self {
        let () = Self::ASSERT_POW2;
        Self {
            buf: [const { MaybeUninit::uninit() }; N],
            head: 0,
            tail: 0,
        }
    }

    #[inline]
    pub fn len(&self) -> usize { self.tail.wrapping_sub(self.head) }

    #[inline]
    pub fn is_empty(&self) -> bool { self.head == self.tail }

    pub fn push_overwrite(&mut self, item: T) -> Option<T> {
        let evicted = if self.len() == N { self.pop_front() } else { None };
        let idx = self.tail & (N - 1);
        self.buf[idx].write(item);
        self.tail = self.tail.wrapping_add(1);
        evicted
    }

    pub fn pop_front(&mut self) -> Option<T> {
        if self.is_empty() {
            return None;
        }
        let idx = self.head & (N - 1);
        self.head = self.head.wrapping_add(1);
        // SAFETY: idx is within head..tail and was initialized by push_overwrite.
        Some(unsafe { self.buf[idx].assume_init_read() })
    }

    pub fn as_slices(&self) -> (&[T], &[T]) {
        let count = self.len();
        if count == 0 {
            return (&[], &[]);
        }
        let start = self.head & (N - 1);
        let first_len = count.min(N - start);
        let second_len = count - first_len;
        // SAFETY: both ranges contain live initialized elements.
        unsafe {
            let ptr = self.buf.as_ptr().cast::<T>();
            (
                slice::from_raw_parts(ptr.add(start), first_len),
                slice::from_raw_parts(ptr, second_len),
            )
        }
    }
}

impl<T, const N: usize> Drop for ArrayRing<T, N> {
    fn drop(&mut self) {
        while self.pop_front().is_some() {}
    }
}
