        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr = {.s_addr = htonl(INADDR_ANY)},
    };
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

ssize_t drain_udp_batch(int fd, void (*on_pkt)(const uint8_t *, size_t, const struct sockaddr_in *)) {
    uint8_t bufs[BATCH_SZ][MAX_PKT];
    struct iovec iovs[BATCH_SZ];
    struct sockaddr_in peers[BATCH_SZ];
    struct mmsghdr msgs[BATCH_SZ];
    memset(msgs, 0, sizeof(msgs));

    for (int i = 0; i < BATCH_SZ; i++) {
        iovs[i].iov_base = bufs[i];
        iovs[i].iov_len = MAX_PKT;
        msgs[i].msg_hdr.msg_iov = &iovs[i];
        msgs[i].msg_hdr.msg_iovlen = 1;
        msgs[i].msg_hdr.msg_name = &peers[i];
        msgs[i].msg_hdr.msg_namelen = sizeof(peers[i]);
    }

    int n = recvmmsg(fd, msgs, BATCH_SZ, MSG_WAITFORONE, NULL);
    if (n < 0) return (errno == EINTR) ? 0 : -1;
    for (int i = 0; i < n; i++) {
        on_pkt(bufs[i], msgs[i].msg_len, &peers[i]);
    }
    return n;
}
