const CASE_MASK: u64 = 0x2020_2020_2020_2020;
const HIGH_BITS: u64 = 0x8080_8080_8080_8080;

#[inline]
fn u64_eq_ascii_nocase(a: u64, b: u64) -> bool {
    let diff = a ^ b;
    if diff == 0 {
        return true;
    }
    if (diff & !CASE_MASK) != 0 {
        return false;
    }
    // Only bit 5 (0x20) differs in changed lanes; verify each changed lane is in 'a'..='z' without cross-lane borrows.
    let lowered = a | CASE_MASK;
    let ge_a = (lowered | HIGH_BITS).wrapping_sub(0x6161_6161_6161_6161);
    let le_z = (0x7a7a_7a7a_7a7a_7a7au64 | HIGH_BITS).wrapping_sub(lowered & !HIGH_BITS);
    let is_ascii_alpha = ge_a & le_z & !lowered & HIGH_BITS;
    ((diff << 2) & !is_ascii_alpha) == 0
}

pub fn eq_ignore_ascii_case_swar(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut ac = a.chunks_exact(8);
    let mut bc = b.chunks_exact(8);
    for (ca, cb) in ac.by_ref().zip(bc.by_ref()) {
        let wa = u64::from_ne_bytes(ca.try_into().unwrap());
        let wb = u64::from_ne_bytes(cb.try_into().unwrap());
        if !u64_eq_ascii_nocase(wa, wb) {
            return false;
        }
    }
    ac.remainder().eq_ignore_ascii_case(bc.remainder())
}
