use std::collections::HashMap;
use std::future::Future;
use std::hash::Hash;
use std::sync::{Arc, Mutex};
use tokio::sync::watch;

pub struct SingleFlight<K, V> {
    inflight: Arc<Mutex<HashMap<K, watch::Receiver<Option<Result<V, String>>>>>>,
}

struct LeaderGuard<K: Eq + Hash, V> {
    key: Option<K>,
    inflight: Arc<Mutex<HashMap<K, watch::Receiver<Option<Result<V, String>>>>>>,
}

impl<K: Eq + Hash, V> Drop for LeaderGuard<K, V> {
    fn drop(&mut self) {
        if let Some(k) = self.key.take() {
            if let Ok(mut map) = self.inflight.lock() {
                map.remove(&k);
            }
        }
    }
}

impl<K: Eq + Hash + Clone, V: Clone> SingleFlight<K, V> {
    pub fn new() -> Self {
        Self { inflight: Arc::new(Mutex::new(HashMap::new())) }
    }

    pub async fn work<F, Fut>(&self, key: K, f: F) -> Result<V, String>
    where
        F: FnOnce() -> Fut,
        Fut: Future<Output = Result<V, String>>,
    {
        let maybe_rx = {
            let mut map = self.inflight.lock().unwrap();
            if let Some(rx) = map.get(&key) {
                Err(rx.clone())
            } else {
                let (tx, rx) = watch::channel(None);
                map.insert(key.clone(), rx);
                Ok(tx)
            }
        };

        match maybe_rx {
            Ok(tx) => {
                let _guard = LeaderGuard { key: Some(key), inflight: Arc::clone(&self.inflight) };
                let res = f().await;
                let _ = tx.send(Some(res.clone()));
                res
            }
            Err(mut rx) => {
                loop {
                    if let Some(done) = rx.borrow_and_update().clone() {
                        return done;
                    }
                    if rx.changed().await.is_err() {
                        return Err("singleflight leader cancelled".into());
                    }
                }
            }
        }
}
}
