package main

import (
	"bufio"
	"flag"
	"fmt"
	"os"
	"strings"
)

func parseEnv(path string, checkVal bool) (map[string]int, []string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()

	seen := make(map[string]int)
	var diags []string
	sc := bufio.NewScanner(f)
	for lineNo := 1; sc.Scan(); lineNo++ {
		raw := strings.TrimSpace(sc.Text())
		if raw == "" || strings.HasPrefix(raw, "#") {
			continue
		}
		raw = strings.TrimPrefix(raw, "export ")
		k, v, ok := strings.Cut(raw, "=")
		k = strings.TrimSpace(k)
		if !ok || k == "" {
			diags = append(diags, fmt.Sprintf("%s:%d: malformed assignment", path, lineNo))
			continue
		}
		if prev, dup := seen[k]; dup {
			diags = append(diags, fmt.Sprintf("%s:%d: duplicate key %s (first at line %d)", path, lineNo, k, prev))
		}
		seen[k] = lineNo
		if checkVal && len(v) > 0 && v[0] != '"' && v[0] != '\'' && strings.ContainsAny(v, " \t") {
			diags = append(diags, fmt.Sprintf("%s:%d: unquoted whitespace in %s", path, lineNo, k))
		}
	}
	return seen, diags, sc.Err()
}

func main() {
	schemaPath := flag.String("schema", ".env.example", "reference schema file")
	envPath := flag.String("env", ".env", "target env file")
	strict := flag.Bool("strict", false, "reject keys absent from schema")
	flag.Parse()

	schema, sDiags, err := parseEnv(*schemaPath, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "envlint: %v\n", err)
		os.Exit(2)
	}
	actual, aDiags, err := parseEnv(*envPath, true)
	if err != nil {
		fmt.Fprintf(os.Stderr, "envlint: %v\n", err)
		os.Exit(2)
	}

	diags := append(sDiags, aDiags...)
	for k, line := range schema {
		if _, ok := actual[k]; !ok {
			diags = append(diags, fmt.Sprintf("%s: missing required key %s (%s:%d)", *envPath, k, *schemaPath, line))
		}
	}
	if *strict {
		for k, line := range actual {
			if _, ok := schema[k]; !ok {
				diags = append(diags, fmt.Sprintf("%s:%d: undeclared key %s", *envPath, line, k))
			}
		}
	}
	for _, d := range diags {
		fmt.Fprintln(os.Stderr, d)
	}
	if len(diags) > 0 {
		os.Exit(1)
	}
}
