package resp2

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
)

type Kind uint8

const (
	SimpleString Kind = iota
	ErrorMsg
	Integer
	BulkString
	NullBulk
	Array
	NullArray
)

type Value struct {
	Kind  Kind
	Str   string
	Int   int64
	Bytes []byte
	Elems []Value
}

func readLineCRLF(r *bufio.Reader) (string, error) {
	line, err := r.ReadString('\n')
	if err != nil {
		return "", err
	}
	if len(line) < 2 || line[len(line)-2] != '\r' {
		return "", errors.New("resp2: missing CRLF")
	}
	return line[:len(line)-2], nil
}

func ReadRESP(r *bufio.Reader, maxBulkLen int, maxDepth int) (Value, error) {
	if maxDepth < 0 {
		return Value{}, errors.New("resp2: max nesting depth exceeded")
	}
	head, err := readLineCRLF(r)
	if err != nil {
		return Value{}, err
	}
	if head == "" {
		return Value{}, errors.New("resp2: empty frame header")
	}
	body := head[1:]
	switch head[0] {
	case '+':
		return Value{Kind: SimpleString, Str: body}, nil
	case '-':
		return Value{Kind: ErrorMsg, Str: body}, nil
	case ':':
		n, err := strconv.ParseInt(body, 10, 64)
		return Value{Kind: Integer, Int: n}, err
	case '$':
		n, err := strconv.Atoi(body)
		if err != nil {
			return Value{}, err
		}
		if n == -1 {
			return Value{Kind: NullBulk}, nil
		}
		if n < 0 || n > maxBulkLen {
			return Value{}, fmt.Errorf("resp2: invalid bulk length %d", n)
		}
		buf := make([]byte, n+2)
		if _, err := io.ReadFull(r, buf); err != nil {
			return Value{}, err
		}
		if buf[n] != '\r' || buf[n+1] != '\n' {
			return Value{}, errors.New("resp2: malformed bulk trailer")
		}
		return Value{Kind: BulkString, Bytes: buf[:n]}, nil
	case '*':
		n, err := strconv.Atoi(body)
		if err != nil {
			return Value{}, err
		}
		if n == -1 {
			return Value{Kind: NullArray}, nil
		}
		if n < 0 || n > 65536 {
			return Value{}, fmt.Errorf("resp2: invalid array count %d", n)
		}
		elems := make([]Value, n)
		for i := 0; i < n; i++ {
			if elems[i], err = ReadRESP(r, maxBulkLen, maxDepth-1); err != nil {
				return Value{}, err
			}
		}
		return Value{Kind: Array, Elems: elems}, nil
	default:
		return Value{}, fmt.Errorf("resp2: unknown prefix %q", head[0])
	}
}
