import heapq
from collections.abc import Mapping, Sequence


class DependencyCycleError(ValueError):
    def __init__(self, cycle: list[str]) -> None:
        self.cycle = cycle
        super().__init__("cycle detected: " + " -> ".join(cycle))


def _extract_cycle(adj: dict[str, list[str]], candidates: set[str]) -> list[str]:
    state: dict[str, int] = {}  # 1 = visiting, 2 = done
    trail: list[str] = []
    pos: dict[str, int] = {}
    for start in sorted(candidates):
        if state.get(start, 0) != 0:
            continue
        stack: list[tuple[str, int]] = [(start, 0)]
        state[start] = 1
        pos[start] = 0
        trail = [start]
        while stack:
            node, idx = stack[-1]
            nbrs = [n for n in adj[node] if n in candidates]
            if idx < len(nbrs):
                stack[-1] = (node, idx + 1)
                nxt = nbrs[idx]
                st = state.get(nxt, 0)
                if st == 1:
                    return trail[pos[nxt]:] + [nxt]
                if st == 0:
                    state[nxt] = 1
                    pos[nxt] = len(trail)
                    trail.append(nxt)
                    stack.append((nxt, 0))
            else:
                state[node] = 2
                pos.pop(node, None)
                trail.pop()
                stack.pop()
    raise RuntimeError("unreachable")


def toposort_build_graph(deps_by_pkg: Mapping[str, Sequence[str]]) -> list[str]:
    nodes: set[str] = set(deps_by_pkg.keys())
    for deps in deps_by_pkg.values():
        nodes.update(deps)
    adj: dict[str, list[str]] = {n: [] for n in nodes}
    indeg: dict[str, int] = {n: 0 for n in nodes}
    for pkg, deps in deps_by_pkg.items():
        for dep in sorted(set(deps)):
            adj[dep].append(pkg)
            indeg[pkg] += 1
    for n in adj:
        adj[n].sort()

    ready = [n for n, d in indeg.items() if d == 0]
    heapq.heapify(ready)
    order: list[str] = []
    while ready:
        cur = heapq.heappop(ready)
        order.append(cur)
        for nxt in adj[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(order) != len(nodes):
        stuck = {n for n, d in indeg.items() if d > 0}
        raise DependencyCycleError(_extract_cycle(adj, stuck))
    return order
