package chash

import (
	"encoding/binary"
	"hash/fnv"
	"sort"
	"strconv"
	"testing"
)

type vnode struct {
	hash uint64
	node string
}

type Ring struct {
	vnodes int
	ring   []vnode
}

func hash64(s string) uint64 {
	h := fnv.New64a()
	_, _ = h.Write([]byte(s))
	var b [8]byte
	binary.LittleEndian.PutUint64(b[:], h.Sum64()*0x9e3779b97f4a7c15)
	return binary.LittleEndian.Uint64(b[:])
}

func NewRing(vnodes int, nodes ...string) *Ring {
	r := &Ring{vnodes: vnodes}
	for _, n := range nodes {
		r.Add(n)
	}
	return r
}

func (r *Ring) Add(node string) {
	for i := 0; i < r.vnodes; i++ {
		r.ring = append(r.ring, vnode{hash: hash64(node + "#" + strconv.Itoa(i)), node: node})
	}
	sort.Slice(r.ring, func(i, j int) bool {
		if r.ring[i].hash == r.ring[j].hash {
			return r.ring[i].node < r.ring[j].node
		}
		return r.ring[i].hash < r.ring[j].hash
	})
}

func (r *Ring) Locate(key string) string {
	if len(r.ring) == 0 {
		return ""
	}
	h := hash64(key)
	idx := sort.Search(len(r.ring), func(i int) bool { return r.ring[i].hash >= h })
	if idx == len(r.ring) {
		idx = 0
	}
	return r.ring[idx].node
}

func TestRingBoundedRemapping(t *testing.T) {
	r4 := NewRing(160, "n1", "n2", "n3", "n4")
	r5 := NewRing(160, "n1", "n2", "n3", "n4", "n5")
	const total = 10000
	moved := 0
	for i := 0; i < total; i++ {
		k := "tenant-key-" + strconv.Itoa(i)
		before, after := r4.Locate(k), r5.Locate(k)
		if before != after {
			if after != "n5" {
				t.Fatalf("key %s moved between existing nodes %s -> %s", k, before, after)
			}
			moved++
		}
	}
	ratio := float64(moved) / total
	if ratio < 0.12 || ratio > 0.30 {
		t.Fatalf("unexpected remap ratio %.3f (moved %d/%d)", ratio, moved, total)
	}
}
