#include <algorithm>
#include <cstdint>
#include <cstring>
#include <memory>
#include <string_view>
#include <unordered_map>
#include <vector>

struct Symbol {
    uint32_t id;
    friend constexpr bool operator==(Symbol, Symbol) = default;
};

struct TransparentStrHash {
    using is_transparent = void;
    size_t operator()(std::string_view sv) const noexcept {
        return std::hash<std::string_view>{}(sv);
    }
};

class StringInterner {
    static constexpr size_t kSlabBytes = 64 * 1024;
    std::vector<std::unique_ptr<char[]>> slabs_;
    size_t offset_ = kSlabBytes;
    std::vector<std::string_view> id_to_str_;
    std::unordered_map<std::string_view, Symbol, TransparentStrHash, std::equal_to<>> map_;

    std::string_view store_copy(std::string_view s) {
        if (s.empty()) return "";
        if (s.size() > kSlabBytes) {
            auto huge = std::make_unique<char[]>(s.size());
            std::memcpy(huge.get(), s.data(), s.size());
            std::string_view view{huge.get(), s.size()};
            slabs_.push_back(std::move(huge));
            return view;
        }
        if (offset_ + s.size() > kSlabBytes) {
            slabs_.push_back(std::make_unique<char[]>(kSlabBytes));
            offset_ = 0;
        }
        char* dst = slabs_.back().get() + offset_;
        std::memcpy(dst, s.data(), s.size());
        offset_ += s.size();
        return {dst, s.size()};
    }

public:
    Symbol intern(std::string_view s) {
        if (auto it = map_.find(s); it != map_.end()) {
            return it->second;
        }
        std::string_view owned = store_copy(s);
        Symbol sym{static_cast<uint32_t>(id_to_str_.size())};
        id_to_str_.push_back(owned);
        map_.emplace(owned, sym);
        return sym;
    }

    std::string_view resolve(Symbol sym) const noexcept {
        return id_to_str_[sym.id];
    }
};
