#include <memory>
#include <stdexcept>
#include <string>
#include <string_view>
#include <variant>

template <class... Ts>
struct Overloaded : Ts... {
    using Ts::operator()...;
};

struct Expr;
using ExprPtr = std::shared_ptr<const Expr>;

struct NumLit { double value; };
struct VarRef { std::string name; };
struct BinExpr { char op; ExprPtr lhs; ExprPtr rhs; };
struct LetExpr { std::string name; ExprPtr bound; ExprPtr body; };

struct Expr {
    std::variant<NumLit, VarRef, BinExpr, LetExpr> node;
};

struct EnvFrame {
    std::string_view key;
    double val;
    const EnvFrame* parent = nullptr;

    double lookup(std::string_view target) const {
        for (const EnvFrame* cur = this; cur != nullptr; cur = cur->parent) {
            if (cur->key == target) return cur->val;
        }
        throw std::runtime_error("unbound variable: " + std::string(target));
    }
};

inline double eval(const Expr& expr, const EnvFrame* env = nullptr) {
    return std::visit(
        Overloaded{
            [](const NumLit& n) -> double { return n.value; },
            [env](const VarRef& v) -> double {
                if (!env) throw std::runtime_error("unbound variable: " + v.name);
                return env->lookup(v.name);
            },
            [env](const BinExpr& b) -> double {
                const double l = eval(*b.lhs, env);
                const double r = eval(*b.rhs, env);
                switch (b.op) {
                    case '+': return l + r;
                    case '-': return l - r;
                    case '*': return l * r;
                    case '/':
                        if (r == 0.0) throw std::domain_error("division by zero");
                        return l / r;
                    default: throw std::invalid_argument("unknown operator");
                }
            },
            [env](const LetExpr& let_e) -> double {
                const double bound_val = eval(*let_e.bound, env);
                const EnvFrame child{let_e.name, bound_val, env};
                return eval(*let_e.body, &child);
            },
        },
        expr.node);
}
