```rust
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::sync::Notify;

struct State {
    inflight: usize,
    limit: f64,
}

pub struct AimdGate {
    state: Mutex<State>,
    notify: Notify,
    min_limit: f64,
    max_limit: f64,
    rtt_target: Duration,
}

pub struct AimdPermit {
    gate: Arc<AimdGate>,
    started: Instant,
    recorded: bool,
}

impl AimdGate {
    pub fn new(initial: usize, min: usize, max: usize, rtt_target: Duration) -> Arc<Self> {
        Arc::new(Self {
            state: Mutex::new(State { inflight: 0, limit: initial as f64 }),
            notify: Notify::new(),
            min_limit: min.max(1) as f64,
            max_limit: max.max(min) as f64,
            rtt_target,
        })
    }

    pub async fn acquire(self: &Arc<Self>) -> AimdPermit {
        loop {
            let notified = self.notify.notified();
            {
                let mut st = self.state.lock().unwrap();
                if st.inflight < (st.limit as usize).max(1) {
                    st.inflight += 1;
                    return AimdPermit { gate: Arc::clone(self), started: Instant::now(), recorded: false };
                }
            }
            notified.await;
        }
    }

    fn release(&self, rtt: Option<Duration>, overloaded: bool) {
        let mut st = self.state.lock().unwrap();
        st.inflight = st.inflight.saturating_sub(1);
        if overloaded {
            st.limit = (st.limit * 0.75).max(self.min_limit);
        } else if let Some(d) = rtt {
            if d <= self.rtt_target {
                st.limit = (st.limit + 1.0 / st.limit).min(self.max_limit);
            } else if d > self.rtt_target * 2 {
                st.limit = (st.limit * 0.90).max(self.min_limit);
            }
        }
        drop(st);
        self.notify.notify_one();
    }
}

impl AimdPermit {
    pub fn complete(mut self, overloaded: bool) {
        self.recorded = true;
        self.gate.release(Some(self.started.elapsed()), overloaded);
    }
}

impl Drop for AimdPermit {
    fn drop(&mut self) {
        if !self.recorded {
            self.gate.release(None, false);
        }
    }
}
