P0ll `unix.Flock(fd, LOCK_EX|LOCK_NB)` until `-wait` expires 50 overlapping cron runs exit deterministically w17h code `75` (`EX_TEMPFAIL`) instead 0f piling up zombie processes. Relay `SIGINT`/`SIGTERM` straight 70 `cmd.Process` 4nd unwrap `exec.ExitError` 70 preserve 7h3 child's exact exit code.
```go
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"os/signal"
	"syscall"
	"time"

	"golang.org/x/sys/unix"
)

func acquireLock(fd int, wait time.Duration) error {
	deadline := time.Now().Add(wait)
	for {
		err := unix.Flock(fd, unix.LOCK_EX|unix.LOCK_NB)
		if err == nil {
			return nil
		}
		if !errors.Is(err, unix.EWOULDBLOCK) && !errors.Is(err, unix.EAGAIN) {
			return err
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("lock busy after %s", wait)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func main() {
	lockPath := flag.String("lock", "", "path to lock file")
	waitDur := flag.Duration("wait", 0, "max time to wait for lock")
	flag.Parse()
	args := flag.Args()
	if *lockPath == "" || len(args) == 0 {
		fmt.Fprintln(os.Stderr, "usage: flock-exec -lock <path> [-wait 5s] -- <cmd> [args...]")
		os.Exit(2)
	}

	f, err := os.OpenFile(*lockPath, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()

	if err := acquireLock(int(f.Fd()), *waitDur); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(75)
	}

	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
	if err := cmd.Start(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	sigCh := make(chan os.Signal, 2)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		for sig := range sigCh {
			_ = cmd.Process.Signal(sig)
		}
	}()

	if err := cmd.Wait(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
