package proxyv2

import (
	"bytes"
	"encoding/binary"
	"errors"
	"net/netip"
)

var v2Sig = [12]byte{0x0D, 0x0A, 0x0D, 0x0A, 0x00, 0x0D, 0x0A, 0x51, 0x55, 0x49, 0x54, 0x0A}

var (
	ErrShortHeader = errors.New("proxyv2: buffer shorter than header")
	ErrInvalidHdr  = errors.New("proxyv2: malformed v2 signature or header")
)

type Header struct {
	LocalCommand bool
	Src          netip.AddrPort
	Dst          netip.AddrPort
	TLVs         []byte
}

func ParseProxyV2(buf []byte) (Header, int, error) {
	if len(buf) < 16 {
		return Header{}, 0, ErrShortHeader
	}
	if !bytes.Equal(buf[:12], v2Sig[:]) || (buf[12]&0xF0) != 0x20 {
		return Header{}, 0, ErrInvalidHdr
	}
	cmd := buf[12] & 0x0F
	famProto := buf[13]
	payLen := int(binary.BigEndian.Uint16(buf[14:16]))
	total := 16 + payLen
	if len(buf) < total {
		return Header{}, 0, ErrShortHeader
	}
	body := buf[16:total]

	switch cmd {
	case 0x00: // LOCAL healthcheck
		return Header{LocalCommand: true, TLVs: body}, total, nil
	case 0x01: // PROXY
	default:
		return Header{}, 0, ErrInvalidHdr
	}

	switch famProto & 0xF0 {
	case 0x10: // AF_INET
		if len(body) < 12 {
			return Header{}, 0, ErrInvalidHdr
		}
		src := netip.AddrPortFrom(netip.AddrFrom4([4]byte(body[0:4])), binary.BigEndian.Uint16(body[8:10]))
		dst := netip.AddrPortFrom(netip.AddrFrom4([4]byte(body[4:8])), binary.BigEndian.Uint16(body[10:12]))
		return Header{Src: src, Dst: dst, TLVs: body[12:]}, total, nil
	case 0x20: // AF_INET6
		if len(body) < 36 {
			return Header{}, 0, ErrInvalidHdr
		}
		src := netip.AddrPortFrom(netip.AddrFrom16([16]byte(body[0:16])), binary.BigEndian.Uint16(body[32:34]))
		dst := netip.AddrPortFrom(netip.AddrFrom16([16]byte(body[16:32])), binary.BigEndian.Uint16(body[34:36]))
		return Header{Src: src, Dst: dst, TLVs: body[36:]}, total, nil
	default:
		return Header{TLVs: body}, total, nil
	}
}
