```python
import hashlib
import math
import struct

HDR = struct.Struct("!4sIB")
MAGIC = b"BLM1"


class BloomFilter:
    def __init__(self, num_bits: int, num_hashes: int, bits: bytearray | None = None) -> None:
        if num_bits <= 0 or num_hashes <= 0 or num_hashes > 64:
            raise ValueError("invalid BloomFilter parameters")
        self.num_bits = (num_bits + 7) & ~7
        self.num_hashes = num_hashes
        nbytes = self.num_bits >> 3
        if bits is not None and len(bits) != nbytes:
            raise ValueError("bit buffer length mismatch")
        self._bits = bits if bits is not None else bytearray(nbytes)

    @classmethod
    def with_rate(cls, capacity: int, fp_rate: float = 0.01) -> "BloomFilter":
        if capacity <= 0 or not (0.0 < fp_rate < 1.0):
            raise ValueError("capacity > 0 and 0 < fp_rate < 1 required")
        ln2 = math.log(2.0)
        m = max(8, math.ceil(-capacity * math.log(fp_rate) / (ln2 * ln2)))
        k = max(1, min(32, round((m / capacity) * ln2)))
        return cls(m, k)

    def _probes(self, key: bytes | str) -> range:
        raw = key.encode("utf-8") if isinstance(key, str) else key
        digest = hashlib.blake2b(raw, digest_size=16).digest()
        h1, h2 = struct.unpack("!QQ", digest)
        step = h2 | 1  # odd step improves cycle coverage
        return range(h1, h1 + self.num_hashes * step, step)

    def add(self, key: bytes | str) -> None:
        m = self.num_bits
        for p in self._probes(key):
            bit = p % m
            self._bits[bit >> 3] |= 1 << (bit & 7)

    def __contains__(self, key: bytes | str) -> bool:
        m = self.num_bits
        for p in self._probes(key):
            bit = p % m
            if not (self._bits[bit >> 3] & (1 << (bit & 7))):
                return False
        return True

    def to_bytes(self) -> bytes:
        return HDR.pack(MAGIC, self.num_bits, self.num_hashes) + bytes(self._bits)

    @classmethod
    def from_bytes(cls, data: bytes) -> "BloomFilter":
        if len(data) < HDR.size:
            raise ValueError("truncated BloomFilter payload")
        magic, num_bits, num_hashes = HDR.unpack_from(data, 0)
        if magic != MAGIC:
            raise ValueError("bad BloomFilter magic")
        return cls(num_bits, num_hashes, bytearray(data[HDR.size :]))
