```rust
pub struct FrameDecoder {
    buf: Vec<u8>,
}

impl FrameDecoder {
    pub fn new() -> Self { Self { buf: Vec::new() } }

    pub fn push_and_drain(&mut self, chunk: &[u8]) -> Vec<Vec<u8>> {
        self.buf.extend_from_slice(chunk);
        let mut out = Vec::new();
        let mut off = 0usize;
        while self.buf.len() - off >= 2 {
            let n = u16::from_be_bytes([self.buf[off], self.buf[off + 1]]) as usize;
            if self.buf.len() - off < 2 + n {
                break;
            }
            out.push(self.buf[off + 2..off + 2 + n].to_vec());
            off += 2 + n;
        }
        if off > 0 {
            self.buf.drain(..off);
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::FrameDecoder;

    struct XorShift64(u64);
    impl XorShift64 {
        fn next_u64(&mut self) -> u64 {
            let mut x = self.0;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.0 = x;
            x
        }
        fn range(&mut self, lo: usize, hi_incl: usize) -> usize {
            lo + (self.next_u64() as usize % (hi_incl - lo + 1))
        }
    }

    #[test]
    fn prop_arbitrary_tcp_chunk_splits_preserve_frames() {
        for seed in 1u64..=500 {
            let mut rng = XorShift64(seed * 0x9E37_79B9_7F4A_7C15);
            let msg_count = rng.range(1, 24);
            let mut expected = Vec::with_capacity(msg_count);
            let mut wire = Vec::new();

            for _ in 0..msg_count {
                let len = rng.range(0, 64);
                let payload: Vec<u8> = (0..len).map(|_| rng.next_u64() as u8).collect();
                wire.extend_from_slice(&(len as u16).to_be_bytes());
                wire.extend_from_slice(&payload);
                expected.push(payload);
            }

            let mut dec = FrameDecoder::new();
            let mut actual = Vec::new();
            let mut cursor = 0;
            while cursor < wire.len() {
                let step = rng.range(1, 19).min(wire.len() - cursor);
                actual.extend(dec.push_and_drain(&wire[cursor..cursor + step]));
                cursor += step;
            }
            assert_eq!(actual, expected, "mismatch on PRNG seed={seed}");
        }
    }
}
