from __future__ import annotations
from dataclasses import dataclass, field
from selectors import DefaultSelector, EVENT_READ, EVENT_WRITE
import errno, socket

HIGH_WATER = 65536

@dataclass
class Leg:
    sock: socket.socket
    ready: bool
    peer: Leg | None = None
    tx: bytearray = field(default_factory=bytearray)
    eof: bool = False

def serve_tcp_relay(bind_addr: tuple[str, int], upstream: tuple[str, int]) -> None:
    sel = DefaultSelector()
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.setblocking(False); srv.bind(bind_addr); srv.listen(128)

    def arm(leg: Leg) -> None:
        if not leg.peer or leg.sock.fileno() < 0: return
        r = EVENT_READ if not leg.eof and len(leg.peer.tx) < HIGH_WATER else 0
        w = EVENT_WRITE if leg.tx else 0
        sel.modify(leg.sock, EVENT_WRITE if not leg.ready else (r | w), (on_io, leg))

    def drop(leg: Leg) -> None:
        for x in (leg, leg.peer):
            if x and x.sock.fileno() >= 0:
                sel.unregister(x.sock); x.sock.close()

    def on_accept(s: socket.socket, _: int) -> None:
        cli, _ = s.accept(); cli.setblocking(False)
        up = socket.socket(socket.AF_INET, socket.SOCK_STREAM); up.setblocking(False)
        if up.connect_ex(upstream) not in (0, errno.EINPROGRESS, errno.EWOULDBLOCK):
            cli.close(); up.close(); return
        a, b = Leg(cli, True), Leg(up, False)
        a.peer, b.peer = b, a
        sel.register(cli, EVENT_READ, (on_io, a))
        sel.register(up, EVENT_WRITE, (on_io, b))

    def on_io(leg: Leg, mask: int) -> None:
        p = leg.peer
        try:
            if not leg.ready:
                if leg.sock.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR): return drop(leg)
                leg.ready = True
            if mask & EVENT_READ:
                if buf := leg.sock.recv(16384): p.tx.extend(buf)
                else:
                    leg.eof = True
                    if not p.tx: p.sock.shutdown(socket.SHUT_WR)
            if (mask & EVENT_WRITE) and leg.tx:
                del leg.tx[: leg.sock.send(leg.tx)]
                if not leg.tx and p.eof: leg.sock.shutdown(socket.SHUT_WR)
            if leg.eof and p.eof and not leg.tx and not p.tx: return drop(leg)
            arm(leg); arm(p)
        except OSError:
            drop(leg)

    sel.register(srv, EVENT_READ, (on_accept, srv))
    while True:
        for key, mask in sel.select():
            fn, arg = key.data; fn(arg, mask)
