#include <span>
#include <type_traits>

template <typename T>
concept WireScalar = std::integral<T> && !std::same_as<T, bool>;

template <typename T>
concept PaddingFreeWireStruct =
    std::is_class_v<T> &&
    std::is_standard_layout_v<T> &&
    std::is_trivially_copyable_v<T> &&
    std::has_unique_object_representations_v<T>;

template <WireScalar T>
[[nodiscard]] constexpr T bswap_scalar(T v) noexcept {
    using U = std::make_unsigned_t<T>;
    U u = static_cast<U>(v);
    if constexpr (sizeof(U) == 1) return v;
    else if constexpr (sizeof(U) == 2) u = static_cast<U>((u << 8) | (u >> 8));
    else if constexpr (sizeof(U) == 4) u = __builtin_bswap32(u);
    else if constexpr (sizeof(U) == 8) u = __builtin_bswap64(u);
    return static_cast<T>(u);
}

template <WireScalar T>
void write_be(std::span<std::byte, sizeof(T)> dst, T host_val) noexcept {
    const T wire = (std::endian::native == std::endian::little) ? bswap_scalar(host_val) : host_val;
    std::memcpy(dst.data(), &wire, sizeof(T));
}

template <WireScalar T>
[[nodiscard]] T read_be(std::span<const std::byte, sizeof(T)> src) noexcept {
    T wire{};
    std::memcpy(&wire, src.data(), sizeof(T));
    return (std::endian::native == std::endian::little) ? bswap_scalar(wire) : wire;
}

template <PaddingFreeWireStruct S>
std::span<const std::byte, sizeof(S)> as_wire_bytes(const S& s) noexcept {
    return std::span<const std::byte, sizeof(S)>(reinterpret_cast<const std::byte*>(&s), sizeof(S));
}
