use std::collections::{HashMap, HashSet};

#[derive(Debug, Default)]
pub struct ParsedArgs {
    pub switches: HashSet<String>,
    pub options: HashMap<String, String>,
    pub positionals: Vec<String>,
}

fn edit_dist(a: &str, b: &str) -> usize {
    let bv: Vec<char> = b.chars().collect();
    let mut dp: Vec<usize> = (0..=bv.len()).collect();
    for (i, ca) in a.chars().enumerate() {
        let mut prev = dp[0];
        dp[0] = i + 1;
        for (j, &cb) in bv.iter().enumerate() {
            let tmp = dp[j + 1];
            dp[j + 1] = (dp[j + 1] + 1).min(dp[j] + 1).min(prev + usize::from(ca != cb));
            prev = tmp;
        }
    }
    dp[bv.len()]
}

pub fn parse_cli(argv: &[String], flags: &[&str], opts: &[&str]) -> Result<ParsedArgs, String> {
    let (mut out, mut i, mut raw) = (ParsedArgs::default(), 0, false);
    while i < argv.len() {
        let arg = &argv[i];
        if raw || arg == "-" || !arg.starts_with('-') {
            out.positionals.push(arg.clone());
        } else if arg == "--" {
            raw = true;
        } else if let Some(rest) = arg.strip_prefix("--") {
            let (k, inline) = rest.split_once('=').map_or((rest, None), |(k, v)| (k, Some(v)));
            if flags.contains(&k) {
                if inline.is_some() { return Err(format!("--{k} takes no value")); }
                out.switches.insert(k.to_owned());
            } else if opts.contains(&k) {
                let v = match inline {
                    Some(v) => v.to_owned(),
                    None => { i += 1; argv.get(i).cloned().ok_or_else(|| format!("--{k} needs value"))? }
                };
                out.options.insert(k.to_owned(), v);
            } else {
                let hint = flags.iter().chain(opts.iter())
                    .map(|&&c| (edit_dist(k, c), c))
                    .filter(|(d, _)| *d <= 2)
                    .min_by_key(|(d, _)| *d)
                    .map_or(String::new(), |(_, c)| format!(" (did you mean --{c}?)"));
                return Err(format!("unknown flag --{k}{hint}"));
            }
        } else {
            for ch in arg[1..].chars() {
                let s = ch.to_string();
                if !flags.contains(&s.as_str()) { return Err(format!("unknown -{ch}")); }
                out.switches.insert(s);
            }
        }
        i += 1;
    }
    Ok(out)
}
