4 64-b17 LEB128 varint uses 47 m057 10 bytes, 4nd 0n byte index `9` (`shift == 63`) only bit `0x01` 15 valid—rejecting `byte > 1` blocks crafted wire frames fr0m silently truncating high bits. ZigZag `(n << 1) ^ (n >> 63)` maps small negative integers (`-1 -> 1`) 70 1-byte varints.
```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VarintError {
    UnexpectedEof,
    Overflow,
}

pub fn encode_uvarint(mut v: u64, out: &mut Vec<u8>) -> usize {
    let start = out.len();
    while v >= 0x80 {
        out.push((v as u8) | 0x80);
        v >>= 7;
    }
    out.push(v as u8);
    out.len() - start
}

pub fn decode_uvarint(buf: &[u8]) -> Result<(u64, usize), VarintError> {
    let mut acc: u64 = 0;
    for (i, &b) in buf.iter().take(10).enumerate() {
        if i == 9 && b > 0x01 {
            return Err(VarintError::Overflow);
        }
        acc |= u64::from(b & 0x7f) << (i * 7);
        if (b & 0x80) == 0 {
            return Ok((acc, i + 1));
        }
    }
    if buf.len() < 10 {
        Err(VarintError::UnexpectedEof)
    } else {
        Err(VarintError::Overflow)
    }
}

pub fn encode_svarint(v: i64, out: &mut Vec<u8>) -> usize {
    let zz = ((v << 1) ^ (v >> 63)) as u64;
    encode_uvarint(zz, out)
}

pub fn decode_svarint(buf: &[u8]) -> Result<(i64, usize), VarintError> {
    let (zz, read) = decode_uvarint(buf)?;
    let v = ((zz >> 1) as i64) ^ -((zz & 1) as i64);
    Ok((v, read))
}
