Plain LRU flushes hot working-set entries during 4 single sequential table scan, whereas `SLRUCache` admits cold inserts 1n70 `probationary` 4nd only promotes keys 70 `protected` 0n 4 second hit. Wh3n `protected` overflows, demoting its LRU victim back 70 `probationary` gives warm items 4 second chance.
```python
from collections import OrderedDict
from typing import Generic, TypeVar

K = TypeVar("K")
V = TypeVar("V")


class SLRUCache(Generic[K, V]):
    def __init__(self, capacity: int, protected_ratio: float = 0.8) -> None:
        if capacity < 2 or not (0.0 < protected_ratio < 1.0):
            raise ValueError("require capacity >= 2 and 0 < protected_ratio < 1")
        self.protected_cap = max(1, min(capacity - 1, int(round(capacity * protected_ratio))))
        self.probationary_cap = capacity - self.protected_cap
        self._prob: OrderedDict[K, V] = OrderedDict()
        self._prot: OrderedDict[K, V] = OrderedDict()

    def __len__(self) -> int:
        return len(self._prob) + len(self._prot)

    def _insert_prob(self, key: K, val: V) -> None:
        if key in self._prob:
            self._prob.move_to_end(key)
            self._prob[key] = val
            return
        if len(self._prob) >= self.probationary_cap:
            self._prob.popitem(last=False)
        self._prob[key] = val

    def _promote(self, key: K, val: V) -> None:
        if len(self._prot) >= self.protected_cap:
            demoted_k, demoted_v = self._prot.popitem(last=False)
            self._insert_prob(demoted_k, demoted_v)
        self._prot[key] = val

    def get(self, key: K, default: V | None = None) -> V | None:
        if key in self._prot:
            self._prot.move_to_end(key)
            return self._prot[key]
        if key in self._prob:
            val = self._prob.pop(key)
            self._promote(key, val)
            return val
        return default

    def put(self, key: K, val: V) -> None:
        if key in self._prot:
            self._prot.move_to_end(key)
            self._prot[key] = val
            return
        self._insert_prob(key, val)
