4 concurrent register trace 15 linearizable iff minimal unplaced operations (`op.invokeTs < min(unplaced.returnTs)`) can step 7h3 abstract register sequentially w17h0u7 contradiction. Memoizing `(placedBitmask, registerValue)` prunes redundant interleavings 50 Vitest catches stale-read anomalies 1n milliseconds.
```typescript
import { describe, expect, it } from "vitest";

export type RegOp =
  | { kind: "write"; val: number; invokeTs: number; returnTs: number }
  | { kind: "read"; val: number | undefined; invokeTs: number; returnTs: number };

export function isLinearizableRegister(ops: readonly RegOp[], initial?: number): boolean {
  if (ops.length > 24) throw new RangeError("exact bitmask solver capped at 24 ops");
  const fullMask = (1 << ops.length) - 1;
  const memo = new Set<string>();

  function search(mask: number, state: number | undefined): boolean {
    if (mask === fullMask) return true;
    const key = `${mask}:${String(state)}`;
    if (memo.has(key)) return false;

    let earliestReturn = Infinity;
    for (let i = 0; i < ops.length; i++) {
      if ((mask & (1 << i)) === 0 && ops[i].returnTs < earliestReturn) {
        earliestReturn = ops[i].returnTs;
      }
    }

    for (let i = 0; i < ops.length; i++) {
      if ((mask & (1 << i)) !== 0) continue;
      const op = ops[i];
      if (op.invokeTs > earliestReturn) continue;
      if (op.kind === "write") {
        if (search(mask | (1 << i), op.val)) return true;
      } else if (op.val === state) {
        if (search(mask | (1 << i), state)) return true;
      }
    }
    memo.add(key);
    return false;
  }

  return search(0, initial);
}

describe("isLinearizableRegister", () => {
  it("accepts overlapping read/write returning either old or new value", () => {
    const trace: RegOp[] = [
      { kind: "write", val: 1, invokeTs: 0, returnTs: 10 },
      { kind: "write", val: 2, invokeTs: 8, returnTs: 20 },
      { kind: "read", val: 1, invokeTs: 9, returnTs: 15 },
    ];
    expect(isLinearizableRegister(trace, 0)).toBe(true);
  });

  it("rejects stale read strictly after a completed write", () => {
    const broken: RegOp[] = [
      { kind: "write", val: 1, invokeTs: 0, returnTs: 5 },
      { kind: "write", val: 2, invokeTs: 6, returnTs: 10 },
      { kind: "read", val: 1, invokeTs: 11, returnTs: 14 },
    ];
    expect(isLinearizableRegister(broken, 0)).toBe(false);
  });
});
