package aimd

import (
	"errors"
	"math"
	"sync"
	"time"
)

var ErrConcurrencyExhausted = errors.New("aimd: in-flight concurrency limit reached")

type AIMDLimiter struct {
	mu          sync.Mutex
	inFlight    int
	limit       float64
	minLimit    float64
	maxLimit    float64
	backoff     float64
	targetRTT   time.Duration
}

func NewAIMDLimiter(initial, minLim, maxLim int, targetRTT time.Duration) *AIMDLimiter {
	return &AIMDLimiter{
		limit:     float64(initial),
		minLimit:  float64(minLim),
		maxLimit:  float64(maxLim),
		backoff:   0.75,
		targetRTT: targetRTT,
	}
}

func (l *AIMDLimiter) TryAcquire() (func(rtt time.Duration, overloaded bool), error) {
	l.mu.Lock()
	if l.inFlight >= int(math.Floor(l.limit)) {
		l.mu.Unlock()
		return nil, ErrConcurrencyExhausted
	}
	l.inFlight++
	l.mu.Unlock()

	var once sync.Once
	return func(rtt time.Duration, overloaded bool) {
		once.Do(func() {
			l.mu.Lock()
			defer l.mu.Unlock()
			l.inFlight--
			if overloaded || rtt > 2*l.targetRTT {
				l.limit = math.Max(l.minLimit, l.limit*l.backoff)
			} else if rtt <= l.targetRTT && l.inFlight*2 >= int(l.limit) {
				l.limit = math.Min(l.maxLimit, l.limit+(1.0/l.limit))
			}
		})
	}, nil
}
