from itertools import count
from typing import NamedTuple

class TVar(NamedTuple): name: str
class TCon(NamedTuple): name: str
class TFun(NamedTuple):
    arg: "Type"
    ret: "Type"

Type = TVar | TCon | TFun
Subst = dict[str, Type]
Scheme = tuple[frozenset[str], Type]

def apply_t(s: Subst, t: Type) -> Type:
    if isinstance(t, TVar):
        return apply_t(s, s[t.name]) if t.name in s else t
    return TFun(apply_t(s, t.arg), apply_t(s, t.ret)) if isinstance(t, TFun) else t

def ftv(t: Type) -> set[str]:
    return {t.name} if isinstance(t, TVar) else (ftv(t.arg) | ftv(t.ret)) if isinstance(t, TFun) else set()

def compose(s2: Subst, s1: Subst) -> Subst:
    return {k: apply_t(s2, v) for k, v in s1.items()} | s2

def unify(t1: Type, t2: Type) -> Subst:
    if t1 == t2:
        return {}
    if isinstance(t1, TVar):
        if t1.name in ftv(t2):
            raise TypeError(f"occurs check: {t1} in {t2}")
        return {t1.name: t2}
    if isinstance(t2, TVar):
        return unify(t2, t1)
    if isinstance(t1, TFun) and isinstance(t2, TFun):
        s1 = unify(t1.arg, t2.arg)
        return compose(unify(apply_t(s1, t1.ret), apply_t(s1, t2.ret)), s1)
    raise TypeError(f"mismatch: {t1} vs {t2}")

def infer(env: dict[str, Scheme], expr: tuple, _seq=count(1)) -> tuple[Subst, Type]:
    fresh = lambda: TVar(f"t{next(_seq)}")
    app_env = lambda s, g: {k: (qv, apply_t(s, b)) for k, (qv, b) in g.items()}
    match expr:
        case ("lit", v):
            return {}, TCon("Bool" if isinstance(v, bool) else "Int")
        case ("var", x):
            qv, b = env[x]
            return {}, apply_t({v: fresh() for v in qv}, b)
        case ("lam", p, body):
            tv = fresh()
            s1, rt = infer(env | {p: (frozenset(), tv)}, body, _seq)
            return s1, TFun(apply_t(s1, tv), rt)
        case ("app", fn_e, arg_e):
            tv = fresh()
            s1, ft = infer(env, fn_e, _seq)
            s2, at = infer(app_env(s1, env), arg_e, _seq)
            s3 = unify(apply_t(s2, ft), TFun(at, tv))
            return compose(s3, compose(s2, s1)), apply_t(s3, tv)
        case ("let", x, val_e, body_e):
            s1, vt = infer(env, val_e, _seq)
            env1 = app_env(s1, env)
            ef = set().union(*(ftv(b) - qv for qv, b in env1.values()))
            s2, bt = infer(env1 | {x: (frozenset(ftv(vt) - ef), vt)}, body_e, _seq)
            return compose(s2, s1), bt
    raise ValueError(expr)
