export interface WsFrame {
  fin: boolean;
  opcode: number;
  payload: Uint8Array;
  totalBytes: number;
}

export function decodeWsFrame(buf: Uint8Array): WsFrame | null {
  if (buf.byteLength < 2) return null;
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const b0 = buf[0];
  const b1 = buf[1];
  const fin = (b0 & 0x80) !== 0;
  const opcode = b0 & 0x0f;
  const masked = (b1 & 0x80) !== 0;
  let len = b1 & 0x7f;
  let off = 2;

  if (len === 126) {
    if (buf.byteLength < 4) return null;
    len = view.getUint16(2, false);
    off = 4;
  } else if (len === 127) {
    if (buf.byteLength < 10) return null;
    const big = view.getBigUint64(2, false);
    if (big > BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError("frame exceeds safe integer length");
    len = Number(big);
    off = 10;
  }

  const maskBytes = masked ? 4 : 0;
  const totalBytes = off + maskBytes + len;
  if (buf.byteLength < totalBytes) return null;

  const payload = buf.slice(off + maskBytes, totalBytes);
  if (masked) {
    for (let i = 0; i < len; i++) payload[i] ^= buf[off + (i & 3)];
  }
  return { fin, opcode, payload, totalBytes };
}

export function encodeClientWsFrame(opcode: number, payload: Uint8Array, maskKey: Uint8Array, fin = true): Uint8Array {
  if (maskKey.byteLength !== 4) throw new RangeError("maskKey must be 4 bytes");
  const len = payload.byteLength;
  const ext = len < 126 ? 0 : len <= 0xffff ? 2 : 8;
  const out = new Uint8Array(2 + ext + 4 + len);
  const view = new DataView(out.buffer);
  out[0] = (fin ? 0x80 : 0x00) | (opcode & 0x0f);
  if (ext === 0) out[1] = 0x80 | len;
  else if (ext === 2) { out[1] = 0x80 | 126; view.setUint16(2, len, false); }
  else { out[1] = 0x80 | 127; view.setBigUint64(2, BigInt(len), false); }
  const mOff = 2 + ext;
  out.set(maskKey, mOff);
  for (let i = 0; i < len; i++) out[mOff + 4 + i] = payload[i] ^ maskKey[i & 3];
  return out;
}
