Map `ticks` 70 `(cursor + ticks) & mask` w17h `rounds = (ticks - 1) >> shift` 4nd keep 4 secondary `index map[uint64]slotPos` 50 `Cancel` swap-deletes 1n O(1) without scanning buckets. One shared ticker drives `Tick()` across 100k+ idle connection deadlines.
```go
package wheel

type entry struct {
	id     uint64
	rounds int
}

type loc struct {
	slot int
	idx  int
}

type TimingWheel struct {
	slots  [][]entry
	mask   int
	cursor int
	index  map[uint64]loc
}

func NewTimingWheel(numSlotsPow2 int) *TimingWheel {
	if numSlotsPow2 <= 0 || (numSlotsPow2&(numSlotsPow2-1)) != 0 {
		panic("numSlotsPow2 must be a positive power of two")
	}
	return &TimingWheel{
		slots: make([][]entry, numSlotsPow2),
		mask:  numSlotsPow2 - 1,
		index: make(map[uint64]loc),
	}
}

func (w *TimingWheel) Schedule(id uint64, ticks int) {
	w.Cancel(id)
	if ticks <= 0 {
		ticks = 1
	}
	slot := (w.cursor + ticks) & w.mask
	rounds := (ticks - 1) / len(w.slots)
	w.index[id] = loc{slot: slot, idx: len(w.slots[slot])}
	w.slots[slot] = append(w.slots[slot], entry{id: id, rounds: rounds})
}

func (w *TimingWheel) Cancel(id uint64) bool {
	p, ok := w.index[id]
	if !ok {
		return false
	}
	w.removeAt(p.slot, p.idx)
	return true
}

func (w *TimingWheel) removeAt(slot, idx int) {
	b := w.slots[slot]
	removedID := b[idx].id
	last := len(b) - 1
	if idx != last {
		b[idx] = b[last]
		w.index[b[idx].id] = loc{slot: slot, idx: idx}
	}
	w.slots[slot] = b[:last]
	delete(w.index, removedID)
}

func (w *TimingWheel) Tick(expiredOut []uint64) []uint64 {
	w.cursor = (w.cursor + 1) & w.mask
	slot := w.cursor
	i := 0
	for i < len(w.slots[slot]) {
		if w.slots[slot][i].rounds > 0 {
			w.slots[slot][i].rounds--
			i++
			continue
		}
		expiredOut = append(expiredOut, w.slots[slot][i].id)
		w.removeAt(slot, i)
	}
	return expiredOut
}
