  const calls: RecordedCall[] = [];

  const fetchImpl: typeof fetch = async (input, init) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;
    const method = init?.method ?? (input instanceof Request ? input.method : "GET");
    calls.push({ url, method, headers: new Headers(init?.headers) });

    const step = queue.shift();
    if (!step) throw new Error(`unexpected fetch call #${calls.length} to ${url}`);

    await waitOrAbort(step.delayMs ?? 0, init?.signal);
    if (step.kind === "network_error") {
      throw new TypeError(step.message);
    }
    return new Response(step.body ?? "", { status: step.status, headers: step.headers });
  };

  return { fetchImpl, calls, remainingSteps: () => queue.length };
}
