import mmap
import os
import struct
from collections.abc import Iterator

REC_STRUCT = struct.Struct("!QQQ")
REC_SIZE = REC_STRUCT.size  # 24 bytes: (ts_ns, stream_id, file_offset)


class MmapTimeIndex:
    def __init__(self, path: str) -> None:
        self._fd = os.open(path, os.O_RDONLY)
        size = os.fstat(self._fd).st_size
        if size % REC_SIZE != 0:
            os.close(self._fd)
            raise ValueError(f"corrupt index size {size}: not a multiple of {REC_SIZE}")
        self._count = size // REC_SIZE
        self._mm = mmap.mmap(self._fd, 0, access=mmap.ACCESS_READ) if size > 0 else None

    def close(self) -> None:
        if self._mm is not None:
            self._mm.close()
            self._mm = None
        if self._fd >= 0:
            os.close(self._fd)
            self._fd = -1

    def _ts_at(self, idx: int) -> int:
        assert self._mm is not None
        return int.from_bytes(self._mm[idx * REC_SIZE : idx * REC_SIZE + 8], "big")

    def _lower_bound(self, target_ns: int) -> int:
        lo, hi = 0, self._count
        while lo < hi:
            mid = (lo + hi) >> 1
            if self._ts_at(mid) < target_ns:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def query_range(self, start_ns: int, end_ns_excl: int) -> Iterator[tuple[int, int, int]]:
        if self._mm is None or start_ns >= end_ns_excl:
            return
        lo = self._lower_bound(start_ns)
        hi = self._lower_bound(end_ns_excl)
        for idx in range(lo, hi):
            yield REC_STRUCT.unpack_from(self._mm, idx * REC_SIZE)
