package batcher

import (
	"context"
	"time"
)

type outcome[Out any] struct {
	val Out
	err error
}

type req[In, Out any] struct {
	item  In
	reply chan outcome[Out]
}

type Batcher[In, Out any] struct {
	inbox chan req[In, Out]
}

func NewBatcher[In, Out any](ctx context.Context, maxBatch int, linger time.Duration, flush func([]In) ([]Out, error)) *Batcher[In, Out] {
	b := &Batcher[In, Out]{inbox: make(chan req[In, Out], maxBatch*4)}
	go b.loop(ctx, maxBatch, linger, flush)
	return b
}

func (b *Batcher[In, Out]) Submit(ctx context.Context, item In) (Out, error) {
	var zero Out
	r := req[In, Out]{item: item, reply: make(chan outcome[Out], 1)}
	select {
	case b.inbox <- r:
	case <-ctx.Done():
		return zero, ctx.Err()
	}
	select {
	case out := <-r.reply:
		return out.val, out.err
	case <-ctx.Done():
		return zero, ctx.Err()
	}
}

func (b *Batcher[In, Out]) loop(ctx context.Context, maxBatch int, linger time.Duration, flush func([]In) ([]Out, error)) {
	batch := make([]req[In, Out], 0, maxBatch)
	timer := time.NewTimer(linger)
	if !timer.Stop() {
		<-timer.C
	}
	fire := func() {
		if len(batch) == 0 {
			return
		}
		inputs := make([]In, len(batch))
		for i := range batch {
			inputs[i] = batch[i].item
		}
		outs, err := flush(inputs)
		for i, waiter := range batch {
			var v Out
			if err == nil && i < len(outs) {
				v = outs[i]
			}
			waiter.reply <- outcome[Out]{val: v, err: err}
		}
		batch = batch[:0]
	}

	for {
		select {
		case <-ctx.Done():
			fire()
			return
		case r := <-b.inbox:
			if len(batch) == 0 {
				timer.Reset(linger)
			}
			batch = append(batch, r)
			if len(batch) >= maxBatch {
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				fire()
			}
		case <-timer.C:
			fire()
		}
	}
}
