#!/usr/bin/env python3
import argparse
import ast
import sys
from pathlib import Path


def is_type_checking_guard(test: ast.expr) -> bool:
    if isinstance(test, ast.Name):
        return test.id == "TYPE_CHECKING"
    if isinstance(test, ast.Attribute) and isinstance(test.value, ast.Name):
        return test.value.id == "typing" and test.attr == "TYPE_CHECKING"
    return False


class BoundaryVisitor(ast.NodeVisitor):
    def __init__(self, forbidden: tuple[str, ...], allow_tc: bool) -> None:
        self.forbidden = forbidden
        self.allow_tc = allow_tc
        self._in_tc = 0
        self.violations: list[tuple[int, int, str]] = []

    def _check(self, mod: str, line: int, col: int) -> None:
        if self.allow_tc and self._in_tc > 0:
            return
        if any(mod == p or mod.startswith(p + ".") for p in self.forbidden):
            self.violations.append((line, col, mod))

    def visit_If(self, node: ast.If) -> None:
        if is_type_checking_guard(node.test):
            self._in_tc += 1
            for stmt in node.body:
                self.visit(stmt)
            self._in_tc -= 1
            for stmt in node.orelse:
                self.visit(stmt)
        else:
            self.generic_visit(node)

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            self._check(alias.name, node.lineno, node.col_offset)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        if node.module:
            self._check(node.module, node.lineno, node.col_offset)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("paths", nargs="+", type=Path)
    ap.add_argument("--forbid-prefix", action="append", required=True)
    ap.add_argument("--allow-type-checking", action="store_true")
    args = ap.parse_args(argv)
    forbidden = tuple(args.forbid_prefix)
    failed = 0
    for root in args.paths:
        targets = [root] if root.is_file() else sorted(root.rglob("*.py"))
        for py in targets:
            tree = ast.parse(py.read_text(encoding="utf-8"), filename=str(py))
            v = BoundaryVisitor(forbidden, args.allow_type_checking)
            v.visit(tree)
            for ln, col, mod in v.violations:
                print(f"{py}:{ln}:{col}: forbidden runtime import '{mod}'", file=sys.stderr)
                failed = 1
    return failed


if __name__ == "__main__":
    raise SystemExit(main())
