#[derive(Debug, Default, PartialEq, Eq)]
pub struct CacheDirectives {
    pub no_store: bool,
    pub no_cache: bool,
    pub must_revalidate: bool,
    pub max_age: Option<u64>,
    pub s_maxage: Option<u64>,
    pub stale_while_revalidate: Option<u64>,
}

fn split_header_tokens(s: &str) -> Vec<&str> {
    let (mut out, mut start, mut in_q, mut esc) = (Vec::new(), 0, false, false);
    for (i, b) in s.bytes().enumerate() {
        if esc { esc = false; continue; }
        match b {
            b'\\' if in_q => esc = true,
            b'"' => in_q = !in_q,
            b',' if !in_q => {
                out.push(s[start..i].trim());
                start = i + 1;
            }
            _ => {}
        }
    }
    out.push(s[start..].trim());
    out
}

impl CacheDirectives {
    pub fn parse(header: &str) -> Self {
        let mut d = Self::default();
        for part in split_header_tokens(header) {
            if part.is_empty() { continue; }
            let (raw_k, raw_v) = part.split_once('=').map_or((part, None), |(k, v)| {
                (k.trim(), Some(v.trim().trim_matches('"')))
            });
            match raw_k.to_ascii_lowercase().as_str() {
                "no-store" => d.no_store = true,
                "no-cache" => d.no_cache = true,
                "must-revalidate" => d.must_revalidate = true,
                "max-age" => d.max_age = raw_v.and_then(|v| v.parse().ok()),
                "s-maxage" => d.s_maxage = raw_v.and_then(|v| v.parse().ok()),
                "stale-while-revalidate" => d.stale_while_revalidate = raw_v.and_then(|v| v.parse().ok()),
                _ => {}
            }
        }
        d
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ETag<'a> {
    pub weak: bool,
    pub tag: &'a str,
}

impl<'a> ETag<'a> {
    pub fn parse(raw: &'a str) -> Option<Self> {
        let s = raw.trim();
        let (weak, rest) = s.strip_prefix("W/").map_or((false, s), |r| (true, r));
        let inner = rest.strip_prefix('"')?.strip_suffix('"')?;
        if inner.contains('"') { return None; }
        Some(Self { weak, tag: inner })
    }

    pub fn strong_eq(self, other: Self) -> bool {
        !self.weak && !other.weak && self.tag == other.tag
    }

    pub fn weak_eq(self, other: Self) -> bool {
        self.tag == other.tag
    }
}
