T = TypeVar("T")
Dot = tuple[str, int]


class ORSet(Generic[T]):
    def __init__(self, replica_id: str) -> None:
        self.replica_id = replica_id
        self.vclock: dict[str, int] = {}
        self.entries: dict[T, set[Dot]] = {}

