        return {item for item, dots in self.entries.items() if dots}

    def __contains__(self, item: T) -> bool:
        return bool(self.entries.get(item))

    def add(self, item: T) -> None:
        nxt = self.vclock.get(self.replica_id, 0) + 1
        self.vclock[self.replica_id] = nxt
        existing = {d for d in self.entries.get(item, set()) if d[0] != self.replica_id}
        existing.add((self.replica_id, nxt))
        self.entries[item] = existing

    def remove(self, item: T) -> None:
        self.entries.pop(item, None)

