#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct HlcTimestamp(pub u64);

impl HlcTimestamp {
    pub fn new(wall_ms: u64, logical: u16) -> Self {
        Self((wall_ms << 16) | u64::from(logical))
    }
    pub fn wall_ms(self) -> u64 { self.0 >> 16 }
    pub fn logical(self) -> u16 { (self.0 & 0xFFFF) as u16 }
}

pub struct Hlc {
    last: HlcTimestamp,
    max_drift_ms: u64,
}

impl Hlc {
    pub fn new(max_drift_ms: u64) -> Self {
        Self { last: HlcTimestamp(0), max_drift_ms }
    }

    pub fn tick(&mut self, phys_ms: u64) -> Result<HlcTimestamp, &'static str> {
        if phys_ms > self.last.wall_ms() {
            self.last = HlcTimestamp::new(phys_ms, 0);
        } else {
            let c = self.last.logical().checked_add(1).ok_or("hlc logical overflow")?;
            self.last = HlcTimestamp::new(self.last.wall_ms(), c);
        }
        Ok(self.last)
    }

    pub fn observe(&mut self, phys_ms: u64, remote: HlcTimestamp) -> Result<HlcTimestamp, &'static str> {
        if remote.wall_ms() > phys_ms.saturating_add(self.max_drift_ms) {
            return Err("remote clock drift exceeds bound");
        }
        let max_wall = phys_ms.max(self.last.wall_ms()).max(remote.wall_ms());
        let next_log = match (max_wall == self.last.wall_ms(), max_wall == remote.wall_ms()) {
            (true, true) => self.last.logical().max(remote.logical()).checked_add(1),
            (true, false) => self.last.logical().checked_add(1),
            (false, true) => remote.logical().checked_add(1),
            (false, false) => Some(0),
        }.ok_or("hlc logical overflow")?;
        self.last = HlcTimestamp::new(max_wall, next_log);
        Ok(self.last)
    }
}

