use std::ops::{Deref, DerefMut};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::net::TcpStream;
use tokio::sync::{OwnedSemaphorePermit, Semaphore};

struct IdleConn {
    stream: TcpStream,
    returned_at: Instant,
}

pub struct LifoPool {
    addr: String,
    max_idle: Duration,
    sem: Arc<Semaphore>,
    idle: Arc<Mutex<Vec<IdleConn>>>,
}

pub struct PooledConn {
    stream: Option<TcpStream>,
    broken: bool,
    idle: Arc<Mutex<Vec<IdleConn>>>,
    _permit: OwnedSemaphorePermit,
}

impl Deref for PooledConn {
    type Target = TcpStream;
    fn deref(&self) -> &Self::Target { self.stream.as_ref().unwrap() }
}

impl DerefMut for PooledConn {
    fn deref_mut(&mut self) -> &mut Self::Target { self.stream.as_mut().unwrap() }
}

impl PooledConn {
    pub fn mark_broken(&mut self) { self.broken = true; }
}

impl Drop for PooledConn {
    fn drop(&mut self) {
        if !self.broken {
            if let Some(stream) = self.stream.take() {
                if let Ok(mut stack) = self.idle.lock() {
                    stack.push(IdleConn { stream, returned_at: Instant::now() });
                }
            }
        }
    }
}

impl LifoPool {
    pub fn new(addr: impl Into<String>, max_open: usize, max_idle: Duration) -> Self {
        Self {
            addr: addr.into(),
            max_idle,
            sem: Arc::new(Semaphore::new(max_open)),
            idle: Arc::new(Mutex::new(Vec::with_capacity(max_open))),
        }
    }

    pub async fn acquire(&self) -> std::io::Result<PooledConn> {
        let permit = Arc::clone(&self.sem).acquire_owned().await.unwrap();
        let now = Instant::now();
        let reused = {
            let mut stack = self.idle.lock().unwrap();
            loop {
                let Some(cand) = stack.pop() else { break None };
                if now.duration_since(cand.returned_at) <= self.max_idle {
                    break Some(cand.stream);
                }
            }
        };
        let stream = match reused {
            Some(s) => s,
            None => TcpStream::connect(&self.addr).await?,
        };
        Ok(PooledConn { stream: Some(stream), broken: false, idle: Arc::clone(&self.idle), _permit: permit })
    }
}
