type ParamVal = string | number;

type SegmentParam<S extends string> = S extends `:${infer Name}?`
  ? { [K in Name]?: ParamVal }
  : S extends `:${infer Name}`
    ? { [K in Name]: ParamVal }
    : S extends `*${infer Wild}`
      ? { [K in Wild extends "" ? "wildcard" : Wild]: string }
      : {};

type Flatten<T> = { [K in keyof T]: T[K] };

type ParseSegments<Path extends string> = Path extends `${infer Head}/${infer Tail}`
  ? SegmentParam<Head> & ParseSegments<Tail>
  : SegmentParam<Path>;

export type RouteParams<Path extends string> = Flatten<
  ParseSegments<Path extends `/${infer Rel}` ? Rel : Path>
>;

export function buildPath<P extends string>(
  pattern: P,
  params: RouteParams<P>,
): string {
  const bag = params as Record<string, ParamVal | undefined>;
  const leadingSlash = pattern.startsWith("/");
  const out: string[] = [];

  for (const seg of pattern.split("/").filter(Boolean)) {
    if (seg.startsWith(":") && seg.endsWith("?")) {
      const val = bag[seg.slice(1, -1)];
      if (val !== undefined) out.push(encodeURIComponent(String(val)));
    } else if (seg.startsWith(":")) {
      const val = bag[seg.slice(1)];
      if (val === undefined) throw new Error(`Missing param ${seg}`);
      out.push(encodeURIComponent(String(val)));
    } else if (seg.startsWith("*")) {
      const key = seg.slice(1) || "wildcard";
      const raw = String(bag[key] ?? "");
      out.push(...raw.split("/").filter(Boolean).map(encodeURIComponent));
    } else {
      out.push(seg);
    }
  }
  return (leadingSlash ? "/" : "") + out.join("/");
}
