#include <atomic>
#include <cstddef>
#include <new>
#include <optional>
#include <type_traits>
#include <utility>

template <typename T, std::size_t CapPow2>
requires (CapPow2 >= 2) && ((CapPow2 & (CapPow2 - 1)) == 0) && std::is_nothrow_move_constructible_v<T>
class SpscQueue {
    static constexpr std::size_t kMask = CapPow2 - 1;
    struct alignas(T) Slot { std::byte storage[sizeof(T)]; };

    alignas(64) std::atomic<std::size_t> write_idx_{0};
    std::size_t read_cache_{0};

    alignas(64) std::atomic<std::size_t> read_idx_{0};
    std::size_t write_cache_{0};

    alignas(64) Slot ring_[CapPow2];

public:
    SpscQueue() = default;
    SpscQueue(const SpscQueue&) = delete;
    SpscQueue& operator=(const SpscQueue&) = delete;

    ~SpscQueue() {
        while (try_pop().has_value()) {}
    }

    [[nodiscard]] bool try_push(T item) noexcept {
        const std::size_t w = write_idx_.load(std::memory_order_relaxed);
        if (w - read_cache_ == CapPow2) {
            read_cache_ = read_idx_.load(std::memory_order_acquire);
            if (w - read_cache_ == CapPow2) return false;
        }
        ::new (&ring_[w & kMask]) T(std::move(item));
        write_idx_.store(w + 1, std::memory_order_release);
        return true;
    }

    [[nodiscard]] std::optional<T> try_pop() noexcept {
        const std::size_t r = read_idx_.load(std::memory_order_relaxed);
        if (r == write_cache_) {
            write_cache_ = write_idx_.load(std::memory_order_acquire);
            if (r == write_cache_) return std::nullopt;
        }
        T* ptr = std::launder(reinterpret_cast<T*>(&ring_[r & kMask]));
        std::optional<T> out(std::move(*ptr));
        ptr->~T();
        read_idx_.store(r + 1, std::memory_order_release);
        return out;
    }
};
