#!/usr/bin/env python3
import argparse
import json
import sys
from typing import Any


def json_type_name(val: Any) -> str:
    if isinstance(val, bool):
        return "bool"
    if isinstance(val, (int, float)):
        return "number"
    if isinstance(val, str):
        return "string"
    if isinstance(val, list):
        return "array"
    if isinstance(val, dict):
        return "object"
    return "null"


def extract_dot_path(doc: dict[str, Any], parts: list[str]) -> Any:
    cur: Any = doc
    for p in parts:
        if not isinstance(cur, dict) or p not in cur:
            return None
        cur = cur[p]
    return cur


def format_cell(val: Any) -> str:
    if val is None:
        return ""
    if isinstance(val, (dict, list, bool)):
        return json.dumps(val, separators=(",", ":"))
    return str(val).replace("\t", " ").replace("\n", " ")


def main() -> int:
    ap = argparse.ArgumentParser(description="Project NDJSON fields and detect type drift.")
    ap.add_argument("-f", "--fields", required=True, help="Comma-separated dot paths")
    args = ap.parse_args()

    paths = [(f.strip(), f.strip().split(".")) for f in args.fields.split(",") if f.strip()]
    baseline_types: dict[str, str] = {}
    drift_count = 0

    print("\t".join(name for name, _ in paths))
    for lineno, raw in enumerate(sys.stdin, 1):
        raw = raw.strip()
        if not raw:
            continue
        doc = json.loads(raw)
        row: list[str] = []
        for name, parts in paths:
            val = extract_dot_path(doc, parts)
            if val is not None:
                tname = json_type_name(val)
                prev = baseline_types.setdefault(name, tname)
                if prev != tname:
                    drift_count += 1
                    print(f"line {lineno}: field '{name}' drifted {prev} -> {tname}", file=sys.stderr)
                    baseline_types[name] = tname
            row.append(format_cell(val))
        print("\t".join(row))
    return 1 if drift_count > 0 else 0


if __name__ == "__main__":
    raise SystemExit(main())
