tlv_status_t tlv_next(tlv_cursor_t *cur, tlv_view_t *out) {
    if (!cur || !out || (!cur->buf && cur->len > 0)) {
        return TLV_ERR_BAD_ARG;
    }
    if (cur->offset >= cur->len) {
        return TLV_DONE;
    }
    size_t rem = cur->len - cur->offset;
    if (rem < 4U) {
        return TLV_ERR_TRUNCATED;
    }

    const uint8_t *p = cur->buf + cur->offset;
    uint8_t tag = p[0];
    uint32_t pay_len = ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
    if ((size_t)pay_len > rem - 4U) {
        return TLV_ERR_TRUNCATED;
    }

    out->type = tag;
    out->length = pay_len;
    out->value = p + 4U;
    cur->offset += 4U + (size_t)pay_len;
    return TLV_OK;
}
