export function parseIpv4Uint32(ip: string): number {
  const parts = ip.split(".");
  if (parts.length !== 4) throw new SyntaxError(`invalid IPv4: ${ip}`);
  let acc = 0;
  for (const p of parts) {
    const n = Number(p);
    if (!Number.isInteger(n) || n < 0 || n > 255 || p === "") throw new SyntaxError(`invalid IPv4: ${ip}`);
    acc = ((acc << 8) | n) >>> 0;
  }
  return acc;
}

export class Ipv4LpmTrie<V> {
  private children = new Int32Array(2048).fill(-1); // [node*2 + bit]
  private valIndex = new Int32Array(1024).fill(-1);
  private values: V[] = [];
  private nodeCount = 1; // 0 = root

  insert(cidr: string, value: V): void {
    const [ipStr, lenStr] = cidr.split("/");
    const plen = Number(lenStr);
    if (!Number.isInteger(plen) || plen < 0 || plen > 32) throw new RangeError(`bad prefix: ${cidr}`);
    const ip = parseIpv4Uint32(ipStr);
    let cur = 0;
    for (let i = 0; i < plen; i++) {
      const bit = (ip >>> (31 - i)) & 1;
      let next = this.children[cur * 2 + bit];
      if (next === -1) {
        next = this.allocNode();
        this.children[cur * 2 + bit] = next;
      }
      cur = next;
    }
    if (this.valIndex[cur] === -1) {
      this.valIndex[cur] = this.values.length;
      this.values.push(value);
    } else {
      this.values[this.valIndex[cur]] = value;
    }
  }

  lookup(ip: string | number): V | undefined {
    const addr = typeof ip === "number" ? ip >>> 0 : parseIpv4Uint32(ip);
    let cur = 0;
    let best = this.valIndex[0];
    for (let i = 0; i < 32; i++) {
      const bit = (addr >>> (31 - i)) & 1;
      cur = this.children[cur * 2 + bit];
      if (cur === -1) break;
      if (this.valIndex[cur] !== -1) best = this.valIndex[cur];
    }
    return best === -1 ? undefined : this.values[best];
  }

  private allocNode(): number {
    const id = this.nodeCount++;
    if (id >= this.valIndex.length) {
      const nextCap = this.valIndex.length * 2;
      const nextCh = new Int32Array(nextCap * 2).fill(-1);
      nextCh.set(this.children);
      this.children = nextCh;
      const nextVal = new Int32Array(nextCap).fill(-1);
      nextVal.set(this.valIndex);
      this.valIndex = nextVal;
    }
    return id;
  }
}
