type truncConn struct {
	net.Conn
	remaining int
}

func (c *truncConn) Write(b []byte) (int, error) {
	if c.remaining <= 0 {
		_ = c.Conn.Close()
		return 0, net.ErrClosed
	}
	if len(b) > c.remaining {
		n, _ := c.Conn.Write(b[:c.remaining])
		c.remaining = 0
		_ = c.Conn.Close()
		return n, io.ErrShortWrite
	}
	n, err := c.Conn.Write(b)
	c.remaining -= n
	return n, err
}

type TruncatingListener struct {
	net.Listener
	MaxTxBytes int
}

func (l *TruncatingListener) Accept() (net.Conn, error) {
	c, err := l.Listener.Accept()
	if err != nil {
		return nil, err
	}
	return &truncConn{Conn: c, remaining: l.MaxTxBytes}, nil
}

