use std::io::{self, Read, Write};
use std::marker::PhantomData;
use std::net::{SocketAddr, TcpStream};

mod private {
    pub trait Sealed {}
}

pub trait ConnState: private::Sealed {}

pub struct Disconnected;
pub struct Handshaking;
pub struct Authenticated;

impl private::Sealed for Disconnected {}
impl private::Sealed for Handshaking {}
impl private::Sealed for Authenticated {}
impl ConnState for Disconnected {}
impl ConnState for Handshaking {}
impl ConnState for Authenticated {}

pub struct WireClient<S: ConnState> {
    addr: SocketAddr,
    stream: Option<TcpStream>,
    session_tag: u64,
    _state: PhantomData<S>,
}

impl WireClient<Disconnected> {
    pub fn new(addr: SocketAddr) -> Self {
        Self { addr, stream: None, session_tag: 0, _state: PhantomData }
    }

    pub fn connect(self) -> io::Result<WireClient<Handshaking>> {
        let s = TcpStream::connect(self.addr)?;
        s.set_nodelay(true)?;
        Ok(WireClient { addr: self.addr, stream: Some(s), session_tag: 0, _state: PhantomData })
    }
}

impl WireClient<Handshaking> {
    pub fn finish_handshake(mut self, token: &[u8; 16]) -> io::Result<WireClient<Authenticated>> {
        let s = self.stream.as_mut().expect("connected in Handshaking");
        s.write_all(token)?;
        let mut ack = [0u8; 8];
        s.read_exact(&mut ack)?;
        Ok(WireClient {
            addr: self.addr,
            stream: self.stream,
            session_tag: u64::from_be_bytes(ack),
            _state: PhantomData,
        })
    }
}

impl WireClient<Authenticated> {
    pub fn session_tag(&self) -> u64 { self.session_tag }

    pub fn send_command(&mut self, frame: &[u8]) -> io::Result<()> {
        let s = self.stream.as_mut().expect("connected in Authenticated");
        let len = (frame.len() as u32).to_be_bytes();
        s.write_all(&len)?;
        s.write_all(frame)
    }
}
