use std::future::Future;
use std::time::Duration;
use tokio::time::sleep;

pub async fn hedged_call<T, E, F1, F2, Fut1, Fut2>(
    hedge_delay: Duration,
    primary: F1,
    backup: F2,
) -> Result<T, E>
where
    F1: FnOnce() -> Fut1,
    F2: FnOnce() -> Fut2,
    Fut1: Future<Output = Result<T, E>>,
    Fut2: Future<Output = Result<T, E>>,
{
    let fut1 = primary();
    tokio::pin!(fut1);

    let first_err: Option<E> = tokio::select! {
        biased;
        res1 = &mut fut1 => match res1 {
            Ok(val) => return Ok(val),
            Err(err) => Some(err),
        },
        _ = sleep(hedge_delay) => None,
    };

    let fut2 = backup();
    if first_err.is_some() {
        return fut2.await;
    }
    tokio::pin!(fut2);

    tokio::select! {
        res1 = &mut fut1 => match res1 {
            Ok(val) => Ok(val),
            Err(_) => fut2.await,
        },
        res2 = &mut fut2 => match res2 {
            Ok(val) => Ok(val),
            Err(_) => fut1.await,
        },
    }
}
