func jsonKind(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	default:
		return "unknown"
	}
}

func main() {
	in := os.Stdin
	if len(os.Args) > 1 && os.Args[1] != "-" {
		f, err := os.Open(os.Args[1])
		if err != nil {
			os.Exit(2)
		}
		defer f.Close()
		in = f
	}

	sc := bufio.NewScanner(in)
	sc.Buffer(make([]byte, 64*1024), 16*1024*1024)
	fields := make(map[string]*FieldStat)
	rows, bad := 0, 0

	for sc.Scan() {
		line := sc.Bytes()
		if len(line) == 0 {
			continue
		}
		var obj map[string]any
		if err := json.Unmarshal(line, &obj); err != nil {
			bad++
			continue
		}
		rows++
		for k, v := range obj {
			st := fields[k]
			if st == nil {
				st = &FieldStat{seen: make(map[string]struct{})}
				fields[k] = st
			}
			st.Count++
			st.seen[jsonKind(v)] = struct{}{}
		}
	}

	for _, st := range fields {
		for t := range st.seen {
			st.Types = append(st.Types, t)
		}
