const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const REV = new Int8Array(128).fill(-1);
for (let i = 0; i < B64.length; i++) REV[B64.charCodeAt(i)] = i;

export function encodeVlq(value: number): string {
  let vlq = value < 0 ? ((-value) << 1) | 1 : value << 1;
  let out = "";
  do {
    let digit = vlq & 0x1f;
    vlq >>>= 5;
    if (vlq > 0) digit |= 0x20;
    out += B64[digit];
  } while (vlq > 0);
  return out;
}

export function encodeVlqSegment(deltas: readonly number[]): string {
  let res = "";
  for (const d of deltas) res += encodeVlq(d);
  return res;
}

export function decodeVlqSegment(segment: string): number[] {
  const out: number[] = [];
  let i = 0;
  while (i < segment.length) {
    let acc = 0;
    let shift = 0;
    let digit = 0;
    do {
      if (i >= segment.length) throw new SyntaxError("truncated VLQ");
