```rust
use std::marker::PhantomData;
use std::mem::{self, MaybeUninit};
use std::sync::atomic::{fence, AtomicU8, AtomicUsize, Ordering};

pub struct SeqLock<T: Copy> {
    seq: AtomicUsize,
    bytes: Box<[AtomicU8]>,
    _marker: PhantomData<T>,
}

unsafe impl<T: Copy + Send> Send for SeqLock<T> {}
unsafe impl<T: Copy + Send + Sync> Sync for SeqLock<T> {}

impl<T: Copy> SeqLock<T> {
    pub fn new(val: T) -> Self {
        let size = mem::size_of::<T>();
        let src = unsafe {
            std::slice::from_raw_parts((&val as *const T).cast::<MaybeUninit<u8>>(), size)
        };
        let bytes = src
            .iter()
            .map(|b| AtomicU8::new(unsafe { b.assume_init() }))
            .collect::<Vec<_>>()
            .into_boxed_slice();
        Self { seq: AtomicUsize::new(0), bytes, _marker: PhantomData }
    }

    /// Caller must serialize writers (single-writer contract).
    pub fn write(&mut self, val: T) {
        let s = self.seq.load(Ordering::Relaxed);
        self.seq.store(s.wrapping_add(1), Ordering::Release);
        fence(Ordering::AcqRel);
        let src = unsafe {
            std::slice::from_raw_parts((&val as *const T).cast::<MaybeUninit<u8>>(), self.bytes.len())
        };
        for (dst, b) in self.bytes.iter().zip(src.iter()) {
            dst.store(unsafe { b.assume_init() }, Ordering::Relaxed);
        }
        self.seq.store(s.wrapping_add(2), Ordering::Release);
    }

    pub fn read(&self) -> T {
        loop {
            let s1 = self.seq.load(Ordering::Acquire);
            if (s1 & 1) != 0 {
                std::hint::spin_loop();
                continue;
            }
            let mut raw = MaybeUninit::<T>::uninit();
            let dst = unsafe {
                std::slice::from_raw_parts_mut(raw.as_mut_ptr().cast::<u8>(), self.bytes.len())
            };
            for (out, cell) in dst.iter_mut().zip(self.bytes.iter()) {
                *out = cell.load(Ordering::Relaxed);
            }
            fence(Ordering::Acquire);
            if self.seq.load(Ordering::Relaxed) == s1 {
                return unsafe { raw.assume_init() };
            }
        }
    }
}
