import random
import pytest


def eval_ast(node: tuple, env: dict[str, int]) -> int:
    match node:
        case ("const", n): return n
        case ("var", k): return env[k]
        case ("add", a, b): return eval_ast(a, env) + eval_ast(b, env)
        case ("mul", a, b): return eval_ast(a, env) * eval_ast(b, env)
        case ("ifz", c, t, f): return eval_ast(t, env) if eval_ast(c, env) == 0 else eval_ast(f, env)
    raise ValueError(node)


def optimize(node: tuple) -> tuple:
    match node:
        case ("const", _) | ("var", _):
            return node
        case ("add", a, b):
            oa, ob = optimize(a), optimize(b)
            if oa[0] == "const" and ob[0] == "const": return ("const", oa[1] + ob[1])
            if oa == ("const", 0): return ob
            if ob == ("const", 0): return oa
            return ("add", oa, ob)
        case ("mul", a, b):
            oa, ob = optimize(a), optimize(b)
            if oa[0] == "const" and ob[0] == "const": return ("const", oa[1] * ob[1])
            if oa == ("const", 0) or ob == ("const", 0): return ("const", 0)
            if oa == ("const", 1): return ob
            if ob == ("const", 1): return oa
            return ("mul", oa, ob)
        case ("ifz", c, t, f):
            oc, ot, of_ = optimize(c), optimize(t), optimize(f)
            if oc[0] == "const": return ot if oc[1] == 0 else of_
            return ot if ot == of_ else ("ifz", oc, ot, of_)
    raise ValueError(node)


def size_ast(node: tuple) -> int:
    return 1 + sum(size_ast(ch) for ch in node[1:] if isinstance(ch, tuple))


def gen_ast(rng: random.Random, depth: int) -> tuple:
    if depth <= 0 or rng.random() < 0.3:
        return ("const", rng.choice([0, 1, 2, -3])) if rng.random() < 0.6 else ("var", rng.choice(["x", "y"]))
    op = rng.choice(["add", "mul", "ifz"])
    if op == "ifz":
        return ("ifz", gen_ast(rng, depth - 1), gen_ast(rng, depth - 1), gen_ast(rng, depth - 1))
    return (op, gen_ast(rng, depth - 1), gen_ast(rng, depth - 1))


