    tree = gen_ast(rng, depth=4)
    folded = optimize(tree)
    assert size_ast(folded) <= size_ast(tree)
    for env in ({"x": 0, "y": 5}, {"x": -2, "y": 0}, {"x": 7, "y": -3}):
