#include <sys/uio.h>
#include <cerrno>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <vector>

class RingSendBuf {
    std::vector<uint8_t> buf_;
    size_t head_ = 0;
    size_t len_ = 0;

public:
    explicit RingSendBuf(size_t capacity) : buf_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    size_t size() const noexcept { return len_; }
    size_t writable() const noexcept { return buf_.size() - len_; }

    size_t enqueue(const uint8_t* src, size_t n) noexcept {
        const size_t take = n < writable() ? n : writable();
        const size_t cap = buf_.size();
        const size_t write_pos = (head_ + len_) % cap;
        const size_t first = take < (cap - write_pos) ? take : (cap - write_pos);
        std::memcpy(buf_.data() + write_pos, src, first);
        if (take > first) {
            std::memcpy(buf_.data(), src + first, take - first);
        }
        len_ += take;
        return take;
    }

    // Returns bytes flushed (>=0), or -1 on fatal errno (0 when EAGAIN/would-block).
    ssize_t flush_fd(int fd) noexcept {
        if (len_ == 0) return 0;
        const size_t cap = buf_.size();
        const size_t first = len_ < (cap - head_) ? len_ : (cap - head_);
        iovec iov[2]{};
        iov[0].iov_base = buf_.data() + head_;
        iov[0].iov_len = first;
        int iovcnt = 1;
        if (len_ > first) {
            iov[1].iov_base = buf_.data();
            iov[1].iov_len = len_ - first;
            iovcnt = 2;
        }

        for (;;) {
            const ssize_t sent = ::writev(fd, iov, iovcnt);
            if (sent >= 0) {
                head_ = (head_ + static_cast<size_t>(sent)) % cap;
                len_ -= static_cast<size_t>(sent);
                return sent;
            }
            if (errno == EINTR) continue;
            if (errno == EAGAIN || errno == EWOULDBLOCK) return 0;
            return -1;
        }
    }
};
