export class SoATelemetryRing {
  private readonly cap: number;
  private readonly tsCol: Float64Array;
  private readonly tenantCol: Uint32Array;
  private readonly latencyCol: Float64Array;
  private readonly scratch: Float64Array;
  private writeIdx = 0;
  private count = 0;

  constructor(capacity: number) {
    if (capacity <= 0) throw new RangeError("capacity must be > 0");
    this.cap = capacity;
    this.tsCol = new Float64Array(capacity);
    this.tenantCol = new Uint32Array(capacity);
    this.latencyCol = new Float64Array(capacity);
    this.scratch = new Float64Array(capacity);
  }

  record(ts: number, tenantId: number, latencyMs: number): void {
    const i = this.writeIdx;
    this.tsCol[i] = ts;
    this.tenantCol[i] = tenantId >>> 0;
    this.latencyCol[i] = latencyMs;
    this.writeIdx = i + 1 === this.cap ? 0 : i + 1;
    if (this.count < this.cap) this.count++;
  }

  p95LatencySince(tenantId: number, minTs: number): number {
    const target = tenantId >>> 0;
    let matched = 0;
    for (let i = 0; i < this.count; i++) {
      if (this.tenantCol[i] === target && this.tsCol[i] >= minTs) {
        this.scratch[matched++] = this.latencyCol[i];
      }
    }
    if (matched === 0) return NaN;
    const view = this.scratch.subarray(0, matched);
    view.sort();
    const rank = Math.min(matched - 1, Math.ceil(0.95 * matched) - 1);
    return view[rank];
  }
}
