```rust
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Pat {
    Wild,
    Bool(bool),
    Pair(Box<Pat>, Box<Pat>),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ctor {
    Bool(bool),
    Pair,
}

fn specialize_pat(p: &Pat, ctor: Ctor) -> Option<Vec<Pat>> {
    match (p, ctor) {
        (Pat::Wild, Ctor::Bool(_)) => Some(vec![]),
        (Pat::Wild, Ctor::Pair) => Some(vec![Pat::Wild, Pat::Wild]),
        (Pat::Bool(b1), Ctor::Bool(b2)) if *b1 == b2 => Some(vec![]),
        (Pat::Pair(a, b), Ctor::Pair) => Some(vec![(**a).clone(), (**b).clone()]),
        _ => None,
    }
}

fn specialize_matrix(matrix: &[Vec<Pat>], ctor: Ctor) -> Vec<Vec<Pat>> {
    matrix
        .iter()
        .filter_map(|row| {
            let mut head = specialize_pat(&row[0], ctor)?;
            head.extend_from_slice(&row[1..]);
            Some(head)
        })
        .collect()
}

pub fn is_useful(matrix: &[Vec<Pat>], q: &[Pat]) -> bool {
    if q.is_empty() {
        return matrix.is_empty();
    }
    let step = |c: Ctor| {
        let mut sq = specialize_pat(&q[0], c).unwrap();
        sq.extend_from_slice(&q[1..]);
        is_useful(&specialize_matrix(matrix, c), &sq)
    };
    match &q[0] {
        Pat::Bool(b) => step(Ctor::Bool(*b)),
        Pat::Pair(_, _) => step(Ctor::Pair),
        Pat::Wild => {
            let has_pair = matrix.iter().any(|r| matches!(r[0], Pat::Pair(_, _)));
            if has_pair {
                step(Ctor::Pair)
            } else {
                step(Ctor::Bool(true)) || step(Ctor::Bool(false))
            }
        }
    }
}

pub fn check_match(arms: &[Pat]) -> (Vec<usize>, bool) {
    let mut seen: Vec<Vec<Pat>> = Vec::new();
    let mut redundant = Vec::new();
    for (idx, arm) in arms.iter().enumerate() {
        let row = vec![arm.clone()];
        if is_useful(&seen, &row) {
            seen.push(row);
        } else {
            redundant.push(idx);
        }
    }
    let exhaustive = !is_useful(&seen, &[Pat::Wild]);
    (redundant, exhaustive)
}
