```typescript
interface LockState {
  readers: number;
  writer: boolean;
  readQueue: Array<() => void>;
  writeQueue: Array<() => void>;
}

export class KeyedRWLock<K> {
  private readonly locks = new Map<K, LockState>();

  private getOrCreate(key: K): LockState {
    let st = this.locks.get(key);
    if (!st) {
      st = { readers: 0, writer: false, readQueue: [], writeQueue: [] };
      this.locks.set(key, st);
    }
    return st;
  }

  private releaseOrGc(key: K, st: LockState): void {
    if (!st.writer && st.readers === 0) {
      const nextWriter = st.writeQueue.shift();
      if (nextWriter) {
        st.writer = true;
        nextWriter();
        return;
      }
      if (st.readQueue.length > 0) {
        const batch = st.readQueue.splice(0);
        st.readers = batch.length;
        for (const wake of batch) wake();
        return;
      }
      this.locks.delete(key);
    }
  }

  async withRead<T>(key: K, fn: () => Promise<T> | T): Promise<T> {
    const st = this.getOrCreate(key);
    if (st.writer || st.writeQueue.length > 0) {
      await new Promise<void>((resolve) => st.readQueue.push(resolve));
    } else {
      st.readers++;
    }
    try {
      return await fn();
    } finally {
      st.readers--;
      this.releaseOrGc(key, st);
    }
  }

  async withWrite<T>(key: K, fn: () => Promise<T> | T): Promise<T> {
    const st = this.getOrCreate(key);
    if (st.writer || st.readers > 0) {
      await new Promise<void>((resolve) => st.writeQueue.push(resolve));
    } else {
      st.writer = true;
    }
    try {
      return await fn();
    } finally {
      st.writer = false;
      this.releaseOrGc(key, st);
    }
  }
}
