package semver

import (
	"errors"
	"strconv"
	"strings"
)

type Version struct {
	Major, Minor, Patch uint64
	Pre                 []string
	Build               string
}

func Parse(raw string) (Version, error) {
	s := strings.TrimPrefix(strings.TrimSpace(raw), "v")
	var v Version
	if base, b, ok := strings.Cut(s, "+"); ok {
		if b == "" { return v, errors.New("empty build metadata") }
		v.Build, s = b, base
	}
	if core, pre, ok := strings.Cut(s, "-"); ok {
		if pre == "" { return v, errors.New("empty prerelease") }
		v.Pre, s = strings.Split(pre, "."), core
	}
	parts := strings.Split(s, ".")
	if len(parts) != 3 { return v, errors.New("expected MAJOR.MINOR.PATCH") }
	var err error
	if v.Major, err = strconv.ParseUint(parts[0], 10, 64); err != nil { return v, err }
	if v.Minor, err = strconv.ParseUint(parts[1], 10, 64); err != nil { return v, err }
	if v.Patch, err = strconv.ParseUint(parts[2], 10, 64); err != nil { return v, err }
	return v, nil
}

func cmpUint(a, b uint64) int {
	if a < b { return -1 }
	if a > b { return 1 }
	return 0
}

func Compare(a, b Version) int {
	if c := cmpUint(a.Major, b.Major); c != 0 { return c }
	if c := cmpUint(a.Minor, b.Minor); c != 0 { return c }
	if c := cmpUint(a.Patch, b.Patch); c != 0 { return c }
	if len(a.Pre) == 0 && len(b.Pre) == 0 { return 0 }
	if len(a.Pre) == 0 { return 1 }
	if len(b.Pre) == 0 { return -1 }
	for i := 0; i < len(a.Pre) && i < len(b.Pre); i++ {
		if a.Pre[i] == b.Pre[i] { continue }
		ai, aErr := strconv.ParseUint(a.Pre[i], 10, 64)
		bi, bErr := strconv.ParseUint(b.Pre[i], 10, 64)
		if aErr == nil && bErr == nil { return cmpUint(ai, bi) }
		if aErr == nil { return -1 }
		if bErr == nil { return 1 }
		return strings.Compare(a.Pre[i], b.Pre[i])
	}
	return cmpUint(uint64(len(a.Pre)), uint64(len(b.Pre)))
}

func SatisfiesCaret(cand, req Version) bool {
	if Compare(cand, req) < 0 { return false }
	if len(cand.Pre) > 0 && (cand.Major != req.Major || cand.Minor != req.Minor || cand.Patch != req.Patch) {
		return false
	}
	if req.Major > 0 { return cand.Major == req.Major }
	if req.Minor > 0 { return cand.Major == 0 && cand.Minor == req.Minor }
	return cand.Major == 0 && cand.Minor == 0 && cand.Patch == req.Patch
}
