package bitmap

import (
	"math/bits"
	"sort"
)

const arrayCutoff = 4096

type chunk struct {
	key   uint16
	array []uint16
	bits  *[1024]uint64
}

func (c *chunk) add(lo uint16) {
	if c.bits != nil {
		c.bits[lo>>6] |= 1 << (lo & 63)
		return
	}
	i := sort.Search(len(c.array), func(idx int) bool { return c.array[idx] >= lo })
	if i < len(c.array) && c.array[i] == lo {
		return
	}
	c.array = append(c.array, 0)
	copy(c.array[i+1:], c.array[i:])
	c.array[i] = lo
	if len(c.array) > arrayCutoff {
		b := new([1024]uint64)
		for _, v := range c.array {
			b[v>>6] |= 1 << (v & 63)
		}
		c.bits, c.array = b, nil
	}
}

func (c *chunk) contains(lo uint16) bool {
	if c.bits != nil {
		return (c.bits[lo>>6] & (1 << (lo & 63))) != 0
	}
	i := sort.Search(len(c.array), func(idx int) bool { return c.array[idx] >= lo })
	return i < len(c.array) && c.array[i] == lo
}

type HybridBitmap struct {
	chunks []chunk
}

func (b *HybridBitmap) Add(x uint32) {
	hi, lo := uint16(x>>16), uint16(x)
	i := sort.Search(len(b.chunks), func(idx int) bool { return b.chunks[idx].key >= hi })
	if i == len(b.chunks) || b.chunks[i].key != hi {
		b.chunks = append(b.chunks, chunk{})
		copy(b.chunks[i+1:], b.chunks[i:])
		b.chunks[i] = chunk{key: hi}
	}
	b.chunks[i].add(lo)
}

func (b *HybridBitmap) Contains(x uint32) bool {
	hi, lo := uint16(x>>16), uint16(x)
	i := sort.Search(len(b.chunks), func(idx int) bool { return b.chunks[idx].key >= hi })
	return i < len(b.chunks) && b.chunks[i].key == hi && b.chunks[i].contains(lo)
}

func AndCount(a, b *HybridBitmap) int {
	i, j, total := 0, 0, 0
	for i < len(a.chunks) && j < len(b.chunks) {
		ca, cb := &a.chunks[i], &b.chunks[j]
		if ca.key < cb.key { i++; continue }
		if ca.key > cb.key { j++; continue }
		switch {
		case ca.bits != nil && cb.bits != nil:
			for w := 0; w < 1024; w++ { total += bits.OnesCount64(ca.bits[w] & cb.bits[w]) }
		case ca.bits != nil:
			for _, v := range cb.array { if ca.contains(v) { total++ } }
		case cb.bits != nil:
			for _, v := range ca.array { if cb.contains(v) { total++ } }
		default:
			p, q := 0, 0
			for p < len(ca.array) && q < len(cb.array) {
				if ca.array[p] == cb.array[q] { total++; p++; q++ } else if ca.array[p] < cb.array[q] { p++ } else { q++ }
			}
		}
		i++; j++
	}
	return total
}
