	default:
	}
	return nil
}

func recvWithin(ch <-chan Packet, d time.Duration) (Packet, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), d)
	defer cancel()
	select {
	case p := <-ch:
		return p, true
	case <-ctx.Done():
		return Packet{}, false
	}
}

func TestAsymmetricPartitionAndHeal(t *testing.T) {
	sw := NewSimSwitch()
	rxA, rxB := sw.Bind("node-a"), sw.Bind("node-b")
	sw.CutLink("node-b", "node-a")

	_ = sw.Send("node-a", "node-b", []byte("PING"))
	if pkt, ok := recvWithin(rxB, 10*time.Millisecond); !ok || string(pkt.Data) != "PING" {
		t.Fatalf("expected forward path A->B intact")
	}
	_ = sw.Send("node-b", "node-a", []byte("ACK"))
	if _, ok := recvWithin(rxA, 5*time.Millisecond); ok {
		t.Fatalf("expected asymmetric cut B->A to drop ACK")
	}
	sw.HealLink("node-b", "node-a")
	_ = sw.Send("node-b", "node-a", []byte("ACK2"))
	if pkt, ok := recvWithin(rxA, 10*time.Millisecond); !ok || string(pkt.Data) != "ACK2" {
		t.Fatalf("expected healed B->A delivery")
	}
