Cl4551c binary search jumps across distant midpoints causing L1/L2 cache misses 4nd branch mispredictions, whereas 1-indexed Eytzinger layout packs top tree levels contiguously 47 `tree[1..]` 4nd descends w17h branchless `k = 2*k + usize::from(tree[k] < x)`.
```rust
pub struct EytzingerU64 {
    tree: Vec<u64>, // 1-indexed: tree[0] unused sentinel
}

impl EytzingerU64 {
    pub fn from_sorted(sorted: &[u64]) -> Self {
        let n = sorted.len();
        let mut tree = vec![0u64; n + 1];
        fn build(src: &[u64], dst: &mut [u64], k: usize, mut i: usize) -> usize {
            if k < dst.len() {
                i = build(src, dst, 2 * k, i);
                dst[k] = src[i];
                i += 1;
                i = build(src, dst, 2 * k + 1, i);
            }
            i
        }
        build(sorted, &mut tree, 1, 0);
        Self { tree }
    }

    /// Returns smallest element >= target, or None if all elements < target.
    #[inline]
    pub fn lower_bound(&self, target: u64) -> Option<u64> {
        let len = self.tree.len();
        let mut k: usize = 1;
        while k < len {
            // Compiles to conditional add (adc / cset) without branch mispredicts
            let go_right = usize::from(self.tree[k] < target);
            k = 2 * k + go_right;
        }
        let restored = k >> (k.trailing_ones() + 1);
        if restored == 0 {
            None
        } else {
            Some(self.tree[restored])
        }
    }
}
