```python
from collections import deque


def rpo_order(entry: str, succs: dict[str, list[str]]) -> list[str]:
    seen: set[str] = set()
    post: list[str] = []
    def dfs(u: str) -> None:
        seen.add(u)
        for v in succs.get(u, ()):
            if v not in seen:
                dfs(v)
        post.append(u)
    dfs(entry)
    post.reverse()
    return post


def compute_idoms_and_df(entry: str, succs: dict[str, list[str]]) -> tuple[dict[str, str], dict[str, set[str]]]:
    rpo = rpo_order(entry, succs)
    rank = {b: i for i, b in enumerate(rpo)}
    preds: dict[str, list[str]] = {b: [] for b in rpo}
    for u in rpo:
        for v in succs.get(u, ()):
            if v in preds:
                preds[v].append(u)

    idom: dict[str, str] = {entry: entry}
    def intersect(b1: str, b2: str) -> str:
        while b1 != b2:
            while rank[b1] > rank[b2]: b1 = idom[b1]
            while rank[b2] > rank[b1]: b2 = idom[b2]
        return b1

    changed = True
    while changed:
        changed = False
        for b in rpo[1:]:
            ready = [p for p in preds[b] if p in idom]
            new_idom = ready[0]
            for p in ready[1:]:
                new_idom = intersect(p, new_idom)
            if idom.get(b) != new_idom:
                idom[b] = new_idom
                changed = True

    df: dict[str, set[str]] = {b: set() for b in rpo}
    for b in rpo:
        if len(preds[b]) >= 2:
            for p in preds[b]:
                runner = p
                while runner != idom[b]:
                    df[runner].add(b)
                    runner = idom[runner]
    return idom, df


def place_phi_nodes(entry: str, succs: dict[str, list[str]], defs: dict[str, set[str]]) -> dict[str, set[str]]:
    _, df = compute_idoms_and_df(entry, succs)
    phis: dict[str, set[str]] = {b: set() for b in df}
    for var, def_blocks in defs.items():
        placed: set[str] = set()
        ever_queued = set(def_blocks)
        work = deque(def_blocks)
        while work:
            x = work.popleft()
            for y in df.get(x, ()):
                if y not in placed:
                    phis[y].add(var)
                    placed.add(y)
                    if y not in ever_queued:
                        ever_queued.add(y)
                        work.append(y)
    return phis
