```go
package swr

import (
	"context"
	"sync"
	"time"
)

type call[V any] struct {
	done chan struct{}
	val  V
	err  error
}

type item[V any] struct {
	val        V
	freshUntil time.Time
	staleUntil time.Time
}

type SWRCache[K comparable, V any] struct {
	mu          sync.Mutex
	items       map[K]item[V]
	inflight    map[K]*call[V]
	freshTTL    time.Duration
	staleWindow time.Duration
	bgTimeout   time.Duration
}

func NewSWRCache[K comparable, V any](freshTTL, staleWindow, bgTimeout time.Duration) *SWRCache[K, V] {
	return &SWRCache[K, V]{
		items:       make(map[K]item[V]),
		inflight:    make(map[K]*call[V]),
		freshTTL:    freshTTL,
		staleWindow: staleWindow,
		bgTimeout:   bgTimeout,
	}
}

func (c *SWRCache[K, V]) startFetchLocked(ctx context.Context, key K, loader func(context.Context, K) (V, error)) *call[V] {
	if existing, ok := c.inflight[key]; ok {
		return existing
	}
	cx := &call[V]{done: make(chan struct{})}
	c.inflight[key] = cx
	go func() {
		v, err := loader(ctx, key)
		now := time.Now()
		c.mu.Lock()
		if err == nil {
			c.items[key] = item[V]{val: v, freshUntil: now.Add(c.freshTTL), staleUntil: now.Add(c.freshTTL + c.staleWindow)}
		}
		cx.val, cx.err = v, err
		delete(c.inflight, key)
		c.mu.Unlock()
		close(cx.done)
	}()
	return cx
}

func (c *SWRCache[K, V]) Get(ctx context.Context, key K, loader func(context.Context, K) (V, error)) (V, error) {
	now := time.Now()
	c.mu.Lock()
	if ent, ok := c.items[key]; ok && now.Before(ent.staleUntil) {
		if now.After(ent.freshUntil) && c.inflight[key] == nil {
			bgCtx, cancel := context.WithTimeout(context.Background(), c.bgTimeout)
			cx := c.startFetchLocked(bgCtx, key, loader)
			go func() { <-cx.done; cancel() }()
		}
		c.mu.Unlock()
		return ent.val, nil
	}
	cx := c.startFetchLocked(ctx, key, loader)
	c.mu.Unlock()

	select {
	case <-ctx.Done():
		var zero V
		return zero, ctx.Err()
	case <-cx.done:
		return cx.val, cx.err
	}
}
