```typescript
#!/usr/bin/env node
import { createInterface } from "node:readline";
import { parseArgs } from "node:util";

const SUB_BITS = 4;
const SUB_COUNT = 1 << SUB_BITS; // 16 sub-bins per octave
const NUM_BINS = (32 - SUB_BITS + 1) * SUB_COUNT;

function bucketIndex(us: number): number {
  const v = Math.max(0, Math.min(0xffffffff, Math.floor(us)));
  if (v < SUB_COUNT) return v;
  const msb = 31 - Math.clz32(v);
  const octave = msb - SUB_BITS;
  const sub = (v >>> octave) & (SUB_COUNT - 1);
  return (octave + 1) * SUB_COUNT + sub;
}

function bucketUpperUs(idx: number): number {
  if (idx < SUB_COUNT) return idx;
  const octave = Math.floor(idx / SUB_COUNT) - 1;
  const sub = idx % SUB_COUNT;
  return ((SUB_COUNT + sub + 1) * 2 ** octave) - 1;
}

function quantileFromBins(bins: Float64Array, total: number, q: number): number {
  if (total === 0) return 0;
  const rank = Math.ceil(total * q);
  let seen = 0;
  for (let i = 0; i < bins.length; i++) {
    seen += bins[i];
    if (seen >= rank) return bucketUpperUs(i);
  }
  return 0;
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      col: { type: "string", short: "c", default: "1" },
      delim: { type: "string", short: "d", default: "\t" },
    },
  });
  const colIdx = Math.max(0, Number(values.col) - 1);
  const delim = values.delim!;
  const bins = new Float64Array(NUM_BINS);
  let count = 0;
  let maxUs = 0;

  const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line) continue;
    const raw = line.split(delim)[colIdx];
    const val = Number(raw);
    if (!Number.isFinite(val) || val < 0) continue;
    bins[bucketIndex(val)] += 1;
    count += 1;
    if (val > maxUs) maxUs = val;
  }

  const p50 = quantileFromBins(bins, count, 0.50);
  const p95 = quantileFromBins(bins, count, 0.95);
  const p99 = quantileFromBins(bins, count, 0.99);
  console.log(JSON.stringify({ count, p50_us: p50, p95_us: p95, p99_us: p99, max_us: maxUs }));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
