#[derive(Debug, PartialEq, Eq)]
pub enum RespFrame<'a> {
    Simple(&'a [u8]),
    Error(&'a [u8]),
    Integer(i64),
    Bulk(Option<&'a [u8]>),
    Array(Option<Vec<RespFrame<'a>>>),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RespErr { BadPrefix, BadInt, BadBulkTerminator, NestingTooDeep }

fn read_line(buf: &[u8]) -> Option<(&[u8], usize)> {
    let cr = buf.windows(2).position(|w| w == b"\r\n")?;
    Some((&buf[..cr], cr + 2))
}

fn parse_i64(raw: &[u8]) -> Result<i64, RespErr> {
    std::str::from_utf8(raw).ok().and_then(|s| s.parse::<i64>().ok()).ok_or(RespErr::BadInt)
}

pub fn parse_resp<'a>(buf: &'a [u8]) -> Result<Option<(RespFrame<'a>, usize)>, RespErr> {
    parse_depth(buf, 0)
}

fn parse_depth<'a>(buf: &'a [u8], depth: usize) -> Result<Option<(RespFrame<'a>, usize)>, RespErr> {
    if depth > 16 { return Err(RespErr::NestingTooDeep); }
    let Some(&tag) = buf.first() else { return Ok(None) };
    let Some((line, hdr_end)) = read_line(&buf[1..]) else { return Ok(None) };
    let mut pos = 1 + hdr_end;

    match tag {
        b'+' => Ok(Some((RespFrame::Simple(line), pos))),
        b'-' => Ok(Some((RespFrame::Error(line), pos))),
        b':' => Ok(Some((RespFrame::Integer(parse_i64(line)?), pos))),
        b'$' => {
            let n = parse_i64(line)?;
            if n == -1 { return Ok(Some((RespFrame::Bulk(None), pos))); }
            let len = usize::try_from(n).map_err(|_| RespErr::BadInt)?;
            if buf.len() < pos + len + 2 { return Ok(None); }
            if &buf[pos + len..pos + len + 2] != b"\r\n" {
                return Err(RespErr::BadBulkTerminator);
            }
            Ok(Some((RespFrame::Bulk(Some(&buf[pos..pos + len])), pos + len + 2)))
        }
        b'*' => {
            let n = parse_i64(line)?;
            if n == -1 { return Ok(Some((RespFrame::Array(None), pos))); }
            let count = usize::try_from(n).map_err(|_| RespErr::BadInt)?;
            let mut items = Vec::with_capacity(count.min(64));
            for _ in 0..count {
                let Some((elem, used)) = parse_depth(&buf[pos..], depth + 1)? else { return Ok(None) };
                items.push(elem);
                pos += used;
            }
            Ok(Some((RespFrame::Array(Some(items)), pos)))
        }
        _ => Err(RespErr::BadPrefix),
    }
}
