package arena

const defaultSlabSize = 64 << 10 // 64 KiB

type ByteArena struct {
	slabSize int
	chunks   [][]byte
	cur      int
	off      int
}

func NewByteArena(slabSize int) *ByteArena {
	if slabSize <= 0 {
		slabSize = defaultSlabSize
	}
	return &ByteArena{
		slabSize: slabSize,
		chunks:   [][]byte{make([]byte, slabSize)},
	}
}

func (a *ByteArena) Alloc(n int) []byte {
	if n <= 0 {
		return nil
	}
	// Oversized requests get a dedicated exact-cap slice so standard slabs stay uniform.
	if n > a.slabSize {
		return make([]byte, n)
	}
	slab := a.chunks[a.cur]
	if a.off+n > len(slab) {
		a.cur++
		a.off = 0
		if a.cur >= len(a.chunks) {
			a.chunks = append(a.chunks, make([]byte, a.slabSize))
		}
		slab = a.chunks[a.cur]
	}
	start := a.off
	end := start + n
	a.off = end
	clear(slab[start:end])
	return slab[start:end:end]
}

func (a *ByteArena) CopyBytes(src []byte) []byte {
	if len(src) == 0 {
		return nil
	}
	dst := a.Alloc(len(src))
	copy(dst, src)
	return dst
}

func (a *ByteArena) Reset() {
	a.cur = 0
	a.off = 0
}
