use std::io;
use std::net::UdpSocket;

const MAGIC: u16 = 0x544D; // "TM"
const PKT_HDR_LEN: usize = 12; // u16 magic + u64 seq + u16 count
const SAFE_UDP_MTU: usize = 1200;

#[derive(Debug)]
pub enum BatchErr {
    RecordExceedsMtu(usize),
    Io(io::Error),
}

impl From<io::Error> for BatchErr {
    fn from(e: io::Error) -> Self { Self::Io(e) }
}

pub struct UdpFrameBatcher {
    sock: UdpSocket,
    buf: Vec<u8>,
    seq: u64,
    count: u16,
}

impl UdpFrameBatcher {
    pub fn new(sock: UdpSocket) -> Self {
        let mut b = Self {
            sock,
            buf: Vec::with_capacity(SAFE_UDP_MTU),
            seq: 0,
            count: 0,
        };
        b.reset_header();
        b
    }

    fn reset_header(&mut self) {
        self.buf.clear();
        self.buf.extend_from_slice(&MAGIC.to_be_bytes());
        self.buf.extend_from_slice(&0u64.to_be_bytes());
        self.buf.extend_from_slice(&0u16.to_be_bytes());
        self.count = 0;
    }

    pub fn push(&mut self, record: &[u8]) -> Result<(), BatchErr> {
        let framed_len = 2 + record.len();
        if PKT_HDR_LEN + framed_len > SAFE_UDP_MTU {
            return Err(BatchErr::RecordExceedsMtu(record.len()));
        }
        if self.buf.len() + framed_len > SAFE_UDP_MTU || self.count == u16::MAX {
            self.flush()?;
        }
        self.buf.extend_from_slice(&(record.len() as u16).to_be_bytes());
        self.buf.extend_from_slice(record);
        self.count += 1;
        Ok(())
    }

    pub fn flush(&mut self) -> Result<usize, BatchErr> {
        if self.count == 0 {
            return Ok(0);
        }
        self.buf[2..10].copy_from_slice(&self.seq.to_be_bytes());
        self.buf[10..12].copy_from_slice(&self.count.to_be_bytes());
        let sent = self.sock.send(&self.buf)?;
        self.seq = self.seq.wrapping_add(1);
        self.reset_header();
        Ok(sent)
    }
}
