#include <cstddef>
#include <cstdint>
#include <utility>
#include <vector>

template <typename V>
class RobinHoodU64Map {
    using u64 = std::uint64_t;
    struct Bucket { u64 key{}; V val{}; std::uint32_t psl{0}; };

    std::vector<Bucket> table_;
    std::size_t size_{0};

    static u64 mix64(u64 x) noexcept {
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    void rehash(std::size_t cap) {
        std::vector<Bucket> old = std::move(table_);
        table_.assign(cap, Bucket{});
        size_ = 0;
        for (auto& b : old) if (b.psl != 0) insert_or_assign(b.key, std::move(b.val));
    }

public:
    explicit RobinHoodU64Map(std::size_t init_pow2 = 64) : table_(init_pow2) {}

    void insert_or_assign(u64 key, V value) {
        if ((size_ + 1) * 10 >= table_.size() * 8) rehash(table_.size() * 2);
        const std::size_t mask = table_.size() - 1;
        std::size_t idx = mix64(key) & mask;
        Bucket cur{key, std::move(value), 1};

        for (;; ++cur.psl, idx = (idx + 1) & mask) {
            Bucket& slot = table_[idx];
            if (slot.psl == 0) { slot = std::move(cur); ++size_; return; }
            if (slot.key == cur.key) { slot.val = std::move(cur.val); return; }
            if (cur.psl > slot.psl) std::swap(cur, slot);
        }
    }

    [[nodiscard]] V* find(u64 key) noexcept {
        const std::size_t mask = table_.size() - 1;
        std::size_t idx = mix64(key) & mask;
        for (std::uint32_t d = 1; ; ++d, idx = (idx + 1) & mask) {
            Bucket& slot = table_[idx];
            if (slot.psl < d) return nullptr;
            if (slot.key == key) return &slot.val;
        }
    }

    bool erase(u64 key) noexcept {
        const std::size_t mask = table_.size() - 1;
        std::size_t idx = mix64(key) & mask;
        for (std::uint32_t d = 1; ; ++d, idx = (idx + 1) & mask) {
            if (table_[idx].psl < d) return false;
            if (table_[idx].key == key) break;
        }
        for (;;) {
            std::size_t next = (idx + 1) & mask;
            if (table_[next].psl <= 1) { table_[idx] = Bucket{}; --size_; return true; }
            table_[idx] = std::move(table_[next]);
            --table_[idx].psl;
            idx = next;
        }
    }
};
