type Simplify<T> = { [K in keyof T]: T[K] };

type SegmentParam<S extends string> =
  S extends `:${infer Name}` ? { [K in Name]: string | number } :
  S extends `*${infer Wild}` ? { [K in (Wild extends "" ? "wildcard" : Wild)]: string } :
  {};

type ParseSegments<Path extends string> =
  Path extends `${infer Head}/${infer Tail}`
    ? SegmentParam<Head> & ParseSegments<Tail>
    : SegmentParam<Path>;

type StripLeadingSlash<P extends string> = P extends `/${infer Rest}` ? Rest : P;

export type RouteParams<Path extends string> = Simplify<ParseSegments<StripLeadingSlash<Path>>>;

export function buildRoute<P extends string>(
  pattern: P,
  ...args: keyof RouteParams<P> extends never ? [] : [params: RouteParams<P>]
): string {
  const params = (args[0] ?? {}) as Record<string, string | number>;
  const leading = pattern.startsWith("/") ? "/" : "";
  const rawBody = leading ? pattern.slice(1) : pattern;
  if (rawBody === "") return leading || "/";

  const rendered = rawBody.split("/").map((seg) => {
    if (seg.startsWith(":")) {
      const key = seg.slice(1);
      return encodeURIComponent(String(params[key]));
    }
    if (seg.startsWith("*")) {
      const key = seg.slice(1) || "wildcard";
      return String(params[key]).split("/").map(encodeURIComponent).join("/");
    }
    return seg;
  });
  return leading + rendered.join("/");
